INSERT INTO questions (question_text, option_a, option_b, option_c, option_d, correct_answer, category, difficulty, explanation) VALUES
  ('During a pre-trip inspection, what should you do with the vehicle inspection report left by the previous driver?', 'Throw it away and start fresh', 'Review it and sign it to acknowledge any defects noted', 'Only read it if the vehicle looks damaged', 'File it without reading', 'B', 'General Knowledge', 'medium', 'You must review the previous driver''s vehicle inspection report and sign it to acknowledge that you have seen it and that any defects noted have been certified as repaired or deemed unnecessary to repair.'),
  ('At 55 mph, what is the approximate total stopping distance for a commercial vehicle on dry pavement?', 'About 200 feet', 'About 300 feet', 'Over 450 feet', 'About 600 feet', 'C', 'General Knowledge', 'medium', 'At 55 mph the total stopping distance is over 450 feet, which includes perception distance (142 feet), reaction distance (61 feet), and braking distance (216 feet). These three distances combined exceed 450 feet.'),
  ('What is the legal blood alcohol concentration (BAC) limit for a CDL driver operating a commercial motor vehicle?', '0.08%', '0.06%', '0.02%', '0.04%', 'D', 'General Knowledge', 'medium', 'The legal BAC limit for CDL holders operating a commercial motor vehicle is 0.04%, which is half the limit for non-commercial drivers in most states.'),
  ('How far ahead do low beam headlights illuminate the road?', '100 feet', '250 feet', '400 feet', '500 feet', 'B', 'General Knowledge', 'medium', 'Low beam headlights illuminate the road approximately 250 feet ahead. This is important for night driving because you should always be able to stop within the distance you can see.'),
  ('What is the minimum fire extinguisher rating required for most commercial motor vehicles?', '2 A:B', '10 B:C', '5 B:C', '3 A:B:C', 'C', 'General Knowledge', 'medium', 'All commercial motor vehicles are required to carry a fire extinguisher with a minimum rating of 5 B:C or higher. The B:C rating means it is effective against flammable liquid and electrical fires.'),
  ('What happens to stopping distance on wet roads compared to dry roads?', 'It stays the same', 'It doubles', 'It triples', 'It increases by 25%', 'B', 'General Knowledge', 'medium', 'Wet roads can double your stopping distance. Reduced tire traction on wet pavement means it takes significantly longer to bring your vehicle to a complete stop, so you should reduce speed and increase following distance.'),
  ('At speeds below 40 mph, what is the recommended following distance rule for a commercial vehicle?', '1 second for every 5 feet of vehicle length', '1 second for every 10 feet of vehicle length', '2 seconds for every 10 feet of vehicle length', 'A flat 4 seconds regardless of vehicle length', 'B', 'General Knowledge', 'medium', 'At speeds below 40 mph, you should maintain at least 1 second of following distance for every 10 feet of vehicle length. For example, a 60-foot vehicle should maintain at least 6 seconds of following distance.'),
  ('When driving above 40 mph, how should you adjust the following distance rule?', 'No adjustment is needed', 'Add 1 additional second to the standard following distance', 'Double the entire following distance', 'Add 3 additional seconds', 'B', 'General Knowledge', 'medium', 'At speeds above 40 mph, you should add 1 additional second to the following distance calculated by the 1-second-per-10-feet rule. This extra second accounts for the increased stopping distance at higher speeds.'),
  ('At what speed can hydroplaning begin to occur?', '50 mph', '45 mph', '40 mph', '30 mph', 'D', 'General Knowledge', 'medium', 'Hydroplaning can occur at speeds as low as 30 mph when there is standing water on the road surface. When your tires lose contact with the road and ride on a film of water, you lose steering and braking control.'),
  ('What is the maximum legal weight allowed on a single axle?', '12,000 lbs', '20,000 lbs', '34,000 lbs', '40,000 lbs', 'B', 'General Knowledge', 'medium', 'The maximum weight generally allowed on a single axle is 20,000 lbs. Exceeding this limit can cause damage to roads and bridges and is a violation of federal weight regulations.'),
  ('What is the maximum legal weight allowed on a tandem axle?', '20,000 lbs', '34,000 lbs', '40,000 lbs', '44,000 lbs', 'B', 'General Knowledge', 'medium', 'The maximum weight generally allowed on a tandem axle is 34,000 lbs. Tandem axles distribute the load over a wider area, allowing for more weight than a single axle.'),
  ('What is the maximum gross vehicle weight generally allowed on public roads?', '60,000 lbs', '70,000 lbs', '80,000 lbs', '90,000 lbs', 'C', 'General Knowledge', 'medium', 'The maximum gross vehicle weight generally allowed on the Interstate highway system is 80,000 lbs. Some states may allow heavier loads with special permits on certain roads.'),
  ('Compared to a passenger car, how much more stopping distance does a loaded truck need?', 'About the same distance', 'About twice the distance', '3 to 4 times the distance', '5 to 6 times the distance', 'C', 'General Knowledge', 'medium', 'A loaded truck traveling at the same speed as a car requires 3 to 4 times the stopping distance. This is due to the greater weight and inertia of a fully loaded commercial vehicle.'),
  ('A GVWR over 26,001 lbs requires what class of CDL?', 'Class C only', 'Class A or B', 'Class D', 'No CDL is required', 'B', 'General Knowledge', 'medium', 'A vehicle with a Gross Vehicle Weight Rating (GVWR) over 26,001 lbs requires a Class A or Class B CDL. Class A is needed when towing a trailer over 10,000 lbs GVWR, while Class B covers single vehicles over 26,001 lbs.'),
  ('When must a driver complete a written vehicle condition report?', 'Only when defects are found', 'At the end of each driving day', 'Once a week', 'Only after an accident', 'B', 'General Knowledge', 'medium', 'Drivers of commercial motor vehicles must complete a written vehicle condition report at the end of each driving day. This report documents the condition of the vehicle and any defects found.'),
  ('What is the perception distance at 55 mph?', '61 feet', '142 feet', '216 feet', '100 feet', 'B', 'General Knowledge', 'medium', 'At 55 mph, perception distance is approximately 142 feet. This is the distance your vehicle travels from the time your eyes see a hazard until your brain recognizes it as a hazard.'),
  ('What is the reaction distance at 55 mph?', '142 feet', '61 feet', '216 feet', '45 feet', 'B', 'General Knowledge', 'medium', 'At 55 mph, reaction distance is approximately 61 feet. This is the distance your vehicle travels from the time your brain recognizes a hazard until your foot physically pushes the brake pedal.'),
  ('What is the braking distance at 55 mph on dry pavement?', '142 feet', '61 feet', '216 feet', '300 feet', 'C', 'General Knowledge', 'medium', 'At 55 mph, the braking distance on dry pavement is approximately 216 feet. This is the distance it takes for the vehicle to come to a complete stop once the brakes are applied.'),
  ('What should you do first if you experience a tire blowout while driving?', 'Slam on the brakes immediately', 'Hold the steering wheel firmly and stay off the brakes until the vehicle slows', 'Swerve to the shoulder immediately', 'Shift into neutral immediately', 'B', 'General Knowledge', 'medium', 'When a tire blows out, you should hold the steering wheel firmly with both hands and stay off the brakes. Let the vehicle slow down gradually, then gently brake and pull off the road. Braking hard can cause loss of control.'),
  ('How far ahead can high beam headlights illuminate the road?', '250 feet', '150 feet', '350 to 500 feet', '600 to 800 feet', 'C', 'General Knowledge', 'medium', 'High beam headlights can illuminate the road approximately 350 to 500 feet ahead. You should use high beams whenever it is safe and legal to do so, switching to low beams when oncoming traffic approaches.'),
  ('What is the BAC limit for a CDL driver who is under 21 years of age?', '0.04%', '0.08%', '0.02%', '0.00%', 'C', 'General Knowledge', 'medium', 'CDL drivers under 21 years of age have a BAC limit of 0.02%. This stricter limit reflects the zero-tolerance approach to underage drinking and driving.'),
  ('Which of the following is a key step in a pre-trip inspection?', 'Check only the tires and lights', 'Walk around the vehicle and inspect all major components systematically', 'Start the engine and listen for problems only', 'Check the mirrors and leave', 'B', 'General Knowledge', 'medium', 'A proper pre-trip inspection requires walking around the entire vehicle and systematically inspecting all major components including tires, lights, brakes, steering, suspension, coupling devices, cargo securement, and fluid levels.'),
  ('When driving on a steep downgrade, what is the proper technique to control speed?', 'Use only the brakes to control your speed', 'Shift to a lower gear before the descent and use engine braking', 'Put the transmission in neutral and coast', 'Maintain your highway speed and brake at the bottom', 'B', 'General Knowledge', 'medium', 'Before starting down a steep grade, you should shift into a lower gear that will allow the engine to help control your speed. Use engine braking (and the engine brake or jake brake if equipped) as the primary method, applying the service brakes only as a supplement.'),
  ('What should you do when approaching a railroad crossing in a commercial vehicle?', 'Speed up to cross quickly', 'Slow down and prepare to stop, look and listen for trains', 'Stop only if you see a train coming', 'Honk your horn and proceed', 'B', 'General Knowledge', 'medium', 'When approaching a railroad crossing, you should slow down, look both directions, and listen for approaching trains. Some commercial vehicles are required by law to stop at all railroad crossings regardless of whether signals are active.'),
  ('During an en-route inspection, which of the following should you check?', 'Only fuel level', 'Tires, brakes, lights, cargo securement, and coupling devices', 'Only the mirrors', 'Only the engine oil', 'B', 'General Knowledge', 'medium', 'During en-route inspections you should check tires, brakes, lights, cargo securement, coupling devices, and any other safety-critical components. You should perform these checks within the first 50 miles and periodically thereafter.'),
  ('What is the primary purpose of a post-trip inspection?', 'To find defects that could make the vehicle unsafe or cause a breakdown', 'To check the fuel level for the next trip', 'To clean the vehicle interior', 'To verify mileage for payroll', 'A', 'General Knowledge', 'medium', 'The primary purpose of a post-trip inspection is to identify any defects or damage that could make the vehicle unsafe to operate or could lead to a breakdown. Any defects found must be documented on the vehicle condition report.'),
  ('When should you downshift an automatic or manual transmission for a curve?', 'While in the curve', 'After exiting the curve', 'Before entering the curve', 'Only on wet roads', 'C', 'General Knowledge', 'medium', 'You should downshift before entering a curve, not during the curve. Downshifting while in a curve can cause a loss of traction and lead to a skid. Slow down and shift before the curve, then accelerate gently through it.'),
  ('What is the most important reason to properly secure cargo?', 'To avoid a fine', 'To prevent cargo from shifting or falling and causing an accident or injury', 'To make the vehicle look professional', 'To reduce fuel consumption', 'B', 'General Knowledge', 'medium', 'The most important reason to secure cargo properly is to prevent it from shifting, falling, or spilling, which could cause an accident, injury, or death. Improperly secured cargo is a serious safety hazard to you and other motorists.'),
  ('In foggy conditions, what should you do?', 'Use high beam headlights for maximum visibility', 'Use low beam headlights, reduce speed, and increase following distance', 'Maintain normal speed and use hazard flashers', 'Pull over and wait for the fog to clear in all cases', 'B', 'General Knowledge', 'medium', 'In fog, you should use low beam headlights (high beams reflect off fog and reduce visibility), significantly reduce speed, and increase your following distance. If visibility becomes too poor, pull over to a safe location.'),
  ('What is the correct action when your drive wheels begin to skid?', 'Accelerate to pull out of the skid', 'Brake harder to stop the skid', 'Stop braking, turn the steering wheel in the direction of the skid, and counter-steer', 'Shift into a higher gear', 'C', 'General Knowledge', 'medium', 'When drive wheels skid, you should take your foot off the brake (or accelerator if an acceleration skid), and steer in the direction you want the vehicle to go. This technique allows the tires to regain traction.'),
  ('How should you use your horn to communicate with other drivers?', 'Only in emergencies', 'Lightly tap the horn to make others aware of your presence when needed', 'Use long blasts to warn distracted drivers', 'Never use your horn near residential areas', 'B', 'General Knowledge', 'medium', 'You should use your horn to alert other road users of your presence when necessary. A light tap is usually sufficient to make drivers aware of you, such as when someone is about to merge into your lane or at blind intersections.'),
  ('What is the leading cause of fatal crashes involving commercial vehicles?', 'Mechanical failure', 'Bad weather', 'Distracted driving and driver fatigue', 'Road construction', 'C', 'General Knowledge', 'medium', 'Driver-related factors such as distracted driving and fatigue are the leading causes of fatal crashes involving commercial vehicles. Staying alert, well-rested, and focused on driving is critical for safety.'),
  ('What should you do if your brakes fail on a downhill grade?', 'Pump the brakes rapidly, downshift, and look for an escape ramp', 'Turn off the engine', 'Jump from the vehicle', 'Steer into oncoming traffic to slow down', 'A', 'General Knowledge', 'medium', 'If your brakes fail going downhill, you should pump the brake pedal rapidly to try to build pressure, downshift to use engine braking, and look for an escape ramp or an upgrade that will slow the vehicle. Using the escape ramp is your safest option if available.'),
  ('When driving at night, you should adjust your speed so you can stop within what distance?', 'The distance you can see ahead with your headlights', '500 feet regardless of visibility', 'The posted speed limit distance', 'Twice the posted speed limit distance', 'A', 'General Knowledge', 'medium', 'You should always drive at a speed that allows you to stop within the distance illuminated by your headlights. Overdriving your headlights means you cannot stop in time if an obstacle appears in your path.'),
  ('What type of fire extinguisher is required on a commercial vehicle, and what types of fires can it fight?', 'Type A only, for paper and wood fires', 'Type B:C, for flammable liquid and electrical fires', 'Type D, for metal fires', 'Type K, for kitchen fires', 'B', 'General Knowledge', 'medium', 'Commercial vehicles must carry a B:C rated fire extinguisher (5 B:C minimum). The B rating covers flammable liquids like gasoline and diesel, and the C rating covers electrical fires, which are the most common fire types encountered on commercial vehicles.'),
  ('What is the first thing you should do at the scene of an accident?', 'Move your vehicle out of the way immediately', 'Protect the area to prevent further accidents by setting out warning devices', 'Call your dispatcher', 'Begin cleaning up debris', 'B', 'General Knowledge', 'medium', 'The first priority at an accident scene is to protect the area to prevent additional crashes. Set out reflective triangles or other warning devices to alert approaching traffic. Then care for the injured and notify authorities.'),
  ('Where should reflective triangles be placed when your vehicle is stopped on the roadside?', 'Only behind the vehicle', 'Within 10 feet of the front, 100 feet behind, and 100 feet ahead of the vehicle', 'Within 10 feet of the rear, 100 feet behind, and 200 feet behind the vehicle on a two-lane road', 'Only in front of the vehicle', 'C', 'General Knowledge', 'medium', 'Reflective triangles should be placed within 10 feet of the rear of the vehicle, approximately 100 feet behind, and approximately 100 feet ahead (or 200 feet behind on an undivided two-lane road). This provides adequate warning for approaching traffic from both directions.'),
  ('Which of these is a common cause of vehicle fires?', 'Under-inflated tires and fuel leaks', 'Overinflated tires', 'Using low beam headlights at night', 'Driving with windows open', 'A', 'General Knowledge', 'medium', 'Under-inflated tires can overheat and catch fire, and fuel leaks near hot engine components are a major fire risk. Regular inspections of tires, fuel lines, and electrical systems help prevent vehicle fires.'),
  ('When loading cargo, where should the heaviest items be placed?', 'At the rear of the trailer', 'On top of lighter cargo', 'As low and as close to the center of the vehicle as possible', 'Near the doors for easy unloading', 'C', 'General Knowledge', 'medium', 'The heaviest cargo should be placed as low as possible and as close to the center (longitudinally) of the vehicle as practical. This keeps the center of gravity low and centered, improving vehicle stability and handling.'),
  ('What does double-clutching involve when shifting gears?', 'Pressing the clutch twice quickly before shifting', 'Releasing the clutch into neutral, then pressing the clutch again to shift into the next gear', 'Using two feet on the clutch pedal', 'Skipping gears in a transmission', 'B', 'General Knowledge', 'medium', 'Double-clutching requires pressing the clutch to move the gearshift to neutral, releasing the clutch briefly to allow engine and gear speeds to synchronize, then pressing the clutch again to move into the next gear. This technique is used in non-synchronized transmissions common in commercial vehicles.'),
  ('What is the purpose of a jake brake (engine retarder)?', 'To increase engine power on upgrades', 'To help slow the vehicle without using the service brakes', 'To improve fuel economy', 'To warm up the engine faster', 'B', 'General Knowledge', 'medium', 'A jake brake (engine retarder) helps slow the vehicle by using the engine''s compression as a braking force. This reduces wear on the service brakes, which is especially valuable during long downhill descents in mountain driving.'),
  ('What should you inspect on your tires during a pre-trip inspection?', 'Only tire pressure', 'Tread depth, air pressure, cuts, bulges, and proper inflation', 'Only whether the tires are the correct size', 'Only that the valve stems are present', 'B', 'General Knowledge', 'medium', 'During a pre-trip inspection, tires should be checked for proper tread depth (minimum 4/32 inch on steer tires, 2/32 inch on other tires), correct air pressure, cuts, bulges, missing valve caps, and signs of uneven wear.'),
  ('What is the minimum number of tie-downs required for cargo that is 10 feet long?', '1 tie-down', '2 tie-downs', '3 tie-downs', '4 tie-downs', 'B', 'General Knowledge', 'medium', 'Cargo must be secured with at least one tie-down for every 10 feet of cargo length, with a minimum of two tie-downs regardless of cargo length. A 10-foot piece of cargo therefore requires at least 2 tie-downs.'),
  ('Under Hours of Service regulations, what is the maximum number of hours a property-carrying driver may drive after being on duty for a consecutive period?', '10 hours', '11 hours', '13 hours', '14 hours', 'B', 'General Knowledge', 'medium', 'Under current Hours of Service regulations, a property-carrying CMV driver may drive a maximum of 11 hours after 10 consecutive hours off duty. The 11-hour driving limit is a core HOS rule.'),
  ('Under HOS rules, after how many consecutive hours on duty must a property-carrying driver stop driving?', '11 hours', '13 hours', '14 hours', '16 hours', 'C', 'General Knowledge', 'medium', 'A property-carrying driver must not drive after the 14th consecutive hour after coming on duty following 10 consecutive hours off duty. This 14-hour window cannot be extended with off-duty time.'),
  ('What is a driver required to do before putting out a vehicle fire?', 'Call 911 first in all cases', 'Know what is burning and use the correct type of extinguisher', 'Remove all cargo first', 'Drive to the nearest fire station', 'B', 'General Knowledge', 'medium', 'Before fighting a vehicle fire you must know what is burning so you can use the correct extinguisher type. Using the wrong extinguisher (such as water on an electrical or grease fire) can make the fire worse or create additional hazards.'),
  ('Which vehicle system is most critical to inspect for proper operation before driving?', 'Air conditioning system', 'Entertainment system', 'Braking system', 'Power window system', 'C', 'General Knowledge', 'medium', 'The braking system is the most critical safety system on a commercial vehicle. During pre-trip inspection, you must check brake components including shoes, drums, hoses, slack adjusters, air pressure, and low-pressure warning devices.'),
  ('When driving on icy roads, what is the safest practice?', 'Reduce speed to a crawl and increase following distance dramatically', 'Maintain normal speed but increase following distance', 'Drive at the posted speed limit and brake gently', 'Use cruise control for steady speed', 'A', 'General Knowledge', 'medium', 'On icy roads, you should reduce speed to a crawl, avoid sudden movements of the steering wheel or brakes, and increase your following distance dramatically. Ice can make stopping nearly impossible at higher speeds.'),
  ('You are driving a 50-foot vehicle at 35 mph. What is the minimum safe following distance?', '3 seconds', '4 seconds', '5 seconds', '7 seconds', 'C', 'General Knowledge', 'medium', 'At speeds under 40 mph, the rule is 1 second for every 10 feet of vehicle length. A 50-foot vehicle needs at least 5 seconds of following distance. Since 35 mph is under 40 mph, no additional second is required.'),
  ('What is the main advantage of using turn signals well in advance of a turn or lane change?', 'It is only required by law and has no practical benefit', 'It gives other drivers time to react and adjust to your intended movement', 'It activates the vehicle anti-lock braking system', 'It reduces your blind spot', 'B', 'General Knowledge', 'medium', 'Signaling well in advance gives other drivers time to see your signal and adjust their driving. For large commercial vehicles, early signaling is especially important because these vehicles need more time and space to complete turns and lane changes.');
INSERT INTO questions (question_text, option_a, option_b, option_c, option_d, correct_answer, category, difficulty, explanation) VALUES
  ('How many steps are in the standard CDL pre-trip inspection method?', 'Five', 'Six', 'Seven', 'Eight', 'C', 'General Knowledge', 'medium', 'The standard CDL pre-trip inspection follows a seven-step method designed to ensure every critical component of the vehicle is checked before driving.'),
  ('What is the first step of the seven-step inspection method?', 'Start the engine and check gauges', 'Check the engine compartment', 'Vehicle overview and approach', 'Walk-around inspection', 'C', 'General Knowledge', 'medium', 'Step 1 is the vehicle overview and approach. As you walk toward the vehicle, you should look for damage, leaning, leaks under the vehicle, and hazards in the area around the vehicle.'),
  ('During the vehicle overview (Step 1), what should you look for as you approach the vehicle?', 'Only tire condition', 'Damage, leaning, leaks, and surrounding hazards', 'Only fluid leaks', 'Only body damage', 'B', 'General Knowledge', 'medium', 'During the vehicle overview approach, you should look for signs of damage, whether the vehicle is leaning to one side, any leaks underneath the vehicle, and any hazards in the surrounding area such as low wires or branches.'),
  ('What does it indicate if the vehicle is leaning to one side during the approach inspection?', 'Normal tire wear', 'Possible flat tire, overloaded cargo, or suspension failure', 'The road is uneven', 'The vehicle was recently washed', 'B', 'General Knowledge', 'medium', 'A vehicle leaning to one side can indicate a flat tire, improperly loaded or shifted cargo, or a suspension system failure. Any of these conditions must be investigated and corrected before driving.'),
  ('What is Step 2 of the seven-step inspection method?', 'Walk-around inspection', 'Check engine compartment', 'In-cab inspection', 'Check signal lights', 'B', 'General Knowledge', 'medium', 'Step 2 is checking the engine compartment. You should inspect power steering fluid, coolant level, oil level, belts, hoses, the battery, and wiring before starting the engine.'),
  ('What is the maximum allowable play in engine belts during the engine compartment inspection?', '1/4 inch', '1/2 inch', '3/4 inch', '1 inch', 'B', 'General Knowledge', 'medium', 'Belts should have no more than 1/2 inch of play when pressed. Excessive belt play can lead to belt slippage, which may cause overheating, loss of power steering, or alternator failure.'),
  ('Which fluids should you check during the engine compartment inspection?', 'Only engine oil', 'Only coolant and oil', 'Power steering fluid, coolant, and engine oil', 'Only transmission fluid', 'C', 'General Knowledge', 'medium', 'During the engine compartment inspection, you should check the power steering fluid, coolant level, and engine oil level. All fluids must be at proper levels to ensure safe vehicle operation.'),
  ('What should you inspect on the battery during the engine compartment check?', 'Only the battery brand', 'Secure mounting, connections, and no corrosion or leaks', 'Only the voltage reading', 'Only the manufacture date', 'B', 'General Knowledge', 'medium', 'During the engine compartment inspection, verify the battery is securely mounted, the connections are tight and free of corrosion, and there are no cracks or leaks in the battery casing.'),
  ('What is Step 3 of the seven-step inspection method?', 'Walk-around inspection', 'Engine compartment check', 'Start engine and in-cab inspection', 'Check lights', 'C', 'General Knowledge', 'medium', 'Step 3 involves starting the engine and performing an in-cab inspection. This includes checking gauges, controls, mirrors, the windshield, wipers, and all dashboard warning lights.'),
  ('After starting the engine, oil pressure should come up to normal within what time frame?', 'Within seconds', 'Within 2 minutes', 'Within 5 minutes', 'Within 10 minutes', 'A', 'General Knowledge', 'medium', 'Oil pressure should come up to the normal operating range within seconds of starting the engine. If oil pressure does not register quickly, shut off the engine immediately to prevent serious engine damage.'),
  ('During the in-cab inspection, what should you verify about the mirrors?', 'They are the correct brand', 'They are properly adjusted, clean, and not damaged', 'They are tinted', 'They have heating elements', 'B', 'General Knowledge', 'medium', 'Mirrors must be properly adjusted to minimize blind spots, clean for clear visibility, and free of cracks or damage. Proper mirror adjustment is essential for safe lane changes and maneuvering.'),
  ('What gauges should you check during the in-cab inspection?', 'Only the speedometer', 'Only the fuel gauge', 'Oil pressure, temperature, ammeter/voltmeter, and air pressure gauges', 'Only the tachometer', 'C', 'General Knowledge', 'medium', 'During the in-cab inspection, you must check the oil pressure gauge, temperature gauge, ammeter or voltmeter, and air pressure gauge. All gauges must be in their normal operating ranges.'),
  ('What is Step 4 of the seven-step inspection method?', 'Walk-around inspection', 'Check signal lights', 'Turn off engine and check lights', 'Start the engine', 'C', 'General Knowledge', 'medium', 'Step 4 is to turn off the engine and check the lights. You should turn on the headlights and four-way flashers, then get out and check that all lights are working properly and are the correct color.'),
  ('What is Step 5 of the seven-step inspection method?', 'Check signal lights', 'Walk-around inspection', 'Brake check', 'Engine compartment check', 'B', 'General Knowledge', 'medium', 'Step 5 is the walk-around inspection. This is the most comprehensive step where you inspect tires, wheels, lug nuts, suspension, brakes, axles, frame, exhaust, fuel tank, and coupling devices.'),
  ('What is the minimum tread depth required on steer tires?', '2/32 inch', '4/32 inch', '6/32 inch', '8/32 inch', 'B', 'General Knowledge', 'medium', 'Steer (front) tires must have a minimum tread depth of 4/32 inch. Steer tires have a higher requirement because they are critical for steering control, especially on wet or slippery surfaces.'),
  ('What is the minimum tread depth required on tires other than the steer axle?', '1/32 inch', '2/32 inch', '4/32 inch', '6/32 inch', 'B', 'General Knowledge', 'medium', 'All tires other than steer axle tires must have a minimum tread depth of 2/32 inch. Tires below this minimum are unsafe and illegal to operate on public roads.'),
  ('During tire inspection, what defects should you look for besides tread depth?', 'Only tire brand', 'Proper inflation, cuts, bulges, and condition of valve stems', 'Only tire age', 'Only tire size', 'B', 'General Knowledge', 'medium', 'When inspecting tires, check for proper inflation, cuts or slashes in the sidewalls, bulges that may indicate internal damage, and the condition of valve stems. All of these can lead to tire failure if not addressed.'),
  ('What do rust streaks around lug nuts indicate?', 'Normal wear', 'The lug nuts may be loose', 'The vehicle was recently in rain', 'The lug nuts are new', 'B', 'General Knowledge', 'medium', 'Rust streaks coming from the lug nuts are a telltale sign that the lug nuts may be loose. Loose lug nuts can lead to wheel separation, which is an extremely dangerous situation.'),
  ('What should you look for when inspecting wheels and rims?', 'Only the wheel size', 'Cracks, dents, missing or broken lugs, and signs of misalignment', 'Only the rim color', 'Only the wheel weight', 'B', 'General Knowledge', 'medium', 'Inspect wheels and rims for cracks, dents, out-of-round conditions, missing or broken lug nuts, and any signs of misalignment. Damaged wheels can fail catastrophically at highway speeds.'),
  ('What components should be inspected as part of the suspension system?', 'Only the tires', 'Springs, air bags, shock absorbers, and torque rods', 'Only the frame', 'Only the axles', 'B', 'General Knowledge', 'medium', 'The suspension system inspection should cover leaf springs (for cracks or missing leaves), air bags (for leaks or damage), shock absorbers (for leaks), and torque rods and bushings (for wear or damage).'),
  ('What is the maximum allowable play in brake slack adjusters?', '1/2 inch', '1 inch', '1-1/2 inches', '2 inches', 'B', 'General Knowledge', 'medium', 'Slack adjusters should have no more than approximately 1 inch of play when pulled by hand. Excessive slack adjuster travel means the brakes are out of adjustment and may not provide adequate stopping power.'),
  ('During brake inspection, what components should you check?', 'Only brake pads', 'Brake pads or shoes, drums or rotors, hoses, and slack adjusters', 'Only brake fluid', 'Only the brake pedal', 'B', 'General Knowledge', 'medium', 'A thorough brake inspection includes checking brake pads or shoes for wear, drums or rotors for cracks or damage, brake hoses for leaks or wear, and slack adjusters for proper adjustment.'),
  ('What is the maximum allowable steering wheel play for a vehicle with power steering?', '5 degrees', '10 degrees', '15 degrees', '20 degrees', 'B', 'General Knowledge', 'medium', 'For a vehicle with power steering, the steering wheel should have no more than 10 degrees of play (approximately 2 inches of movement on a 20-inch steering wheel) before the front wheels begin to move.'),
  ('What components are part of the steering system inspection?', 'Only the steering wheel', 'Steering box, power steering hoses and fluid, linkage, and steering play', 'Only the tires', 'Only the tie rods', 'B', 'General Knowledge', 'medium', 'The steering system inspection includes the steering box (for leaks and secure mounting), power steering hoses and fluid level, all linkage components (for wear and damage), and checking for excessive steering wheel play.'),
  ('What is Step 6 of the seven-step inspection method?', 'Brake check', 'Walk-around inspection', 'Check signal lights', 'Engine compartment check', 'C', 'General Knowledge', 'medium', 'Step 6 is checking the signal lights. Have someone observe from outside or use a wall reflection to verify that turn signals, brake lights, and four-way flashers are all working properly.'),
  ('What is Step 7 of the seven-step inspection method?', 'Check the engine', 'Walk-around inspection', 'Brake check', 'Check signal lights', 'C', 'General Knowledge', 'medium', 'Step 7 is the brake check. This includes testing the parking brake, service brake, and for vehicles with air brakes, performing specific air brake tests to ensure the braking system is functioning properly.'),
  ('How do you test the parking brake during Step 7?', 'Press the service brake pedal', 'Engage the parking brake, then gently try to move the vehicle in a low gear', 'Rev the engine', 'Flash the headlights', 'B', 'General Knowledge', 'medium', 'To test the parking brake, apply it with the vehicle stopped, then gently try to move the vehicle forward in a low gear. The parking brake should hold the vehicle in place. If it does not, the parking brake needs repair.'),
  ('How do you test the service brake during Step 7?', 'Only check the brake fluid level', 'Drive at about 5 mph and firmly apply the brakes to check for pulling, unusual feel, or delayed stopping', 'Press the brake pedal while parked only', 'Only check the brake lights', 'B', 'General Knowledge', 'medium', 'To test the service brakes, drive the vehicle forward at about 5 mph and firmly apply the brakes. The vehicle should stop smoothly and promptly without pulling to one side, making unusual noises, or feeling spongy.'),
  ('For air brake vehicles, air pressure must build from 50 to 90 psi within what time frame?', '1 minute', '2 minutes', '3 minutes', '5 minutes', 'C', 'General Knowledge', 'medium', 'Air pressure must build from 50 to 90 psi within 3 minutes with the engine at operating RPM. If it takes longer, the air compressor may be defective or there may be a leak in the system.'),
  ('At what psi range should the governor cut out the air compressor?', '80-100 psi', '100-120 psi', '120-140 psi', '140-160 psi', 'C', 'General Knowledge', 'medium', 'The governor should cut out the air compressor at approximately 120 to 140 psi. This prevents over-pressurization of the air brake system. If the compressor does not cut out in this range, the system needs repair.'),
  ('The low air pressure warning device must activate before air pressure drops below what level?', '40 psi', '50 psi', '60 psi', '80 psi', 'C', 'General Knowledge', 'medium', 'The low air pressure warning signal must activate before the air pressure drops below 60 psi. This warning gives the driver time to safely stop the vehicle before air pressure drops low enough for the spring brakes to lock.'),
  ('At what pressure should the safety relief (pop-off) valve open?', '100 psi', '120 psi', '140 psi', '150 psi', 'D', 'General Knowledge', 'medium', 'The safety relief valve is designed to open at approximately 150 psi to protect the air system from over-pressurization. If the governor fails to cut out the compressor, the safety valve prevents dangerous pressure buildup.'),
  ('What should you check regarding ABS indicator lights during the in-cab inspection?', 'ABS lights should stay on while driving', 'ABS light on the dash should come on during the bulb check at startup and then turn off', 'ABS lights should flash continuously', 'ABS lights are not important to check', 'B', 'General Knowledge', 'medium', 'The ABS indicator light on the dashboard should illuminate briefly when you turn on the ignition as part of the bulb check, and then turn off. If the light stays on, it indicates a malfunction in the ABS system.'),
  ('What should you inspect regarding the exhaust system during the walk-around?', 'Only the muffler brand', 'Check for leaks, loose parts, damage, and that it is properly mounted', 'Only the tailpipe size', 'Exhaust inspection is not required', 'B', 'General Knowledge', 'medium', 'Inspect the exhaust system for leaks at connections, loose or broken mounting brackets, holes or cracks in the muffler or pipes, and any signs of exhaust blowing against wiring or fuel lines, which creates a fire hazard.'),
  ('Why are exhaust leaks particularly dangerous?', 'They reduce fuel economy', 'Exhaust fumes can enter the cab and cause driver drowsiness or carbon monoxide poisoning', 'They make the vehicle louder', 'They are only a cosmetic issue', 'B', 'General Knowledge', 'medium', 'Exhaust leaks are extremely dangerous because exhaust fumes, including carbon monoxide, can enter the cab. Carbon monoxide is odorless and colorless and can cause drowsiness, impaired judgment, unconsciousness, or death.'),
  ('What should you look for when inspecting the frame and cross members?', 'Only the paint condition', 'Cracks, bends, broken welds, holes, and loose or missing bolts', 'Only the frame color', 'Frame inspection is not part of pre-trip', 'B', 'General Knowledge', 'medium', 'Inspect the frame and cross members for cracks, bends, broken welds, holes from corrosion, and any loose or missing bolts or fasteners. The frame is the structural backbone of the vehicle and must be in sound condition.'),
  ('What electrical components should be inspected during the walk-around?', 'Only the headlights', 'Wiring for damage, all lights functioning, reflectors clean and present, and reflective tape intact', 'Only the battery', 'Only the turn signals', 'B', 'General Knowledge', 'medium', 'The electrical system inspection includes checking wiring for loose connections or damage, verifying all lights are functioning and the correct color, ensuring reflectors are clean and present, and confirming reflective tape is intact.'),
  ('What minimum rating must the fire extinguisher carry on a commercial vehicle?', '2 B:C', '5 B:C', '10 B:C', '20 B:C', 'B', 'General Knowledge', 'medium', 'The fire extinguisher on a commercial vehicle must be rated at least 5 B:C. The B rating covers flammable liquid fires and the C rating covers electrical fires. The extinguisher must also be securely mounted, easily accessible, and fully charged.'),
  ('What emergency equipment is required on a commercial vehicle?', 'Only a fire extinguisher', 'Fire extinguisher rated 5 B:C, spare electrical fuses, and three reflective warning triangles', 'Only warning triangles', 'Only spare fuses', 'B', 'General Knowledge', 'medium', 'Federal regulations require a fire extinguisher rated at least 5 B:C, spare electrical fuses (unless the vehicle has circuit breakers), and three reflective warning triangles for roadside emergencies.'),
  ('At what distances should reflective warning triangles be placed behind a stopped vehicle on an undivided highway?', '5, 50, and 100 feet', '10, 100, and 200 feet', '25, 150, and 300 feet', '50, 200, and 400 feet', 'B', 'General Knowledge', 'medium', 'Reflective warning triangles must be placed at 10 feet, 100 feet, and 200 feet behind the stopped vehicle on an undivided two-lane road. This gives approaching traffic adequate warning at various distances.'),
  ('What should you inspect on the coupling system for a combination vehicle?', 'Only the paint on the fifth wheel', 'Fifth wheel plate, locking jaws, kingpin, air and electrical lines, and safety chains or devices', 'Only the trailer brakes', 'Coupling inspection is not needed', 'B', 'General Knowledge', 'medium', 'The coupling system inspection for combination vehicles includes checking the fifth wheel plate for damage and grease, locking jaws for secure engagement around the kingpin, air and electrical lines for damage, and safety chains or latch devices.'),
  ('What should you check regarding cargo securement during the pre-trip inspection?', 'Cargo inspection is only done at pickup', 'Cargo is properly blocked, braced, tied, and chained, and tailgate or doors are secure', 'Only the weight of the cargo', 'Cargo inspection is only for hazmat loads', 'B', 'General Knowledge', 'medium', 'You must verify that cargo is properly blocked, braced, tied down, or chained to prevent shifting. Tailgates, doors, and tarps should be secured. Cargo must also not obstruct your view or access to emergency equipment.'),
  ('What fluid levels should be checked as part of the pre-trip inspection?', 'Only engine oil', 'Engine oil, coolant, power steering fluid, transmission fluid, and windshield washer fluid', 'Only coolant', 'Only windshield washer fluid', 'B', 'General Knowledge', 'medium', 'A complete pre-trip inspection includes checking engine oil, coolant, power steering fluid, transmission fluid, and windshield washer fluid. All fluids should be at their proper levels as indicated on dipsticks or reservoir markings.'),
  ('What is the purpose of the post-trip inspection?', 'It is only required for hazmat vehicles', 'To identify and report any vehicle defects or problems found at the end of the trip', 'To clean the vehicle', 'Post-trip inspections are not required', 'B', 'General Knowledge', 'medium', 'The post-trip inspection is required by federal regulations. Drivers must identify and report any vehicle defects or conditions that could affect safety or lead to a breakdown. This report must be in writing and reviewed by the next driver.'),
  ('Before beginning the pre-trip inspection, what written document should you review?', 'The vehicle registration only', 'The previous driver vehicle condition report', 'The vehicle warranty', 'The maintenance schedule only', 'B', 'General Knowledge', 'medium', 'You should always review the previous driver vehicle condition report (DVIR) before beginning your pre-trip inspection. This tells you about any defects reported and whether they were repaired, so you know what to pay special attention to.'),
  ('What condition of a leaf spring would require the vehicle to be placed out of service?', 'A spring with minor surface rust', 'A cracked or broken leaf spring or a missing leaf', 'A spring with normal wear', 'A leaf spring with grease on it', 'B', 'General Knowledge', 'medium', 'A cracked or broken leaf spring or a spring with any leaves missing is a serious safety defect. This weakens the suspension and can lead to loss of vehicle control or axle shift, requiring the vehicle to be placed out of service.'),
  ('What should you check on brake drums during the walk-around inspection?', 'Only the drum color', 'Cracks, dents, and signs of overheating such as discoloration', 'Only the drum size', 'Brake drums do not need inspection', 'B', 'General Knowledge', 'medium', 'Brake drums should be inspected for cracks, dents, and signs of overheating such as heat discoloration (blue or glazed appearance). Cracked or overheated drums can fail and cause a loss of braking ability.'),
  ('What should you look for when checking brake hoses and lines?', 'Only the hose color', 'Leaks, cracks, chafing, and that they are not tangled or restricted', 'Only the hose length', 'Brake hoses do not need inspection', 'B', 'General Knowledge', 'medium', 'Brake hoses and lines must be checked for leaks, cracks, chafing from rubbing against other components, and any kinks or tangles that could restrict air flow. A damaged brake hose can lead to complete brake failure on that wheel.'),
  ('During the in-cab inspection, what should you verify about the windshield?', 'Only that it is the correct size', 'No illegal stickers, no damage obstructing the view, and wipers work properly', 'Only that it is tinted', 'Windshield inspection is optional', 'B', 'General Knowledge', 'medium', 'Check the windshield for cracks, chips, or damage that could obstruct your view, ensure no illegal stickers are blocking your field of vision, and verify that windshield wipers operate properly and the washer fluid sprays correctly.'),
  ('What is the purpose of checking the fuel tank during the walk-around inspection?', 'Only to check the fuel level', 'To verify the tank is securely mounted, not leaking, and the cap is tight', 'Only to check the fuel brand', 'Fuel tanks do not need inspection', 'B', 'General Knowledge', 'medium', 'During the walk-around, verify the fuel tank is securely mounted to the frame, there are no leaks from the tank or fuel lines, and the fuel cap is on tight and secure. A fuel leak is an extreme fire hazard.');
INSERT INTO questions (question_text, option_a, option_b, option_c, option_d, correct_answer, category, difficulty, explanation) VALUES
  ('What is the function of the air compressor in an air brake system?', 'To store compressed air in the brake drums', 'To pump air into the air storage tanks', 'To release air from the braking system', 'To cool the brake linings', 'B', 'Air Brakes', 'medium', 'The air compressor pumps air into the air storage tanks, building up and maintaining the air pressure needed to operate the air brake system.'),
  ('The governor controls the air compressor by:', 'Regulating brake pedal pressure', 'Cutting in at 100 PSI and cutting out at 125 PSI', 'Cutting in at 125 PSI and cutting out at 150 PSI', 'Monitoring brake pad wear', 'B', 'Air Brakes', 'medium', 'The governor controls when the air compressor pumps air. It cuts in at around 100 PSI to start building pressure and cuts out at around 125 PSI when the tanks are sufficiently charged.'),
  ('Why should you drain air tanks regularly?', 'To prevent the compressor from overheating', 'To remove water and oil that collect and can damage the brakes', 'To reduce air pressure to safe levels', 'To test the low air pressure warning', 'B', 'Air Brakes', 'medium', 'Compressed air contains water and compressor oil. These accumulate in air tanks and can damage the braking system, cause corrosion, and reduce braking effectiveness, especially in cold weather when water can freeze.'),
  ('What does the safety valve on an air brake system do?', 'Opens at 60 PSI to warn the driver', 'Opens at 150 PSI to protect the tank from over-pressurization', 'Closes at 125 PSI to stop air flow', 'Releases air when the brake pedal is pressed', 'B', 'Air Brakes', 'medium', 'The safety valve is installed in the first tank the air compressor pumps air into. It protects the tank and the system from too much pressure by automatically opening (popping off) if pressure reaches 150 PSI.'),
  ('What is the purpose of an alcohol evaporator in an air brake system?', 'To clean the air lines', 'To help reduce the risk of ice forming in air brake valves during cold weather', 'To lubricate the compressor', 'To improve fuel efficiency', 'B', 'Air Brakes', 'medium', 'An alcohol evaporator introduces alcohol into the air system to help reduce the risk of ice forming in air brake valves and other parts during cold weather. Ice blockages can prevent brakes from working properly.'),
  ('A dual air brake system has:', 'Two complete sets of brake drums', 'Two separate air brake systems with a single set of controls', 'Two brake pedals for redundancy', 'Two air compressors', 'B', 'Air Brakes', 'medium', 'A dual air brake system has two separate air brake systems that use a single set of brake controls. The primary system typically operates the rear axle brakes, and the secondary system operates the front axle brakes, providing redundancy.'),
  ('If one system in a dual air brake system fails, what happens?', 'All braking is lost immediately', 'The other system can still provide some braking power', 'The parking brake automatically engages', 'The vehicle cannot be driven at all', 'B', 'Air Brakes', 'medium', 'If one air brake system in a dual system fails, the other system can still provide braking. However, the remaining system will not have full normal braking power, so you should get the vehicle off the road and repaired as soon as safely possible.'),
  ('When you press the brake pedal in an air brake system, you are operating the:', 'Spring brakes', 'Service brakes', 'Parking brakes', 'Emergency brakes', 'B', 'Air Brakes', 'medium', 'Pressing the brake pedal applies the service brakes, which use air pressure to push foundation brake components against the drums or rotors to slow and stop the vehicle. This is different from spring brakes, which are used for parking.'),
  ('Foundation brakes are used at each wheel. The most common type is the:', 'Wedge brake', 'Disc brake', 'S-cam drum brake', 'Hydraulic brake', 'C', 'Air Brakes', 'medium', 'The most common type of foundation brake found on heavy commercial vehicles is the S-cam drum brake. When air pressure is applied, it pushes a rod out that turns a cam shaped like the letter S, which forces the brake shoes against the drum.'),
  ('In an S-cam brake, what component forces the brake shoes apart and against the drum?', 'The slack adjuster', 'The push rod', 'The S-cam', 'The brake chamber', 'C', 'Air Brakes', 'medium', 'The S-cam is a shaft with a cam shaped like the letter S. When the push rod pushes the slack adjuster, the slack adjuster turns the S-cam, which twists and forces the brake shoes apart and presses them against the inside of the brake drum.'),
  ('How do wedge brakes differ from S-cam brakes?', 'Wedge brakes use a wedge pushed between the brake shoes instead of an S-cam', 'Wedge brakes only work on front axles', 'Wedge brakes do not use air pressure', 'Wedge brakes are only used on trailers', 'A', 'Air Brakes', 'medium', 'In wedge brakes, the brake chamber push rod pushes a wedge directly between the ends of the brake shoes, forcing them apart and against the brake drum. Unlike S-cam brakes, they do not use a slack adjuster or S-cam mechanism.'),
  ('What should the air pressure gauge reading be in a typical air brake system during normal operation?', 'Between 50 and 75 PSI', 'Between 100 and 125 PSI', 'Between 130 and 150 PSI', 'Between 60 and 80 PSI', 'B', 'Air Brakes', 'medium', 'During normal operation, the air pressure in the system should be maintained between approximately 100 and 125 PSI. The governor cuts in at about 100 PSI to build pressure and cuts out at about 125 PSI.'),
  ('The low air pressure warning signal must activate before air pressure drops below:', '80 PSI', '55 PSI', '60 PSI', '45 PSI', 'C', 'Air Brakes', 'medium', 'Federal and state regulations require that a low air pressure warning signal activates before the air pressure in the system drops below 60 PSI. This gives the driver time to stop safely before pressure drops too low for the brakes to work.'),
  ('What typically happens when the low air pressure warning activates?', 'The engine shuts off', 'A red warning light and/or buzzer comes on', 'The transmission locks', 'The parking brake releases', 'B', 'Air Brakes', 'medium', 'When air pressure drops to about 60 PSI or below, a low air pressure warning device activates. This is usually a red warning light, a buzzer (wig-wag), or both. The driver should stop immediately and safely when this warning activates.'),
  ('Spring brakes will automatically engage when air pressure drops to between:', '60 and 80 PSI', '20 and 45 PSI', '100 and 125 PSI', '5 and 10 PSI', 'B', 'Air Brakes', 'medium', 'Spring brakes are held in the released position by air pressure. When air pressure drops to between 20 and 45 PSI, the springs are strong enough to overcome the remaining air pressure and apply the brakes automatically.'),
  ('Why should you never use the brake pedal to hold your vehicle on a hill when the spring brakes are engaged?', 'It wastes fuel', 'Air pressure could leak away, releasing the service brakes and causing the vehicle to roll', 'It causes excessive tire wear', 'It damages the air compressor', 'B', 'Air Brakes', 'medium', 'If you use the brake pedal (service brakes) to hold your vehicle and the air leaks away, you will lose braking. Spring brakes, on the other hand, are applied mechanically by springs and do not depend on air pressure to remain engaged.'),
  ('The parking brake in vehicles with air brakes is applied using:', 'The brake pedal', 'A yellow diamond-shaped push-pull control knob', 'The trailer hand valve', 'A foot-operated lever', 'B', 'Air Brakes', 'medium', 'In vehicles with air brakes, the parking brake is controlled by a yellow, diamond-shaped push-pull control knob on the dashboard. Pulling the knob out applies the parking brakes (spring brakes), and pushing it in releases them.'),
  ('At what PSI does the governor typically cut in to start the air compressor?', '60 PSI', '125 PSI', '100 PSI', '150 PSI', 'C', 'Air Brakes', 'medium', 'The governor cuts in (starts the compressor pumping) at approximately 100 PSI. This means when air pressure drops to around 100 PSI during normal use, the compressor begins refilling the tanks.'),
  ('At what PSI does the governor typically cut out to stop the air compressor?', '100 PSI', '150 PSI', '60 PSI', '125 PSI', 'D', 'Air Brakes', 'medium', 'The governor cuts out (stops the compressor from pumping) at approximately 125 PSI. This prevents over-pressurization of the system during normal operation while maintaining adequate braking pressure.'),
  ('During an air leakage rate test for a single vehicle (not a combination), the air pressure drop should be less than:', '4 PSI per minute', '3 PSI per minute', '2 PSI per minute', '1 PSI per minute', 'C', 'Air Brakes', 'medium', 'For a single vehicle with a fully charged air system, the air leakage rate should be less than 2 PSI per minute with the engine off and brakes applied. A higher leak rate indicates an air leak that must be repaired.'),
  ('During an air leakage rate test for a combination vehicle, the air pressure drop should be less than:', '2 PSI per minute', '5 PSI per minute', '3 PSI per minute', '4 PSI per minute', 'C', 'Air Brakes', 'medium', 'For a combination vehicle (tractor-trailer), the air leakage rate should be less than 3 PSI per minute with the engine off and brakes applied. Combination vehicles have more connections and components, so a slightly higher rate is allowed.'),
  ('Brake lag distance at 55 mph is approximately:', '10 feet', '22 feet', '32 feet', '50 feet', 'C', 'Air Brakes', 'medium', 'At 55 mph, brake lag adds about 32 feet to your stopping distance. Brake lag is the time it takes for the air to travel through the lines and activate the brakes after you press the pedal, which is about one-half second.'),
  ('The delay between pressing the brake pedal and the brakes actually working in an air brake system is called:', 'Reaction distance', 'Brake fade', 'Brake lag', 'Perception distance', 'C', 'Air Brakes', 'medium', 'Brake lag is the time delay between when you press the brake pedal and when the brakes actually begin to work. In air brake systems, this delay occurs because air takes time to flow through the lines to the brakes, typically about one-half second.'),
  ('How long is the typical brake lag time in an air brake system?', 'About one-half second', 'About two seconds', 'About three seconds', 'About one-tenth of a second', 'A', 'Air Brakes', 'medium', 'The typical brake lag time in an air brake system is about one-half second. This is the time it takes for air to travel through the brake lines after you step on the pedal. At higher speeds, this delay adds significant stopping distance.'),
  ('The total stopping distance for a vehicle with air brakes is made up of:', 'Perception distance + reaction distance + brake lag distance + braking distance', 'Reaction distance + braking distance only', 'Perception distance + braking distance only', 'Brake lag distance + braking distance only', 'A', 'Air Brakes', 'medium', 'Total stopping distance for air brake vehicles includes four components: perception distance (time to see the hazard), reaction distance (time to move your foot to the brake), brake lag distance (time for air to reach the brakes), and braking distance (time for the vehicle to stop once brakes are working).'),
  ('Compared to hydraulic brakes, air brakes require more stopping distance because of:', 'Heavier vehicle weight only', 'Brake lag distance added by the air system', 'Smaller brake drums', 'Lower friction brake materials', 'B', 'Air Brakes', 'medium', 'Air brakes add brake lag distance that hydraulic brakes do not have. It takes time for air to flow through the lines to the brake chambers, adding about one-half second of delay. Hydraulic systems respond almost instantly because fluid does not compress.'),
  ('What is brake fade?', 'Brakes wearing out over time', 'A loss of braking power caused by excessive heat from overuse', 'Air leaking from the brake lines', 'Brake shoes becoming misaligned', 'B', 'Air Brakes', 'medium', 'Brake fade is the loss of braking effectiveness that occurs when brakes overheat from excessive or prolonged use. Heat builds up faster than it can be dissipated, reducing friction between brake linings and drums, making the brakes less effective.'),
  ('When going down a long steep hill, what is the proper braking technique?', 'Apply brakes continuously all the way down', 'Use snub braking by applying brakes to slow 5 mph below your safe speed then release', 'Shift to neutral and coast to save brakes', 'Only use the parking brake', 'B', 'Air Brakes', 'medium', 'The correct technique on long downgrades is snub braking. Apply the brakes firmly enough to reduce your speed to about 5 mph below your safe speed for that grade, then release the brakes. Repeat this process. This helps prevent brake fade from overheating.'),
  ('Why is riding the brakes on a long downgrade dangerous?', 'It can cause the engine to overheat', 'It causes excessive heat buildup leading to brake fade and possible brake failure', 'It damages the transmission', 'It uses too much fuel', 'B', 'Air Brakes', 'medium', 'Riding the brakes (keeping them applied continuously) on a long downgrade causes excessive heat buildup in the brake drums and linings. This leads to brake fade, where the brakes become less effective, and can ultimately result in complete brake failure.'),
  ('What should you do if your brakes fail on a downgrade?', 'Shift to neutral', 'Look for an escape ramp or other way to safely get off the road', 'Turn off the engine', 'Open the door to increase drag', 'B', 'Air Brakes', 'medium', 'If your brakes fail on a downgrade, look for an escape ramp, an open field, or any other safe way to stop. Escape ramps use a long bed of loose material to slow and stop a vehicle. Downshift to use engine braking and do not shift to neutral.'),
  ('In emergency braking with air brakes (no ABS), the best method is to:', 'Brake as hard as possible and hold the pedal down', 'Apply brakes firmly without locking the wheels and steer to safety', 'Pump the brakes rapidly', 'Apply the parking brake immediately', 'B', 'Air Brakes', 'medium', 'During emergency braking without ABS, you should apply the brakes firmly while avoiding wheel lockup. Locked wheels cause skidding and loss of steering control. Controlled braking (braking as hard as you can without locking wheels) is the most effective method.'),
  ('What does ABS (Anti-Lock Braking System) do on air brake equipped vehicles?', 'Automatically stops the vehicle faster', 'Prevents wheel lockup so you maintain steering control during hard braking', 'Eliminates the need for brake maintenance', 'Increases air pressure in the tanks', 'B', 'Air Brakes', 'medium', 'ABS uses sensors on the wheels to detect lockup and automatically reduces and reapplies brake pressure to prevent wheels from locking. This helps the driver maintain steering control during hard braking. ABS does not necessarily shorten stopping distance.'),
  ('Does ABS shorten your stopping distance?', 'Yes, it always shortens stopping distance significantly', 'No, ABS does not necessarily shorten stopping distance', 'Yes, by at least 50 percent', 'Only on wet roads', 'B', 'Air Brakes', 'medium', 'ABS does not necessarily shorten stopping distance. Its primary purpose is to prevent wheel lockup so the driver can maintain steering control during hard braking. On some surfaces, stopping distance may be similar or even slightly longer, but vehicle control is maintained.'),
  ('How should you brake when your vehicle has ABS?', 'Pump the brake pedal rapidly', 'Brake normally and do not let up on the pedal when you feel it pulsing', 'Apply brakes lightly only', 'Use the parking brake instead', 'B', 'Air Brakes', 'medium', 'When braking with ABS, you should brake normally. If you need to stop quickly, press the brake pedal firmly and do not let up, even if you feel the pedal pulsing or vibrating. The pulsing is the ABS working. Do not pump ABS brakes.'),
  ('How can you tell if your vehicle is equipped with ABS?', 'The vehicle will have a yellow ABS malfunction lamp on the instrument panel', 'There will be a special ABS sticker on the steering wheel', 'The brake pedal will be a different color', 'There is no way to tell from the cab', 'A', 'Air Brakes', 'medium', 'Vehicles equipped with ABS have a yellow ABS malfunction lamp on the instrument panel. This lamp comes on at start-up for a bulb check and then turns off. If it stays on, it indicates an ABS malfunction, though normal brakes will still work.'),
  ('How long should it take for air pressure to build from 50 to 90 PSI with the engine at operating RPM?', 'Within 5 minutes', 'Within 10 minutes', 'Within 3 minutes', 'Within 1 minute', 'C', 'Air Brakes', 'medium', 'The air compressor should build air pressure from 50 to 90 PSI within 3 minutes with the engine at operating RPM. If it takes longer, the air compressor or the system may have a problem that needs to be repaired before driving.'),
  ('If the air compressor takes longer than 3 minutes to build pressure from 50 to 90 PSI, this indicates:', 'Normal operation in cold weather', 'A possible problem with the compressor or system that needs repair', 'The governor needs adjustment', 'The safety valve is working correctly', 'B', 'Air Brakes', 'medium', 'If the air compressor cannot build pressure from 50 to 90 PSI within 3 minutes with the engine running at operating RPM, there is likely a problem. Possible causes include a worn compressor, air leaks, or a defective governor.'),
  ('The safety valve in the air brake system opens automatically at:', '100 PSI', '125 PSI', '60 PSI', '150 PSI', 'D', 'Air Brakes', 'medium', 'The safety valve is designed to protect the air system from overpressurization. It opens automatically at 150 PSI to release excess air pressure. If the safety valve must open, something is wrong with the system, likely a malfunctioning governor.'),
  ('If the safety valve has to release air, what is the likely problem?', 'The drain valves are stuck open', 'The governor or compressor unloading mechanism is malfunctioning', 'The brake pedal is stuck', 'The slack adjusters are too tight', 'B', 'Air Brakes', 'medium', 'If the safety valve releases air, it means pressure has exceeded 150 PSI. This likely indicates a malfunctioning governor that is not cutting out the compressor at 125 PSI, or the compressor unloading mechanism has failed.'),
  ('What is the purpose of front brake limiting valves found on some older vehicles?', 'To increase front brake pressure on slippery roads', 'To reduce front brake pressure to prevent front wheel skids on slippery surfaces', 'To lock the front brakes during emergency stops', 'To balance air between the primary and secondary systems', 'B', 'Air Brakes', 'medium', 'Front brake limiting valves were used on older vehicles to reduce air pressure to the front brakes, typically to about 50 percent of normal, on slippery surfaces. This was to help prevent front wheel lockup and loss of steering control.'),
  ('Should you use the front brake limiting valve in the normal or slippery position during normal driving?', 'Always in the slippery position', 'Always in the normal position to have full front braking power', 'It does not matter', 'Only use it when going uphill', 'B', 'Air Brakes', 'medium', 'The front brake limiting valve should be kept in the normal position during everyday driving to take full advantage of front brake stopping power. Reducing front brake pressure unnecessarily increases stopping distance. Many experts advise removing these valves.'),
  ('What are glad hands?', 'The rubber seals on brake chambers', 'Coupling devices that connect air lines between the tractor and trailer', 'Handles on the brake drums for inspection', 'The release valves on air tanks', 'B', 'Air Brakes', 'medium', 'Glad hands are the coupling devices used to connect the air lines between the tractor and trailer in a combination vehicle. They snap together and have rubber seals (grommets) to prevent air leaks at the connection point.'),
  ('What can happen if glad hand connections are not properly sealed?', 'The engine will not start', 'Air leaks that can reduce braking performance or cause brake failure', 'The trailer lights will not work', 'The fifth wheel will not lock', 'B', 'Air Brakes', 'medium', 'Improperly sealed glad hand connections cause air leaks in the brake system. This can lead to reduced air pressure, poor braking performance, and potentially brake failure. Always check that glad hand seals are in good condition and connections are secure.'),
  ('When coupling glad hands, what should you check for?', 'That the rubber seals are in good condition and free of damage', 'That the glad hands are painted the same color', 'That the air lines are the same length', 'That the trailer wheels are chocked on both sides', 'A', 'Air Brakes', 'medium', 'When coupling glad hands, you should inspect the rubber grommets (seals) to make sure they are in good condition and free of cracks, damage, or debris. Damaged seals will cause air leaks that reduce braking ability.'),
  ('What do air brake gauges tell you?', 'The temperature of the brake drums', 'How much air pressure is in the air tanks', 'The thickness of the brake pads', 'How fast the vehicle is going', 'B', 'Air Brakes', 'medium', 'Air brake gauges on the dashboard indicate the amount of air pressure in the air tanks, measured in PSI. In dual air brake systems, there are gauges for each system (primary and secondary). Monitoring these gauges is critical for safe operation.'),
  ('What should you do if the low air pressure warning comes on while driving?', 'Continue driving to the next rest stop', 'Speed up to build air pressure faster', 'Stop and safely park as soon as possible', 'Turn off the warning light and continue', 'C', 'Air Brakes', 'medium', 'If the low air pressure warning activates while driving, you should stop and safely park as soon as possible. Continuing to drive risks a further drop in pressure, which will cause the spring brakes to lock up suddenly, possibly causing a loss of control.'),
  ('What is the slack adjuster used for in an S-cam brake?', 'To adjust the distance between the brake shoes and the drum', 'To connect the air line to the brake chamber', 'To measure air pressure at the wheel', 'To lubricate the brake drum', 'A', 'Air Brakes', 'medium', 'The slack adjuster connects the push rod to the S-cam and is used to adjust the clearance between the brake shoes and the brake drum. Proper adjustment is critical because too much slack means the brakes will not apply fully.'),
  ('What happens to braking ability if the slack adjusters are out of adjustment?', 'Braking will be smoother', 'The brakes may not work properly or could fail because the push rod travels too far', 'The air compressor will build pressure faster', 'Nothing, as the ABS compensates automatically', 'B', 'Air Brakes', 'medium', 'If the slack adjusters are out of adjustment, the push rod has to travel too far to move the brake shoes against the drum. This reduces braking power and can lead to brake failure. Out-of-adjustment brakes are a leading cause of truck accidents.'),
  ('How should you test that the low air pressure warning works during a pre-trip inspection?', 'By turning on the ignition and checking if the light comes on briefly', 'By pumping the brake pedal with the engine off to reduce air pressure and verify the warning activates before 60 PSI', 'By disconnecting an air line', 'By pressing the horn button', 'B', 'Air Brakes', 'medium', 'To test the low air pressure warning, turn the engine off with a fully charged system, then repeatedly press and release the brake pedal to reduce air pressure. The low air pressure warning light and/or buzzer should activate before the pressure drops below 60 PSI.'),
  ('Automatic drain valves on air tanks:', 'Must be manually operated every day', 'Automatically expel water and oil that accumulate in the tanks', 'Regulate the air pressure in the system', 'Are only found on trailer air tanks', 'B', 'Air Brakes', 'medium', 'Automatic drain valves are installed on air tanks to automatically expel accumulated water, oil, and other contaminants. Even with automatic valves, it is good practice to manually drain the tanks periodically to ensure they are working properly.');
INSERT INTO questions (question_text, option_a, option_b, option_c, option_d, correct_answer, category, difficulty, explanation) VALUES
  ('What color is the service air line on a combination vehicle?', 'Red', 'Blue', 'Green', 'Yellow', 'B', 'Combination Vehicles', 'medium', 'The service air line is blue. It carries air controlled by the foot brake or the trailer hand valve to operate the trailer brakes.'),
  ('What color is the emergency (supply) air line on a combination vehicle?', 'Blue', 'Yellow', 'Red', 'Black', 'C', 'Combination Vehicles', 'medium', 'The emergency or supply air line is red. It supplies air to the trailer air tanks and controls the emergency brakes on the trailer.'),
  ('At what PSI range does the tractor protection valve automatically close?', '5-10 PSI', '20-45 PSI', '50-60 PSI', '60-80 PSI', 'B', 'Combination Vehicles', 'medium', 'The tractor protection valve closes automatically when air pressure drops to the range of 20 to 45 PSI. This prevents further loss of air from the tractor and applies the trailer emergency brakes.'),
  ('What is the purpose of the tractor protection valve?', 'To protect the trailer brakes from overheating', 'To keep air in the tractor brake system if the trailer breaks away or develops a bad leak', 'To regulate fuel flow to the engine', 'To lock the kingpin into the fifth wheel', 'B', 'Combination Vehicles', 'medium', 'The tractor protection valve keeps air in the tractor brake system in case the trailer breaks away or develops a serious air leak. It prevents the tractor from losing all its air pressure.'),
  ('What knob color is the trailer air supply control?', 'Blue', 'Yellow', 'Green', 'Red', 'D', 'Combination Vehicles', 'medium', 'The trailer air supply control is a red octagonal knob. Pushing it in supplies air to the trailer, and pulling it out shuts off the air supply and activates the trailer emergency brakes.'),
  ('Why should the trailer hand valve (trolley valve) NOT be used for parking?', 'It uses too much air', 'Air can leak away and release the brakes, allowing the trailer to move', 'It damages the brake drums', 'It is illegal in all states', 'B', 'Combination Vehicles', 'medium', 'The trailer hand valve should never be used for parking because air can leak away over time. If the air leaks out, the brakes will release and the trailer could move. Always use the parking brakes for parking.'),
  ('What should you do immediately after locking the kingpin into the fifth wheel during coupling?', 'Raise the landing gear', 'Connect the air lines', 'Pull the tractor forward gently to test the coupling', 'Connect the electrical cord', 'C', 'Combination Vehicles', 'medium', 'After the kingpin locks into the fifth wheel, you should pull the tractor forward gently to test that the fifth wheel has locked onto the kingpin properly. This tug test is critical to ensure a secure coupling.'),
  ('During the coupling procedure, what height should the trailer be?', 'Higher than the center of the fifth wheel so it is raised when coupled', 'At the same height as the fifth wheel', 'Slightly lower than the center of the fifth wheel so the trailer is raised slightly by the tractor', 'As low as possible to the ground', 'C', 'Combination Vehicles', 'medium', 'The trailer should be at the correct height so that it is raised slightly by the tractor when the tractor backs under it. If the trailer is too low, the tractor may strike and damage the nose of the trailer. If too high, the trailer may not couple correctly.'),
  ('What is the first step when uncoupling a trailer?', 'Lower the landing gear', 'Disconnect the air lines', 'Secure the trailer by chocking wheels or using parking brakes', 'Unlock the fifth wheel', 'C', 'Combination Vehicles', 'medium', 'The first step in uncoupling is to secure the trailer to prevent it from moving. This means applying the trailer parking brakes and, if necessary, chocking the wheels. Safety must come first before disconnecting anything.'),
  ('What should you inspect the fifth wheel for during a pre-trip inspection?', 'Cracks, missing parts, proper greasing, and secure mounting', 'Paint condition and color', 'Brand name and model number', 'Tire tread depth', 'A', 'Combination Vehicles', 'medium', 'During a pre-trip inspection, the fifth wheel should be checked for cracks, missing parts, proper greasing of the plate, and secure mounting to the tractor frame. A damaged fifth wheel can lead to a separation of the tractor and trailer.'),
  ('What does off-tracking mean in combination vehicles?', 'The trailer tires lose traction on wet roads', 'The rear wheels follow a different, shorter path than the front wheels when turning', 'The trailer brakes activate before the tractor brakes', 'The GPS loses the vehicle signal', 'B', 'Combination Vehicles', 'medium', 'Off-tracking means that when a vehicle goes around a corner, the rear wheels follow a shorter path than the front wheels. The longer the vehicle, the more off-tracking occurs. Drivers must make wider turns to compensate.'),
  ('What is the crack-the-whip effect?', 'A sudden acceleration of the tractor', 'The tendency for the last trailer in a multi-trailer combination to amplify movements, making it sway more than the front trailers', 'A technique for backing up a double trailer', 'The sound brakes make when they are worn', 'B', 'Combination Vehicles', 'medium', 'The crack-the-whip effect refers to how the last trailer in a combination amplifies any turning or swerving motion. A small movement at the front becomes a much larger movement at the rear, which can cause the last trailer to roll over.'),
  ('What is rearward amplification?', 'Increased braking power at the rear axle', 'The tendency for the rear trailer in a multi-trailer combination to swing out more during sudden steering movements', 'Louder noise coming from the rear of the vehicle', 'Increased visibility from the rear mirrors', 'B', 'Combination Vehicles', 'medium', 'Rearward amplification is the tendency for the last trailer in a multi-trailer rig to swing out more during sudden steering changes. In doubles, the rear trailer can amplify steering movements up to two times, and in triples, it can be even more.'),
  ('How can you help prevent a jackknife?', 'Brake hard going into curves', 'Avoid over-braking, over-steering, and maintain proper speed for conditions', 'Always use the trailer hand valve when slowing down', 'Drive faster to maintain momentum', 'B', 'Combination Vehicles', 'medium', 'To prevent jackknifing, avoid over-braking, over-steering, and always travel at speeds appropriate for road and weather conditions. Sudden braking or turning can cause the drive wheels to lose traction and the trailer to push the tractor sideways.'),
  ('What happens during a trailer skid?', 'The tractor drive wheels lose traction and slide sideways', 'The trailer wheels lock up and the trailer swings around toward the tractor', 'The front wheels of the tractor lose steering control', 'The engine stalls while the vehicle is in motion', 'B', 'Combination Vehicles', 'medium', 'During a trailer skid, the trailer wheels lock up and the trailer swings sideways, potentially pushing the tractor forward or to the side. This is usually caused by excessive braking or braking on slippery surfaces.'),
  ('What happens during a tractor jackknife?', 'The trailer wheels lock and the trailer slides sideways', 'The tractor drive wheels lose traction and the rear of the tractor slides sideways toward the trailer', 'The front wheels lose traction and the tractor goes straight', 'The fifth wheel unlocks and the trailer separates', 'B', 'Combination Vehicles', 'medium', 'In a tractor jackknife, the tractor drive wheels lose traction and the rear end of the tractor swings sideways. The tractor ends up folding toward the trailer, forming a V shape. This is usually caused by over-braking or driving too fast on slippery roads.'),
  ('What should you do to reduce the risk of rollover when driving a combination vehicle?', 'Accelerate through curves to maintain stability', 'Slow down before curves, ramps, and turns', 'Shift to neutral in curves to reduce engine braking', 'Apply the trailer hand valve in turns', 'B', 'Combination Vehicles', 'medium', 'To reduce rollover risk, slow down before entering curves, highway ramps, and turns. Combination vehicles have a higher center of gravity and are more prone to rollovers than single vehicles. Taking turns and curves at safe speeds is critical.'),
  ('What are glad hands?', 'The hand grips on the trailer doors', 'Coupling devices that connect the air lines between the tractor and trailer', 'Safety chains used to secure the trailer', 'The handles used to crank the landing gear', 'B', 'Combination Vehicles', 'medium', 'Glad hands are the coupling devices used to connect the air lines between the tractor and trailer. They connect the service (blue) and emergency/supply (red) air lines. They must be properly sealed and securely connected to prevent air leaks.'),
  ('What is the purpose of the locking jaws on a fifth wheel?', 'To lock the trailer doors during transport', 'To grip and hold the kingpin securely when coupled', 'To lock the sliding mechanism of the fifth wheel', 'To secure the landing gear in the raised position', 'B', 'Combination Vehicles', 'medium', 'The locking jaws on a fifth wheel close around the kingpin to hold the trailer securely to the tractor. They must be checked during the pre-trip inspection to make sure they are fully closed around the kingpin with no gaps.'),
  ('What is the kingpin?', 'A pin that locks the trailer doors', 'A pin on the underside of the trailer front that locks into the fifth wheel', 'A pin that holds the landing gear in place', 'A pin used to adjust the fifth wheel position', 'B', 'Combination Vehicles', 'medium', 'The kingpin is a large steel pin on the underside of the front of the trailer. It fits into and locks within the fifth wheel on the tractor. It is the main coupling point between the tractor and trailer.'),
  ('When should you connect the air lines during the coupling procedure?', 'Before backing under the trailer', 'After the tug test confirms the coupling is secure', 'Before raising the landing gear', 'After raising the landing gear and before driving', 'B', 'Combination Vehicles', 'medium', 'Air lines should be connected after the tug test confirms the coupling is secure. The general coupling order is: back under the trailer, lock the kingpin, do the tug test, connect air lines, connect the electrical cord, then raise the landing gear.'),
  ('What should you do with the landing gear before driving a coupled combination vehicle?', 'Leave it partially down for stability', 'Raise it fully to provide clearance', 'Remove it from the trailer', 'Lower it to touch the ground', 'B', 'Combination Vehicles', 'medium', 'The landing gear must be fully raised before driving to provide proper ground clearance. Driving with the landing gear down can cause it to catch on railroad tracks, speed bumps, or uneven ground, resulting in serious damage.'),
  ('What is the purpose of landing gear on a trailer?', 'To steer the trailer when backing', 'To support the front of the trailer when it is not coupled to a tractor', 'To provide additional braking power', 'To help the trailer turn corners', 'B', 'Combination Vehicles', 'medium', 'Landing gear supports the front of the trailer when it is not coupled to a tractor. It holds the trailer at the proper height for coupling and prevents the trailer from tipping forward when uncoupled. It must be lowered before uncoupling.'),
  ('Where should shut-off valves be positioned on the rear of the last trailer in a combination?', 'Open', 'Closed', 'Partially open', 'Removed', 'B', 'Combination Vehicles', 'medium', 'Shut-off valves at the rear of the last trailer must be closed. This prevents air from escaping out the back of the last trailer. If left open, the air would leak out and the brakes would not work properly.'),
  ('Where should shut-off valves be positioned on trailers in front of the last trailer in a combination?', 'Closed', 'Open', 'Partially open', 'It does not matter', 'B', 'Combination Vehicles', 'medium', 'Shut-off valves on trailers in front of the last trailer must be open so that air can flow through to the next trailer. Only the shut-off valves at the rear of the last trailer should be closed.'),
  ('What is the upper fifth wheel?', 'The part mounted on the tractor frame', 'The flat plate and kingpin assembly on the underside of the trailer front', 'The release handle on the fifth wheel', 'The locking jaw mechanism', 'B', 'Combination Vehicles', 'medium', 'The upper fifth wheel, also called the upper coupler, is the flat plate on the underside of the front of the trailer that includes the kingpin. It sits on top of the lower fifth wheel which is mounted on the tractor.'),
  ('What is the lower fifth wheel?', 'The kingpin on the trailer', 'The plate and locking mechanism mounted on the tractor frame that receives the kingpin', 'The trailer apron plate', 'The landing gear base plate', 'B', 'Combination Vehicles', 'medium', 'The lower fifth wheel is the V-shaped plate and locking mechanism mounted on the tractor frame. It receives the kingpin from the trailer and locks it in place. It must be properly greased and inspected for cracks and secure mounting.'),
  ('What is the release handle on a fifth wheel used for?', 'To release the trailer brakes', 'To unlock the locking jaws so the kingpin can be released during uncoupling', 'To release the air from the trailer tanks', 'To lower the landing gear', 'B', 'Combination Vehicles', 'medium', 'The release handle on the fifth wheel is pulled to unlock the locking jaws during the uncoupling procedure. This allows the kingpin to slide out of the fifth wheel as the tractor pulls away from the trailer.'),
  ('What is the trailer apron?', 'The mud flap behind the trailer wheels', 'The bottom plate of the trailer front that rests on the fifth wheel', 'The cover over the trailer air tanks', 'The painted area around the trailer doors', 'B', 'Combination Vehicles', 'medium', 'The trailer apron is the flat metal plate on the underside of the trailer front that rests on and slides across the fifth wheel. It should be inspected for damage and should be smooth to allow proper coupling movement.'),
  ('Why is the fifth wheel greased?', 'To prevent the kingpin from locking', 'To reduce friction and allow the trailer to turn freely on the fifth wheel', 'To keep rain water from pooling on the surface', 'To make the fifth wheel easier to inspect', 'B', 'Combination Vehicles', 'medium', 'The fifth wheel is greased to reduce friction between the upper and lower fifth wheel plates. This allows the trailer to pivot and turn smoothly on the tractor. Without proper greasing, steering can be difficult and the plates can wear prematurely.'),
  ('When backing under the trailer during coupling, what speed should you use?', 'Fast to create momentum', 'Moderate speed to save time', 'Back under slowly to avoid hitting the kingpin too hard and damaging equipment', 'Speed does not matter during coupling', 'C', 'Combination Vehicles', 'medium', 'You should always back under the trailer slowly during coupling. Hitting the trailer too hard can damage the kingpin, the fifth wheel, or the trailer itself. Slow and controlled movement ensures a safe and proper coupling.'),
  ('What could happen if you fail to perform a tug test after coupling?', 'The electrical cord may not work', 'The trailer could separate from the tractor while driving if the fifth wheel did not lock properly', 'The landing gear might not retract', 'The trailer brakes will not release', 'B', 'Combination Vehicles', 'medium', 'Failing to perform a tug test could result in the trailer separating from the tractor while driving. The tug test verifies that the fifth wheel locking jaws have fully engaged around the kingpin. This is a critical safety step.'),
  ('When coupling, what should you check after connecting the air lines and before raising the landing gear?', 'That the trailer license plate is current', 'That air is flowing to the trailer by checking for air pressure buildup and listening for leaks', 'That the trailer doors are closed', 'That the fuel tank is full', 'B', 'Combination Vehicles', 'medium', 'After connecting the air lines, you should check that air is flowing properly to the trailer. Listen for air leaks at the connections and check that the trailer air pressure is building up. Leaking connections can lead to brake failure.'),
  ('What is the purpose of the electrical cord connected between the tractor and trailer?', 'To charge the trailer battery for the refrigeration unit', 'To provide power for the trailer lights including brake, turn, and running lights', 'To power the trailer brakes', 'To connect the radio system', 'B', 'Combination Vehicles', 'medium', 'The electrical cord provides power from the tractor to the trailer for all lighting, including brake lights, turn signals, clearance lights, and running lights. Without it, other drivers cannot see the trailer signals, creating a serious safety hazard.'),
  ('During uncoupling, when should you lower the landing gear?', 'After pulling the tractor away from the trailer', 'After disconnecting the air and electrical lines but before unlocking the fifth wheel', 'Before securing the trailer', 'Landing gear does not need to be lowered during uncoupling', 'B', 'Combination Vehicles', 'medium', 'The landing gear should be lowered after disconnecting the air and electrical lines but before unlocking the fifth wheel and pulling out. The landing gear supports the front of the trailer and must be down before the tractor is removed to prevent the trailer from tipping.'),
  ('What is a sliding fifth wheel used for?', 'To make coupling easier', 'To adjust the weight distribution between the tractor and trailer axles to comply with axle weight limits', 'To allow the trailer to slide sideways', 'To increase fuel efficiency', 'B', 'Combination Vehicles', 'medium', 'A sliding fifth wheel can be moved forward or backward on the tractor frame to adjust how much weight is carried by the tractor drive axles versus the trailer axles. This helps comply with bridge laws and axle weight limits.'),
  ('What is the bridge weight formula concerned with?', 'The maximum weight a vehicle can carry across any bridge', 'The maximum weight allowed on a group of axles based on the number of axles and the distance between them', 'The total weight of the bridge structure', 'The distance a vehicle must maintain from other vehicles on a bridge', 'B', 'Combination Vehicles', 'medium', 'The bridge weight formula determines the maximum weight allowed on a group of axles based on the number of axles and the distance between them. It is designed to prevent excessive stress on bridges and road surfaces.'),
  ('What is the proper use of safety chains on a combination vehicle?', 'They replace the kingpin connection', 'They provide a backup connection between the tractor and trailer in case the primary coupling fails, commonly used on converter dollies', 'They are used to secure cargo inside the trailer', 'They are used to lock the trailer doors', 'B', 'Combination Vehicles', 'medium', 'Safety chains are used as a backup connection, particularly on converter dollies, to keep the dolly connected to the front trailer if the primary coupling fails. They should be crossed under the connection point to catch the dolly tongue if it breaks free.'),
  ('What happens when you pull out the trailer air supply control (red knob)?', 'The trailer brakes release', 'Air supply is shut off to the trailer and the trailer emergency brakes apply', 'The engine shuts off', 'The tractor parking brakes release', 'B', 'Combination Vehicles', 'medium', 'Pulling out the red trailer air supply control knob shuts off the air supply to the trailer and activates the trailer emergency brakes via spring force. This is used when parking or in an emergency to stop the trailer.'),
  ('What is a converter dolly?', 'A device that converts air brakes to hydraulic brakes', 'A coupling device with one or two axles and a fifth wheel used to connect a semi-trailer as a full trailer in a double or triple combination', 'A tool for adjusting the fifth wheel height', 'A device that converts a single trailer into a tandem', 'B', 'Combination Vehicles', 'medium', 'A converter dolly is a coupling device with one or two axles and its own fifth wheel. It is used to attach a semi-trailer as the second or third trailer in a double or triple combination. The dolly connects to the rear of the trailer in front.'),
  ('What should you check about the fifth wheel mounting during a pre-trip inspection?', 'That it is painted correctly', 'That there are no cracks or breaks in the mounting structure and all bolts are tight and secure', 'That it has a manufacturer label', 'That the serial number is visible', 'B', 'Combination Vehicles', 'medium', 'During a pre-trip inspection, check that the fifth wheel mounting structure has no cracks or breaks and that all mounting bolts are present, tight, and secure. A compromised mounting can lead to the fifth wheel separating from the tractor.'),
  ('When making a right turn with a combination vehicle, why should you be especially cautious?', 'Because the engine loses power in turns', 'Because off-tracking causes the rear wheels to follow a shorter path, potentially running over the curb or hitting objects', 'Because the trailer brakes activate automatically in turns', 'Because the mirrors cannot show the right side', 'B', 'Combination Vehicles', 'medium', 'Off-tracking is especially dangerous in right turns because the rear wheels cut the corner more sharply than the front wheels. The longer the combination, the greater the off-tracking. Drivers must swing wide enough to avoid running over curbs, pedestrians, or objects.'),
  ('In a triple trailer combination, which trailer is most likely to roll over in a sudden lane change?', 'The first trailer', 'The second trailer', 'The third (last) trailer', 'All trailers roll over equally', 'C', 'Combination Vehicles', 'medium', 'Due to rearward amplification and the crack-the-whip effect, the last trailer in a multi-trailer combination experiences the greatest lateral force during sudden steering maneuvers. In triples, the third trailer can amplify steering input up to three times.'),
  ('What can cause a trailer skid?', 'Under-inflated tires on the tractor', 'Locking up the trailer brakes by using too much brake pressure or having a malfunctioning brake system', 'Driving too slowly', 'Having too much weight on the trailer', 'B', 'Combination Vehicles', 'medium', 'A trailer skid occurs when the trailer wheels lock up and lose traction. This can happen from excessive braking, a malfunctioning trailer brake system, or braking on slippery surfaces. When the trailer wheels lock, the trailer can swing sideways.'),
  ('What is the best way to correct a trailer skid?', 'Apply more brakes to stop the skid', 'Release the brakes to allow the trailer wheels to regain traction and grip the road', 'Steer sharply in the opposite direction', 'Accelerate quickly to pull the trailer straight', 'B', 'Combination Vehicles', 'medium', 'To correct a trailer skid, release the brakes so the trailer wheels can start rolling again and regain traction. Once the wheels are rolling, the trailer will start to follow the tractor and straighten out. Avoid further braking until the skid is corrected.'),
  ('Why should you inspect the glad hands before connecting them?', 'To check their color', 'To make sure the rubber seals are in good condition and the connections are clean and free of debris', 'To verify the brand matches the tractor', 'To ensure they are the correct diameter', 'B', 'Combination Vehicles', 'medium', 'Before connecting glad hands, inspect the rubber seals to make sure they are not damaged, worn, or missing. Also check that the connections are clean and free of dirt or debris. Bad seals or dirty connections can cause air leaks and brake problems.'),
  ('What is the danger of having the trailer too high when coupling?', 'The landing gear may be too short', 'The trailer may not couple correctly and the tractor could end up under the trailer without the kingpin engaging the fifth wheel', 'The electrical cord will not reach', 'The air lines will be too tight', 'B', 'Combination Vehicles', 'medium', 'If the trailer is too high when coupling, the tractor may go under the trailer without the kingpin properly engaging the fifth wheel. This can result in a false coupling where the trailer appears connected but is not secured, which could lead to separation while driving.'),
  ('What can happen if the air lines are crossed when connecting a tractor to a trailer?', 'Nothing, the lines are the same', 'The trailer brakes may not work correctly, creating a dangerous situation', 'The engine will not start', 'The fifth wheel will not lock', 'B', 'Combination Vehicles', 'medium', 'If the air lines are crossed between the tractor and trailer, the brakes will not function properly. The service and supply lines serve different purposes, and crossing them can prevent brakes from applying when needed.'),
  ('How do the emergency brakes on a trailer typically function?', 'They are applied by electrical signals from the tractor', 'They use spring force that engages when air pressure is lost', 'They are manually applied by pulling a cable', 'They use hydraulic fluid from the tractor', 'B', 'Combination Vehicles', 'medium', 'Trailer emergency brakes use powerful springs that are held compressed by air pressure during normal operation. When air pressure drops due to a leak or disconnection, the springs expand and push the brake shoes against the drums to stop the trailer.'),
  ('What should you do if the fifth wheel locking jaws are not securely closed around the kingpin?', 'Drive slowly to the nearest repair shop', 'Do not drive the vehicle until the coupling is properly secured', 'Use safety chains as a temporary fix', 'Apply more grease to help the jaws close', 'B', 'Combination Vehicles', 'medium', 'You must never drive a vehicle if the fifth wheel locking jaws are not fully closed around the kingpin. An improperly secured coupling can result in the trailer separating from the tractor while driving, which is extremely dangerous.');
INSERT INTO questions (question_text, option_a, option_b, option_c, option_d, correct_answer, category, difficulty, explanation) VALUES
  ('During a pre-trip inspection, what should you do with the vehicle inspection report left by the previous driver?', 'Throw it away and start fresh', 'Review it and sign it to acknowledge any defects noted', 'Only read it if the vehicle looks damaged', 'File it without reading', 'B', 'General Knowledge', 'medium', 'You must review the previous driver''s vehicle inspection report and sign it to acknowledge that you have seen it and that any defects noted have been certified as repaired or deemed unnecessary to repair.'),
  ('At 55 mph, what is the approximate total stopping distance for a commercial vehicle on dry pavement?', 'About 200 feet', 'About 300 feet', 'Over 450 feet', 'About 600 feet', 'C', 'General Knowledge', 'medium', 'At 55 mph the total stopping distance is over 450 feet, which includes perception distance (142 feet), reaction distance (61 feet), and braking distance (216 feet). These three distances combined exceed 450 feet.'),
  ('What is the legal blood alcohol concentration (BAC) limit for a CDL driver operating a commercial motor vehicle?', '0.08%', '0.06%', '0.02%', '0.04%', 'D', 'General Knowledge', 'medium', 'The legal BAC limit for CDL holders operating a commercial motor vehicle is 0.04%, which is half the limit for non-commercial drivers in most states.'),
  ('How far ahead do low beam headlights illuminate the road?', '100 feet', '250 feet', '400 feet', '500 feet', 'B', 'General Knowledge', 'medium', 'Low beam headlights illuminate the road approximately 250 feet ahead. This is important for night driving because you should always be able to stop within the distance you can see.'),
  ('What is the minimum fire extinguisher rating required for most commercial motor vehicles?', '2 A:B', '10 B:C', '5 B:C', '3 A:B:C', 'C', 'General Knowledge', 'medium', 'All commercial motor vehicles are required to carry a fire extinguisher with a minimum rating of 5 B:C or higher. The B:C rating means it is effective against flammable liquid and electrical fires.'),
  ('What happens to stopping distance on wet roads compared to dry roads?', 'It stays the same', 'It doubles', 'It triples', 'It increases by 25%', 'B', 'General Knowledge', 'medium', 'Wet roads can double your stopping distance. Reduced tire traction on wet pavement means it takes significantly longer to bring your vehicle to a complete stop, so you should reduce speed and increase following distance.'),
  ('At speeds below 40 mph, what is the recommended following distance rule for a commercial vehicle?', '1 second for every 5 feet of vehicle length', '1 second for every 10 feet of vehicle length', '2 seconds for every 10 feet of vehicle length', 'A flat 4 seconds regardless of vehicle length', 'B', 'General Knowledge', 'medium', 'At speeds below 40 mph, you should maintain at least 1 second of following distance for every 10 feet of vehicle length. For example, a 60-foot vehicle should maintain at least 6 seconds of following distance.'),
  ('When driving above 40 mph, how should you adjust the following distance rule?', 'No adjustment is needed', 'Add 1 additional second to the standard following distance', 'Double the entire following distance', 'Add 3 additional seconds', 'B', 'General Knowledge', 'medium', 'At speeds above 40 mph, you should add 1 additional second to the following distance calculated by the 1-second-per-10-feet rule. This extra second accounts for the increased stopping distance at higher speeds.'),
  ('At what speed can hydroplaning begin to occur?', '50 mph', '45 mph', '40 mph', '30 mph', 'D', 'General Knowledge', 'medium', 'Hydroplaning can occur at speeds as low as 30 mph when there is standing water on the road surface. When your tires lose contact with the road and ride on a film of water, you lose steering and braking control.'),
  ('What is the maximum legal weight allowed on a single axle?', '12,000 lbs', '20,000 lbs', '34,000 lbs', '40,000 lbs', 'B', 'General Knowledge', 'medium', 'The maximum weight generally allowed on a single axle is 20,000 lbs. Exceeding this limit can cause damage to roads and bridges and is a violation of federal weight regulations.'),
  ('What is the maximum legal weight allowed on a tandem axle?', '20,000 lbs', '34,000 lbs', '40,000 lbs', '44,000 lbs', 'B', 'General Knowledge', 'medium', 'The maximum weight generally allowed on a tandem axle is 34,000 lbs. Tandem axles distribute the load over a wider area, allowing for more weight than a single axle.'),
  ('What is the maximum gross vehicle weight generally allowed on public roads?', '60,000 lbs', '70,000 lbs', '80,000 lbs', '90,000 lbs', 'C', 'General Knowledge', 'medium', 'The maximum gross vehicle weight generally allowed on the Interstate highway system is 80,000 lbs. Some states may allow heavier loads with special permits on certain roads.'),
  ('Compared to a passenger car, how much more stopping distance does a loaded truck need?', 'About the same distance', 'About twice the distance', '3 to 4 times the distance', '5 to 6 times the distance', 'C', 'General Knowledge', 'medium', 'A loaded truck traveling at the same speed as a car requires 3 to 4 times the stopping distance. This is due to the greater weight and inertia of a fully loaded commercial vehicle.'),
  ('A GVWR over 26,001 lbs requires what class of CDL?', 'Class C only', 'Class A or B', 'Class D', 'No CDL is required', 'B', 'General Knowledge', 'medium', 'A vehicle with a Gross Vehicle Weight Rating (GVWR) over 26,001 lbs requires a Class A or Class B CDL. Class A is needed when towing a trailer over 10,000 lbs GVWR, while Class B covers single vehicles over 26,001 lbs.'),
  ('When must a driver complete a written vehicle condition report?', 'Only when defects are found', 'At the end of each driving day', 'Once a week', 'Only after an accident', 'B', 'General Knowledge', 'medium', 'Drivers of commercial motor vehicles must complete a written vehicle condition report at the end of each driving day. This report documents the condition of the vehicle and any defects found.'),
  ('What is the perception distance at 55 mph?', '61 feet', '142 feet', '216 feet', '100 feet', 'B', 'General Knowledge', 'medium', 'At 55 mph, perception distance is approximately 142 feet. This is the distance your vehicle travels from the time your eyes see a hazard until your brain recognizes it as a hazard.'),
  ('What is the reaction distance at 55 mph?', '142 feet', '61 feet', '216 feet', '45 feet', 'B', 'General Knowledge', 'medium', 'At 55 mph, reaction distance is approximately 61 feet. This is the distance your vehicle travels from the time your brain recognizes a hazard until your foot physically pushes the brake pedal.'),
  ('What is the braking distance at 55 mph on dry pavement?', '142 feet', '61 feet', '216 feet', '300 feet', 'C', 'General Knowledge', 'medium', 'At 55 mph, the braking distance on dry pavement is approximately 216 feet. This is the distance it takes for the vehicle to come to a complete stop once the brakes are applied.'),
  ('What should you do first if you experience a tire blowout while driving?', 'Slam on the brakes immediately', 'Hold the steering wheel firmly and stay off the brakes until the vehicle slows', 'Swerve to the shoulder immediately', 'Shift into neutral immediately', 'B', 'General Knowledge', 'medium', 'When a tire blows out, you should hold the steering wheel firmly with both hands and stay off the brakes. Let the vehicle slow down gradually, then gently brake and pull off the road. Braking hard can cause loss of control.'),
  ('How far ahead can high beam headlights illuminate the road?', '250 feet', '150 feet', '350 to 500 feet', '600 to 800 feet', 'C', 'General Knowledge', 'medium', 'High beam headlights can illuminate the road approximately 350 to 500 feet ahead. You should use high beams whenever it is safe and legal to do so, switching to low beams when oncoming traffic approaches.'),
  ('What is the BAC limit for a CDL driver who is under 21 years of age?', '0.04%', '0.08%', '0.02%', '0.00%', 'C', 'General Knowledge', 'medium', 'CDL drivers under 21 years of age have a BAC limit of 0.02%. This stricter limit reflects the zero-tolerance approach to underage drinking and driving.'),
  ('Which of the following is a key step in a pre-trip inspection?', 'Check only the tires and lights', 'Walk around the vehicle and inspect all major components systematically', 'Start the engine and listen for problems only', 'Check the mirrors and leave', 'B', 'General Knowledge', 'medium', 'A proper pre-trip inspection requires walking around the entire vehicle and systematically inspecting all major components including tires, lights, brakes, steering, suspension, coupling devices, cargo securement, and fluid levels.'),
  ('When driving on a steep downgrade, what is the proper technique to control speed?', 'Use only the brakes to control your speed', 'Shift to a lower gear before the descent and use engine braking', 'Put the transmission in neutral and coast', 'Maintain your highway speed and brake at the bottom', 'B', 'General Knowledge', 'medium', 'Before starting down a steep grade, you should shift into a lower gear that will allow the engine to help control your speed. Use engine braking (and the engine brake or jake brake if equipped) as the primary method, applying the service brakes only as a supplement.'),
  ('What should you do when approaching a railroad crossing in a commercial vehicle?', 'Speed up to cross quickly', 'Slow down and prepare to stop, look and listen for trains', 'Stop only if you see a train coming', 'Honk your horn and proceed', 'B', 'General Knowledge', 'medium', 'When approaching a railroad crossing, you should slow down, look both directions, and listen for approaching trains. Some commercial vehicles are required by law to stop at all railroad crossings regardless of whether signals are active.'),
  ('During an en-route inspection, which of the following should you check?', 'Only fuel level', 'Tires, brakes, lights, cargo securement, and coupling devices', 'Only the mirrors', 'Only the engine oil', 'B', 'General Knowledge', 'medium', 'During en-route inspections you should check tires, brakes, lights, cargo securement, coupling devices, and any other safety-critical components. You should perform these checks within the first 50 miles and periodically thereafter.'),
  ('What is the primary purpose of a post-trip inspection?', 'To find defects that could make the vehicle unsafe or cause a breakdown', 'To check the fuel level for the next trip', 'To clean the vehicle interior', 'To verify mileage for payroll', 'A', 'General Knowledge', 'medium', 'The primary purpose of a post-trip inspection is to identify any defects or damage that could make the vehicle unsafe to operate or could lead to a breakdown. Any defects found must be documented on the vehicle condition report.'),
  ('When should you downshift an automatic or manual transmission for a curve?', 'While in the curve', 'After exiting the curve', 'Before entering the curve', 'Only on wet roads', 'C', 'General Knowledge', 'medium', 'You should downshift before entering a curve, not during the curve. Downshifting while in a curve can cause a loss of traction and lead to a skid. Slow down and shift before the curve, then accelerate gently through it.'),
  ('What is the most important reason to properly secure cargo?', 'To avoid a fine', 'To prevent cargo from shifting or falling and causing an accident or injury', 'To make the vehicle look professional', 'To reduce fuel consumption', 'B', 'General Knowledge', 'medium', 'The most important reason to secure cargo properly is to prevent it from shifting, falling, or spilling, which could cause an accident, injury, or death. Improperly secured cargo is a serious safety hazard to you and other motorists.'),
  ('In foggy conditions, what should you do?', 'Use high beam headlights for maximum visibility', 'Use low beam headlights, reduce speed, and increase following distance', 'Maintain normal speed and use hazard flashers', 'Pull over and wait for the fog to clear in all cases', 'B', 'General Knowledge', 'medium', 'In fog, you should use low beam headlights (high beams reflect off fog and reduce visibility), significantly reduce speed, and increase your following distance. If visibility becomes too poor, pull over to a safe location.'),
  ('What is the correct action when your drive wheels begin to skid?', 'Accelerate to pull out of the skid', 'Brake harder to stop the skid', 'Stop braking, turn the steering wheel in the direction of the skid, and counter-steer', 'Shift into a higher gear', 'C', 'General Knowledge', 'medium', 'When drive wheels skid, you should take your foot off the brake (or accelerator if an acceleration skid), and steer in the direction you want the vehicle to go. This technique allows the tires to regain traction.'),
  ('How should you use your horn to communicate with other drivers?', 'Only in emergencies', 'Lightly tap the horn to make others aware of your presence when needed', 'Use long blasts to warn distracted drivers', 'Never use your horn near residential areas', 'B', 'General Knowledge', 'medium', 'You should use your horn to alert other road users of your presence when necessary. A light tap is usually sufficient to make drivers aware of you, such as when someone is about to merge into your lane or at blind intersections.'),
  ('What is the leading cause of fatal crashes involving commercial vehicles?', 'Mechanical failure', 'Bad weather', 'Distracted driving and driver fatigue', 'Road construction', 'C', 'General Knowledge', 'medium', 'Driver-related factors such as distracted driving and fatigue are the leading causes of fatal crashes involving commercial vehicles. Staying alert, well-rested, and focused on driving is critical for safety.'),
  ('What should you do if your brakes fail on a downhill grade?', 'Pump the brakes rapidly, downshift, and look for an escape ramp', 'Turn off the engine', 'Jump from the vehicle', 'Steer into oncoming traffic to slow down', 'A', 'General Knowledge', 'medium', 'If your brakes fail going downhill, you should pump the brake pedal rapidly to try to build pressure, downshift to use engine braking, and look for an escape ramp or an upgrade that will slow the vehicle. Using the escape ramp is your safest option if available.'),
  ('When driving at night, you should adjust your speed so you can stop within what distance?', 'The distance you can see ahead with your headlights', '500 feet regardless of visibility', 'The posted speed limit distance', 'Twice the posted speed limit distance', 'A', 'General Knowledge', 'medium', 'You should always drive at a speed that allows you to stop within the distance illuminated by your headlights. Overdriving your headlights means you cannot stop in time if an obstacle appears in your path.'),
  ('What type of fire extinguisher is required on a commercial vehicle, and what types of fires can it fight?', 'Type A only, for paper and wood fires', 'Type B:C, for flammable liquid and electrical fires', 'Type D, for metal fires', 'Type K, for kitchen fires', 'B', 'General Knowledge', 'medium', 'Commercial vehicles must carry a B:C rated fire extinguisher (5 B:C minimum). The B rating covers flammable liquids like gasoline and diesel, and the C rating covers electrical fires, which are the most common fire types encountered on commercial vehicles.'),
  ('What is the first thing you should do at the scene of an accident?', 'Move your vehicle out of the way immediately', 'Protect the area to prevent further accidents by setting out warning devices', 'Call your dispatcher', 'Begin cleaning up debris', 'B', 'General Knowledge', 'medium', 'The first priority at an accident scene is to protect the area to prevent additional crashes. Set out reflective triangles or other warning devices to alert approaching traffic. Then care for the injured and notify authorities.'),
  ('Where should reflective triangles be placed when your vehicle is stopped on the roadside?', 'Only behind the vehicle', 'Within 10 feet of the front, 100 feet behind, and 100 feet ahead of the vehicle', 'Within 10 feet of the rear, 100 feet behind, and 200 feet behind the vehicle on a two-lane road', 'Only in front of the vehicle', 'C', 'General Knowledge', 'medium', 'Reflective triangles should be placed within 10 feet of the rear of the vehicle, approximately 100 feet behind, and approximately 100 feet ahead (or 200 feet behind on an undivided two-lane road). This provides adequate warning for approaching traffic from both directions.'),
  ('Which of these is a common cause of vehicle fires?', 'Under-inflated tires and fuel leaks', 'Overinflated tires', 'Using low beam headlights at night', 'Driving with windows open', 'A', 'General Knowledge', 'medium', 'Under-inflated tires can overheat and catch fire, and fuel leaks near hot engine components are a major fire risk. Regular inspections of tires, fuel lines, and electrical systems help prevent vehicle fires.'),
  ('When loading cargo, where should the heaviest items be placed?', 'At the rear of the trailer', 'On top of lighter cargo', 'As low and as close to the center of the vehicle as possible', 'Near the doors for easy unloading', 'C', 'General Knowledge', 'medium', 'The heaviest cargo should be placed as low as possible and as close to the center (longitudinally) of the vehicle as practical. This keeps the center of gravity low and centered, improving vehicle stability and handling.'),
  ('What does double-clutching involve when shifting gears?', 'Pressing the clutch twice quickly before shifting', 'Releasing the clutch into neutral, then pressing the clutch again to shift into the next gear', 'Using two feet on the clutch pedal', 'Skipping gears in a transmission', 'B', 'General Knowledge', 'medium', 'Double-clutching requires pressing the clutch to move the gearshift to neutral, releasing the clutch briefly to allow engine and gear speeds to synchronize, then pressing the clutch again to move into the next gear. This technique is used in non-synchronized transmissions common in commercial vehicles.'),
  ('What is the purpose of a jake brake (engine retarder)?', 'To increase engine power on upgrades', 'To help slow the vehicle without using the service brakes', 'To improve fuel economy', 'To warm up the engine faster', 'B', 'General Knowledge', 'medium', 'A jake brake (engine retarder) helps slow the vehicle by using the engine''s compression as a braking force. This reduces wear on the service brakes, which is especially valuable during long downhill descents in mountain driving.'),
  ('What should you inspect on your tires during a pre-trip inspection?', 'Only tire pressure', 'Tread depth, air pressure, cuts, bulges, and proper inflation', 'Only whether the tires are the correct size', 'Only that the valve stems are present', 'B', 'General Knowledge', 'medium', 'During a pre-trip inspection, tires should be checked for proper tread depth (minimum 4/32 inch on steer tires, 2/32 inch on other tires), correct air pressure, cuts, bulges, missing valve caps, and signs of uneven wear.'),
  ('What is the minimum number of tie-downs required for cargo that is 10 feet long?', '1 tie-down', '2 tie-downs', '3 tie-downs', '4 tie-downs', 'B', 'General Knowledge', 'medium', 'Cargo must be secured with at least one tie-down for every 10 feet of cargo length, with a minimum of two tie-downs regardless of cargo length. A 10-foot piece of cargo therefore requires at least 2 tie-downs.'),
  ('Under Hours of Service regulations, what is the maximum number of hours a property-carrying driver may drive after being on duty for a consecutive period?', '10 hours', '11 hours', '13 hours', '14 hours', 'B', 'General Knowledge', 'medium', 'Under current Hours of Service regulations, a property-carrying CMV driver may drive a maximum of 11 hours after 10 consecutive hours off duty. The 11-hour driving limit is a core HOS rule.'),
  ('Under HOS rules, after how many consecutive hours on duty must a property-carrying driver stop driving?', '11 hours', '13 hours', '14 hours', '16 hours', 'C', 'General Knowledge', 'medium', 'A property-carrying driver must not drive after the 14th consecutive hour after coming on duty following 10 consecutive hours off duty. This 14-hour window cannot be extended with off-duty time.'),
  ('What is a driver required to do before putting out a vehicle fire?', 'Call 911 first in all cases', 'Know what is burning and use the correct type of extinguisher', 'Remove all cargo first', 'Drive to the nearest fire station', 'B', 'General Knowledge', 'medium', 'Before fighting a vehicle fire you must know what is burning so you can use the correct extinguisher type. Using the wrong extinguisher (such as water on an electrical or grease fire) can make the fire worse or create additional hazards.'),
  ('Which vehicle system is most critical to inspect for proper operation before driving?', 'Air conditioning system', 'Entertainment system', 'Braking system', 'Power window system', 'C', 'General Knowledge', 'medium', 'The braking system is the most critical safety system on a commercial vehicle. During pre-trip inspection, you must check brake components including shoes, drums, hoses, slack adjusters, air pressure, and low-pressure warning devices.'),
  ('When driving on icy roads, what is the safest practice?', 'Reduce speed to a crawl and increase following distance dramatically', 'Maintain normal speed but increase following distance', 'Drive at the posted speed limit and brake gently', 'Use cruise control for steady speed', 'A', 'General Knowledge', 'medium', 'On icy roads, you should reduce speed to a crawl, avoid sudden movements of the steering wheel or brakes, and increase your following distance dramatically. Ice can make stopping nearly impossible at higher speeds.'),
  ('You are driving a 50-foot vehicle at 35 mph. What is the minimum safe following distance?', '3 seconds', '4 seconds', '5 seconds', '7 seconds', 'C', 'General Knowledge', 'medium', 'At speeds under 40 mph, the rule is 1 second for every 10 feet of vehicle length. A 50-foot vehicle needs at least 5 seconds of following distance. Since 35 mph is under 40 mph, no additional second is required.'),
  ('What is the main advantage of using turn signals well in advance of a turn or lane change?', 'It is only required by law and has no practical benefit', 'It gives other drivers time to react and adjust to your intended movement', 'It activates the vehicle anti-lock braking system', 'It reduces your blind spot', 'B', 'General Knowledge', 'medium', 'Signaling well in advance gives other drivers time to see your signal and adjust their driving. For large commercial vehicles, early signaling is especially important because these vehicles need more time and space to complete turns and lane changes.');
INSERT INTO questions (question_text, option_a, option_b, option_c, option_d, correct_answer, category, difficulty, explanation) VALUES
  ('How many steps are in the standard CDL pre-trip inspection method?', 'Five', 'Six', 'Seven', 'Eight', 'C', 'General Knowledge', 'medium', 'The standard CDL pre-trip inspection follows a seven-step method designed to ensure every critical component of the vehicle is checked before driving.'),
  ('What is the first step of the seven-step inspection method?', 'Start the engine and check gauges', 'Check the engine compartment', 'Vehicle overview and approach', 'Walk-around inspection', 'C', 'General Knowledge', 'medium', 'Step 1 is the vehicle overview and approach. As you walk toward the vehicle, you should look for damage, leaning, leaks under the vehicle, and hazards in the area around the vehicle.'),
  ('During the vehicle overview (Step 1), what should you look for as you approach the vehicle?', 'Only tire condition', 'Damage, leaning, leaks, and surrounding hazards', 'Only fluid leaks', 'Only body damage', 'B', 'General Knowledge', 'medium', 'During the vehicle overview approach, you should look for signs of damage, whether the vehicle is leaning to one side, any leaks underneath the vehicle, and any hazards in the surrounding area such as low wires or branches.'),
  ('What does it indicate if the vehicle is leaning to one side during the approach inspection?', 'Normal tire wear', 'Possible flat tire, overloaded cargo, or suspension failure', 'The road is uneven', 'The vehicle was recently washed', 'B', 'General Knowledge', 'medium', 'A vehicle leaning to one side can indicate a flat tire, improperly loaded or shifted cargo, or a suspension system failure. Any of these conditions must be investigated and corrected before driving.'),
  ('What is Step 2 of the seven-step inspection method?', 'Walk-around inspection', 'Check engine compartment', 'In-cab inspection', 'Check signal lights', 'B', 'General Knowledge', 'medium', 'Step 2 is checking the engine compartment. You should inspect power steering fluid, coolant level, oil level, belts, hoses, the battery, and wiring before starting the engine.'),
  ('What is the maximum allowable play in engine belts during the engine compartment inspection?', '1/4 inch', '1/2 inch', '3/4 inch', '1 inch', 'B', 'General Knowledge', 'medium', 'Belts should have no more than 1/2 inch of play when pressed. Excessive belt play can lead to belt slippage, which may cause overheating, loss of power steering, or alternator failure.'),
  ('Which fluids should you check during the engine compartment inspection?', 'Only engine oil', 'Only coolant and oil', 'Power steering fluid, coolant, and engine oil', 'Only transmission fluid', 'C', 'General Knowledge', 'medium', 'During the engine compartment inspection, you should check the power steering fluid, coolant level, and engine oil level. All fluids must be at proper levels to ensure safe vehicle operation.'),
  ('What should you inspect on the battery during the engine compartment check?', 'Only the battery brand', 'Secure mounting, connections, and no corrosion or leaks', 'Only the voltage reading', 'Only the manufacture date', 'B', 'General Knowledge', 'medium', 'During the engine compartment inspection, verify the battery is securely mounted, the connections are tight and free of corrosion, and there are no cracks or leaks in the battery casing.'),
  ('What is Step 3 of the seven-step inspection method?', 'Walk-around inspection', 'Engine compartment check', 'Start engine and in-cab inspection', 'Check lights', 'C', 'General Knowledge', 'medium', 'Step 3 involves starting the engine and performing an in-cab inspection. This includes checking gauges, controls, mirrors, the windshield, wipers, and all dashboard warning lights.'),
  ('After starting the engine, oil pressure should come up to normal within what time frame?', 'Within seconds', 'Within 2 minutes', 'Within 5 minutes', 'Within 10 minutes', 'A', 'General Knowledge', 'medium', 'Oil pressure should come up to the normal operating range within seconds of starting the engine. If oil pressure does not register quickly, shut off the engine immediately to prevent serious engine damage.'),
  ('During the in-cab inspection, what should you verify about the mirrors?', 'They are the correct brand', 'They are properly adjusted, clean, and not damaged', 'They are tinted', 'They have heating elements', 'B', 'General Knowledge', 'medium', 'Mirrors must be properly adjusted to minimize blind spots, clean for clear visibility, and free of cracks or damage. Proper mirror adjustment is essential for safe lane changes and maneuvering.'),
  ('What gauges should you check during the in-cab inspection?', 'Only the speedometer', 'Only the fuel gauge', 'Oil pressure, temperature, ammeter/voltmeter, and air pressure gauges', 'Only the tachometer', 'C', 'General Knowledge', 'medium', 'During the in-cab inspection, you must check the oil pressure gauge, temperature gauge, ammeter or voltmeter, and air pressure gauge. All gauges must be in their normal operating ranges.'),
  ('What is Step 4 of the seven-step inspection method?', 'Walk-around inspection', 'Check signal lights', 'Turn off engine and check lights', 'Start the engine', 'C', 'General Knowledge', 'medium', 'Step 4 is to turn off the engine and check the lights. You should turn on the headlights and four-way flashers, then get out and check that all lights are working properly and are the correct color.'),
  ('What is Step 5 of the seven-step inspection method?', 'Check signal lights', 'Walk-around inspection', 'Brake check', 'Engine compartment check', 'B', 'General Knowledge', 'medium', 'Step 5 is the walk-around inspection. This is the most comprehensive step where you inspect tires, wheels, lug nuts, suspension, brakes, axles, frame, exhaust, fuel tank, and coupling devices.'),
  ('What is the minimum tread depth required on steer tires?', '2/32 inch', '4/32 inch', '6/32 inch', '8/32 inch', 'B', 'General Knowledge', 'medium', 'Steer (front) tires must have a minimum tread depth of 4/32 inch. Steer tires have a higher requirement because they are critical for steering control, especially on wet or slippery surfaces.'),
  ('What is the minimum tread depth required on tires other than the steer axle?', '1/32 inch', '2/32 inch', '4/32 inch', '6/32 inch', 'B', 'General Knowledge', 'medium', 'All tires other than steer axle tires must have a minimum tread depth of 2/32 inch. Tires below this minimum are unsafe and illegal to operate on public roads.'),
  ('During tire inspection, what defects should you look for besides tread depth?', 'Only tire brand', 'Proper inflation, cuts, bulges, and condition of valve stems', 'Only tire age', 'Only tire size', 'B', 'General Knowledge', 'medium', 'When inspecting tires, check for proper inflation, cuts or slashes in the sidewalls, bulges that may indicate internal damage, and the condition of valve stems. All of these can lead to tire failure if not addressed.'),
  ('What do rust streaks around lug nuts indicate?', 'Normal wear', 'The lug nuts may be loose', 'The vehicle was recently in rain', 'The lug nuts are new', 'B', 'General Knowledge', 'medium', 'Rust streaks coming from the lug nuts are a telltale sign that the lug nuts may be loose. Loose lug nuts can lead to wheel separation, which is an extremely dangerous situation.'),
  ('What should you look for when inspecting wheels and rims?', 'Only the wheel size', 'Cracks, dents, missing or broken lugs, and signs of misalignment', 'Only the rim color', 'Only the wheel weight', 'B', 'General Knowledge', 'medium', 'Inspect wheels and rims for cracks, dents, out-of-round conditions, missing or broken lug nuts, and any signs of misalignment. Damaged wheels can fail catastrophically at highway speeds.'),
  ('What components should be inspected as part of the suspension system?', 'Only the tires', 'Springs, air bags, shock absorbers, and torque rods', 'Only the frame', 'Only the axles', 'B', 'General Knowledge', 'medium', 'The suspension system inspection should cover leaf springs (for cracks or missing leaves), air bags (for leaks or damage), shock absorbers (for leaks), and torque rods and bushings (for wear or damage).'),
  ('What is the maximum allowable play in brake slack adjusters?', '1/2 inch', '1 inch', '1-1/2 inches', '2 inches', 'B', 'General Knowledge', 'medium', 'Slack adjusters should have no more than approximately 1 inch of play when pulled by hand. Excessive slack adjuster travel means the brakes are out of adjustment and may not provide adequate stopping power.'),
  ('During brake inspection, what components should you check?', 'Only brake pads', 'Brake pads or shoes, drums or rotors, hoses, and slack adjusters', 'Only brake fluid', 'Only the brake pedal', 'B', 'General Knowledge', 'medium', 'A thorough brake inspection includes checking brake pads or shoes for wear, drums or rotors for cracks or damage, brake hoses for leaks or wear, and slack adjusters for proper adjustment.'),
  ('What is the maximum allowable steering wheel play for a vehicle with power steering?', '5 degrees', '10 degrees', '15 degrees', '20 degrees', 'B', 'General Knowledge', 'medium', 'For a vehicle with power steering, the steering wheel should have no more than 10 degrees of play (approximately 2 inches of movement on a 20-inch steering wheel) before the front wheels begin to move.'),
  ('What components are part of the steering system inspection?', 'Only the steering wheel', 'Steering box, power steering hoses and fluid, linkage, and steering play', 'Only the tires', 'Only the tie rods', 'B', 'General Knowledge', 'medium', 'The steering system inspection includes the steering box (for leaks and secure mounting), power steering hoses and fluid level, all linkage components (for wear and damage), and checking for excessive steering wheel play.'),
  ('What is Step 6 of the seven-step inspection method?', 'Brake check', 'Walk-around inspection', 'Check signal lights', 'Engine compartment check', 'C', 'General Knowledge', 'medium', 'Step 6 is checking the signal lights. Have someone observe from outside or use a wall reflection to verify that turn signals, brake lights, and four-way flashers are all working properly.'),
  ('What is Step 7 of the seven-step inspection method?', 'Check the engine', 'Walk-around inspection', 'Brake check', 'Check signal lights', 'C', 'General Knowledge', 'medium', 'Step 7 is the brake check. This includes testing the parking brake, service brake, and for vehicles with air brakes, performing specific air brake tests to ensure the braking system is functioning properly.'),
  ('How do you test the parking brake during Step 7?', 'Press the service brake pedal', 'Engage the parking brake, then gently try to move the vehicle in a low gear', 'Rev the engine', 'Flash the headlights', 'B', 'General Knowledge', 'medium', 'To test the parking brake, apply it with the vehicle stopped, then gently try to move the vehicle forward in a low gear. The parking brake should hold the vehicle in place. If it does not, the parking brake needs repair.'),
  ('How do you test the service brake during Step 7?', 'Only check the brake fluid level', 'Drive at about 5 mph and firmly apply the brakes to check for pulling, unusual feel, or delayed stopping', 'Press the brake pedal while parked only', 'Only check the brake lights', 'B', 'General Knowledge', 'medium', 'To test the service brakes, drive the vehicle forward at about 5 mph and firmly apply the brakes. The vehicle should stop smoothly and promptly without pulling to one side, making unusual noises, or feeling spongy.'),
  ('For air brake vehicles, air pressure must build from 50 to 90 psi within what time frame?', '1 minute', '2 minutes', '3 minutes', '5 minutes', 'C', 'General Knowledge', 'medium', 'Air pressure must build from 50 to 90 psi within 3 minutes with the engine at operating RPM. If it takes longer, the air compressor may be defective or there may be a leak in the system.'),
  ('At what psi range should the governor cut out the air compressor?', '80-100 psi', '100-120 psi', '120-140 psi', '140-160 psi', 'C', 'General Knowledge', 'medium', 'The governor should cut out the air compressor at approximately 120 to 140 psi. This prevents over-pressurization of the air brake system. If the compressor does not cut out in this range, the system needs repair.'),
  ('The low air pressure warning device must activate before air pressure drops below what level?', '40 psi', '50 psi', '60 psi', '80 psi', 'C', 'General Knowledge', 'medium', 'The low air pressure warning signal must activate before the air pressure drops below 60 psi. This warning gives the driver time to safely stop the vehicle before air pressure drops low enough for the spring brakes to lock.'),
  ('At what pressure should the safety relief (pop-off) valve open?', '100 psi', '120 psi', '140 psi', '150 psi', 'D', 'General Knowledge', 'medium', 'The safety relief valve is designed to open at approximately 150 psi to protect the air system from over-pressurization. If the governor fails to cut out the compressor, the safety valve prevents dangerous pressure buildup.'),
  ('What should you check regarding ABS indicator lights during the in-cab inspection?', 'ABS lights should stay on while driving', 'ABS light on the dash should come on during the bulb check at startup and then turn off', 'ABS lights should flash continuously', 'ABS lights are not important to check', 'B', 'General Knowledge', 'medium', 'The ABS indicator light on the dashboard should illuminate briefly when you turn on the ignition as part of the bulb check, and then turn off. If the light stays on, it indicates a malfunction in the ABS system.'),
  ('What should you inspect regarding the exhaust system during the walk-around?', 'Only the muffler brand', 'Check for leaks, loose parts, damage, and that it is properly mounted', 'Only the tailpipe size', 'Exhaust inspection is not required', 'B', 'General Knowledge', 'medium', 'Inspect the exhaust system for leaks at connections, loose or broken mounting brackets, holes or cracks in the muffler or pipes, and any signs of exhaust blowing against wiring or fuel lines, which creates a fire hazard.'),
  ('Why are exhaust leaks particularly dangerous?', 'They reduce fuel economy', 'Exhaust fumes can enter the cab and cause driver drowsiness or carbon monoxide poisoning', 'They make the vehicle louder', 'They are only a cosmetic issue', 'B', 'General Knowledge', 'medium', 'Exhaust leaks are extremely dangerous because exhaust fumes, including carbon monoxide, can enter the cab. Carbon monoxide is odorless and colorless and can cause drowsiness, impaired judgment, unconsciousness, or death.'),
  ('What should you look for when inspecting the frame and cross members?', 'Only the paint condition', 'Cracks, bends, broken welds, holes, and loose or missing bolts', 'Only the frame color', 'Frame inspection is not part of pre-trip', 'B', 'General Knowledge', 'medium', 'Inspect the frame and cross members for cracks, bends, broken welds, holes from corrosion, and any loose or missing bolts or fasteners. The frame is the structural backbone of the vehicle and must be in sound condition.'),
  ('What electrical components should be inspected during the walk-around?', 'Only the headlights', 'Wiring for damage, all lights functioning, reflectors clean and present, and reflective tape intact', 'Only the battery', 'Only the turn signals', 'B', 'General Knowledge', 'medium', 'The electrical system inspection includes checking wiring for loose connections or damage, verifying all lights are functioning and the correct color, ensuring reflectors are clean and present, and confirming reflective tape is intact.'),
  ('What minimum rating must the fire extinguisher carry on a commercial vehicle?', '2 B:C', '5 B:C', '10 B:C', '20 B:C', 'B', 'General Knowledge', 'medium', 'The fire extinguisher on a commercial vehicle must be rated at least 5 B:C. The B rating covers flammable liquid fires and the C rating covers electrical fires. The extinguisher must also be securely mounted, easily accessible, and fully charged.'),
  ('What emergency equipment is required on a commercial vehicle?', 'Only a fire extinguisher', 'Fire extinguisher rated 5 B:C, spare electrical fuses, and three reflective warning triangles', 'Only warning triangles', 'Only spare fuses', 'B', 'General Knowledge', 'medium', 'Federal regulations require a fire extinguisher rated at least 5 B:C, spare electrical fuses (unless the vehicle has circuit breakers), and three reflective warning triangles for roadside emergencies.'),
  ('At what distances should reflective warning triangles be placed behind a stopped vehicle on an undivided highway?', '5, 50, and 100 feet', '10, 100, and 200 feet', '25, 150, and 300 feet', '50, 200, and 400 feet', 'B', 'General Knowledge', 'medium', 'Reflective warning triangles must be placed at 10 feet, 100 feet, and 200 feet behind the stopped vehicle on an undivided two-lane road. This gives approaching traffic adequate warning at various distances.'),
  ('What should you inspect on the coupling system for a combination vehicle?', 'Only the paint on the fifth wheel', 'Fifth wheel plate, locking jaws, kingpin, air and electrical lines, and safety chains or devices', 'Only the trailer brakes', 'Coupling inspection is not needed', 'B', 'General Knowledge', 'medium', 'The coupling system inspection for combination vehicles includes checking the fifth wheel plate for damage and grease, locking jaws for secure engagement around the kingpin, air and electrical lines for damage, and safety chains or latch devices.'),
  ('What should you check regarding cargo securement during the pre-trip inspection?', 'Cargo inspection is only done at pickup', 'Cargo is properly blocked, braced, tied, and chained, and tailgate or doors are secure', 'Only the weight of the cargo', 'Cargo inspection is only for hazmat loads', 'B', 'General Knowledge', 'medium', 'You must verify that cargo is properly blocked, braced, tied down, or chained to prevent shifting. Tailgates, doors, and tarps should be secured. Cargo must also not obstruct your view or access to emergency equipment.'),
  ('What fluid levels should be checked as part of the pre-trip inspection?', 'Only engine oil', 'Engine oil, coolant, power steering fluid, transmission fluid, and windshield washer fluid', 'Only coolant', 'Only windshield washer fluid', 'B', 'General Knowledge', 'medium', 'A complete pre-trip inspection includes checking engine oil, coolant, power steering fluid, transmission fluid, and windshield washer fluid. All fluids should be at their proper levels as indicated on dipsticks or reservoir markings.'),
  ('What is the purpose of the post-trip inspection?', 'It is only required for hazmat vehicles', 'To identify and report any vehicle defects or problems found at the end of the trip', 'To clean the vehicle', 'Post-trip inspections are not required', 'B', 'General Knowledge', 'medium', 'The post-trip inspection is required by federal regulations. Drivers must identify and report any vehicle defects or conditions that could affect safety or lead to a breakdown. This report must be in writing and reviewed by the next driver.'),
  ('Before beginning the pre-trip inspection, what written document should you review?', 'The vehicle registration only', 'The previous driver vehicle condition report', 'The vehicle warranty', 'The maintenance schedule only', 'B', 'General Knowledge', 'medium', 'You should always review the previous driver vehicle condition report (DVIR) before beginning your pre-trip inspection. This tells you about any defects reported and whether they were repaired, so you know what to pay special attention to.'),
  ('What condition of a leaf spring would require the vehicle to be placed out of service?', 'A spring with minor surface rust', 'A cracked or broken leaf spring or a missing leaf', 'A spring with normal wear', 'A leaf spring with grease on it', 'B', 'General Knowledge', 'medium', 'A cracked or broken leaf spring or a spring with any leaves missing is a serious safety defect. This weakens the suspension and can lead to loss of vehicle control or axle shift, requiring the vehicle to be placed out of service.'),
  ('What should you check on brake drums during the walk-around inspection?', 'Only the drum color', 'Cracks, dents, and signs of overheating such as discoloration', 'Only the drum size', 'Brake drums do not need inspection', 'B', 'General Knowledge', 'medium', 'Brake drums should be inspected for cracks, dents, and signs of overheating such as heat discoloration (blue or glazed appearance). Cracked or overheated drums can fail and cause a loss of braking ability.'),
  ('What should you look for when checking brake hoses and lines?', 'Only the hose color', 'Leaks, cracks, chafing, and that they are not tangled or restricted', 'Only the hose length', 'Brake hoses do not need inspection', 'B', 'General Knowledge', 'medium', 'Brake hoses and lines must be checked for leaks, cracks, chafing from rubbing against other components, and any kinks or tangles that could restrict air flow. A damaged brake hose can lead to complete brake failure on that wheel.'),
  ('During the in-cab inspection, what should you verify about the windshield?', 'Only that it is the correct size', 'No illegal stickers, no damage obstructing the view, and wipers work properly', 'Only that it is tinted', 'Windshield inspection is optional', 'B', 'General Knowledge', 'medium', 'Check the windshield for cracks, chips, or damage that could obstruct your view, ensure no illegal stickers are blocking your field of vision, and verify that windshield wipers operate properly and the washer fluid sprays correctly.'),
  ('What is the purpose of checking the fuel tank during the walk-around inspection?', 'Only to check the fuel level', 'To verify the tank is securely mounted, not leaking, and the cap is tight', 'Only to check the fuel brand', 'Fuel tanks do not need inspection', 'B', 'General Knowledge', 'medium', 'During the walk-around, verify the fuel tank is securely mounted to the frame, there are no leaks from the tank or fuel lines, and the fuel cap is on tight and secure. A fuel leak is an extreme fire hazard.');
INSERT INTO questions (question_text, option_a, option_b, option_c, option_d, correct_answer, category, difficulty, explanation) VALUES
  ('What is the function of the air compressor in an air brake system?', 'To store compressed air in the brake drums', 'To pump air into the air storage tanks', 'To release air from the braking system', 'To cool the brake linings', 'B', 'Air Brakes', 'medium', 'The air compressor pumps air into the air storage tanks, building up and maintaining the air pressure needed to operate the air brake system.'),
  ('The governor controls the air compressor by:', 'Regulating brake pedal pressure', 'Cutting in at 100 PSI and cutting out at 125 PSI', 'Cutting in at 125 PSI and cutting out at 150 PSI', 'Monitoring brake pad wear', 'B', 'Air Brakes', 'medium', 'The governor controls when the air compressor pumps air. It cuts in at around 100 PSI to start building pressure and cuts out at around 125 PSI when the tanks are sufficiently charged.'),
  ('Why should you drain air tanks regularly?', 'To prevent the compressor from overheating', 'To remove water and oil that collect and can damage the brakes', 'To reduce air pressure to safe levels', 'To test the low air pressure warning', 'B', 'Air Brakes', 'medium', 'Compressed air contains water and compressor oil. These accumulate in air tanks and can damage the braking system, cause corrosion, and reduce braking effectiveness, especially in cold weather when water can freeze.'),
  ('What does the safety valve on an air brake system do?', 'Opens at 60 PSI to warn the driver', 'Opens at 150 PSI to protect the tank from over-pressurization', 'Closes at 125 PSI to stop air flow', 'Releases air when the brake pedal is pressed', 'B', 'Air Brakes', 'medium', 'The safety valve is installed in the first tank the air compressor pumps air into. It protects the tank and the system from too much pressure by automatically opening (popping off) if pressure reaches 150 PSI.'),
  ('What is the purpose of an alcohol evaporator in an air brake system?', 'To clean the air lines', 'To help reduce the risk of ice forming in air brake valves during cold weather', 'To lubricate the compressor', 'To improve fuel efficiency', 'B', 'Air Brakes', 'medium', 'An alcohol evaporator introduces alcohol into the air system to help reduce the risk of ice forming in air brake valves and other parts during cold weather. Ice blockages can prevent brakes from working properly.'),
  ('A dual air brake system has:', 'Two complete sets of brake drums', 'Two separate air brake systems with a single set of controls', 'Two brake pedals for redundancy', 'Two air compressors', 'B', 'Air Brakes', 'medium', 'A dual air brake system has two separate air brake systems that use a single set of brake controls. The primary system typically operates the rear axle brakes, and the secondary system operates the front axle brakes, providing redundancy.'),
  ('If one system in a dual air brake system fails, what happens?', 'All braking is lost immediately', 'The other system can still provide some braking power', 'The parking brake automatically engages', 'The vehicle cannot be driven at all', 'B', 'Air Brakes', 'medium', 'If one air brake system in a dual system fails, the other system can still provide braking. However, the remaining system will not have full normal braking power, so you should get the vehicle off the road and repaired as soon as safely possible.'),
  ('When you press the brake pedal in an air brake system, you are operating the:', 'Spring brakes', 'Service brakes', 'Parking brakes', 'Emergency brakes', 'B', 'Air Brakes', 'medium', 'Pressing the brake pedal applies the service brakes, which use air pressure to push foundation brake components against the drums or rotors to slow and stop the vehicle. This is different from spring brakes, which are used for parking.'),
  ('Foundation brakes are used at each wheel. The most common type is the:', 'Wedge brake', 'Disc brake', 'S-cam drum brake', 'Hydraulic brake', 'C', 'Air Brakes', 'medium', 'The most common type of foundation brake found on heavy commercial vehicles is the S-cam drum brake. When air pressure is applied, it pushes a rod out that turns a cam shaped like the letter S, which forces the brake shoes against the drum.'),
  ('In an S-cam brake, what component forces the brake shoes apart and against the drum?', 'The slack adjuster', 'The push rod', 'The S-cam', 'The brake chamber', 'C', 'Air Brakes', 'medium', 'The S-cam is a shaft with a cam shaped like the letter S. When the push rod pushes the slack adjuster, the slack adjuster turns the S-cam, which twists and forces the brake shoes apart and presses them against the inside of the brake drum.'),
  ('How do wedge brakes differ from S-cam brakes?', 'Wedge brakes use a wedge pushed between the brake shoes instead of an S-cam', 'Wedge brakes only work on front axles', 'Wedge brakes do not use air pressure', 'Wedge brakes are only used on trailers', 'A', 'Air Brakes', 'medium', 'In wedge brakes, the brake chamber push rod pushes a wedge directly between the ends of the brake shoes, forcing them apart and against the brake drum. Unlike S-cam brakes, they do not use a slack adjuster or S-cam mechanism.'),
  ('What should the air pressure gauge reading be in a typical air brake system during normal operation?', 'Between 50 and 75 PSI', 'Between 100 and 125 PSI', 'Between 130 and 150 PSI', 'Between 60 and 80 PSI', 'B', 'Air Brakes', 'medium', 'During normal operation, the air pressure in the system should be maintained between approximately 100 and 125 PSI. The governor cuts in at about 100 PSI to build pressure and cuts out at about 125 PSI.'),
  ('The low air pressure warning signal must activate before air pressure drops below:', '80 PSI', '55 PSI', '60 PSI', '45 PSI', 'C', 'Air Brakes', 'medium', 'Federal and state regulations require that a low air pressure warning signal activates before the air pressure in the system drops below 60 PSI. This gives the driver time to stop safely before pressure drops too low for the brakes to work.'),
  ('What typically happens when the low air pressure warning activates?', 'The engine shuts off', 'A red warning light and/or buzzer comes on', 'The transmission locks', 'The parking brake releases', 'B', 'Air Brakes', 'medium', 'When air pressure drops to about 60 PSI or below, a low air pressure warning device activates. This is usually a red warning light, a buzzer (wig-wag), or both. The driver should stop immediately and safely when this warning activates.'),
  ('Spring brakes will automatically engage when air pressure drops to between:', '60 and 80 PSI', '20 and 45 PSI', '100 and 125 PSI', '5 and 10 PSI', 'B', 'Air Brakes', 'medium', 'Spring brakes are held in the released position by air pressure. When air pressure drops to between 20 and 45 PSI, the springs are strong enough to overcome the remaining air pressure and apply the brakes automatically.'),
  ('Why should you never use the brake pedal to hold your vehicle on a hill when the spring brakes are engaged?', 'It wastes fuel', 'Air pressure could leak away, releasing the service brakes and causing the vehicle to roll', 'It causes excessive tire wear', 'It damages the air compressor', 'B', 'Air Brakes', 'medium', 'If you use the brake pedal (service brakes) to hold your vehicle and the air leaks away, you will lose braking. Spring brakes, on the other hand, are applied mechanically by springs and do not depend on air pressure to remain engaged.'),
  ('The parking brake in vehicles with air brakes is applied using:', 'The brake pedal', 'A yellow diamond-shaped push-pull control knob', 'The trailer hand valve', 'A foot-operated lever', 'B', 'Air Brakes', 'medium', 'In vehicles with air brakes, the parking brake is controlled by a yellow, diamond-shaped push-pull control knob on the dashboard. Pulling the knob out applies the parking brakes (spring brakes), and pushing it in releases them.'),
  ('At what PSI does the governor typically cut in to start the air compressor?', '60 PSI', '125 PSI', '100 PSI', '150 PSI', 'C', 'Air Brakes', 'medium', 'The governor cuts in (starts the compressor pumping) at approximately 100 PSI. This means when air pressure drops to around 100 PSI during normal use, the compressor begins refilling the tanks.'),
  ('At what PSI does the governor typically cut out to stop the air compressor?', '100 PSI', '150 PSI', '60 PSI', '125 PSI', 'D', 'Air Brakes', 'medium', 'The governor cuts out (stops the compressor from pumping) at approximately 125 PSI. This prevents over-pressurization of the system during normal operation while maintaining adequate braking pressure.'),
  ('During an air leakage rate test for a single vehicle (not a combination), the air pressure drop should be less than:', '4 PSI per minute', '3 PSI per minute', '2 PSI per minute', '1 PSI per minute', 'C', 'Air Brakes', 'medium', 'For a single vehicle with a fully charged air system, the air leakage rate should be less than 2 PSI per minute with the engine off and brakes applied. A higher leak rate indicates an air leak that must be repaired.'),
  ('During an air leakage rate test for a combination vehicle, the air pressure drop should be less than:', '2 PSI per minute', '5 PSI per minute', '3 PSI per minute', '4 PSI per minute', 'C', 'Air Brakes', 'medium', 'For a combination vehicle (tractor-trailer), the air leakage rate should be less than 3 PSI per minute with the engine off and brakes applied. Combination vehicles have more connections and components, so a slightly higher rate is allowed.'),
  ('Brake lag distance at 55 mph is approximately:', '10 feet', '22 feet', '32 feet', '50 feet', 'C', 'Air Brakes', 'medium', 'At 55 mph, brake lag adds about 32 feet to your stopping distance. Brake lag is the time it takes for the air to travel through the lines and activate the brakes after you press the pedal, which is about one-half second.'),
  ('The delay between pressing the brake pedal and the brakes actually working in an air brake system is called:', 'Reaction distance', 'Brake fade', 'Brake lag', 'Perception distance', 'C', 'Air Brakes', 'medium', 'Brake lag is the time delay between when you press the brake pedal and when the brakes actually begin to work. In air brake systems, this delay occurs because air takes time to flow through the lines to the brakes, typically about one-half second.'),
  ('How long is the typical brake lag time in an air brake system?', 'About one-half second', 'About two seconds', 'About three seconds', 'About one-tenth of a second', 'A', 'Air Brakes', 'medium', 'The typical brake lag time in an air brake system is about one-half second. This is the time it takes for air to travel through the brake lines after you step on the pedal. At higher speeds, this delay adds significant stopping distance.'),
  ('The total stopping distance for a vehicle with air brakes is made up of:', 'Perception distance + reaction distance + brake lag distance + braking distance', 'Reaction distance + braking distance only', 'Perception distance + braking distance only', 'Brake lag distance + braking distance only', 'A', 'Air Brakes', 'medium', 'Total stopping distance for air brake vehicles includes four components: perception distance (time to see the hazard), reaction distance (time to move your foot to the brake), brake lag distance (time for air to reach the brakes), and braking distance (time for the vehicle to stop once brakes are working).'),
  ('Compared to hydraulic brakes, air brakes require more stopping distance because of:', 'Heavier vehicle weight only', 'Brake lag distance added by the air system', 'Smaller brake drums', 'Lower friction brake materials', 'B', 'Air Brakes', 'medium', 'Air brakes add brake lag distance that hydraulic brakes do not have. It takes time for air to flow through the lines to the brake chambers, adding about one-half second of delay. Hydraulic systems respond almost instantly because fluid does not compress.'),
  ('What is brake fade?', 'Brakes wearing out over time', 'A loss of braking power caused by excessive heat from overuse', 'Air leaking from the brake lines', 'Brake shoes becoming misaligned', 'B', 'Air Brakes', 'medium', 'Brake fade is the loss of braking effectiveness that occurs when brakes overheat from excessive or prolonged use. Heat builds up faster than it can be dissipated, reducing friction between brake linings and drums, making the brakes less effective.'),
  ('When going down a long steep hill, what is the proper braking technique?', 'Apply brakes continuously all the way down', 'Use snub braking by applying brakes to slow 5 mph below your safe speed then release', 'Shift to neutral and coast to save brakes', 'Only use the parking brake', 'B', 'Air Brakes', 'medium', 'The correct technique on long downgrades is snub braking. Apply the brakes firmly enough to reduce your speed to about 5 mph below your safe speed for that grade, then release the brakes. Repeat this process. This helps prevent brake fade from overheating.'),
  ('Why is riding the brakes on a long downgrade dangerous?', 'It can cause the engine to overheat', 'It causes excessive heat buildup leading to brake fade and possible brake failure', 'It damages the transmission', 'It uses too much fuel', 'B', 'Air Brakes', 'medium', 'Riding the brakes (keeping them applied continuously) on a long downgrade causes excessive heat buildup in the brake drums and linings. This leads to brake fade, where the brakes become less effective, and can ultimately result in complete brake failure.'),
  ('What should you do if your brakes fail on a downgrade?', 'Shift to neutral', 'Look for an escape ramp or other way to safely get off the road', 'Turn off the engine', 'Open the door to increase drag', 'B', 'Air Brakes', 'medium', 'If your brakes fail on a downgrade, look for an escape ramp, an open field, or any other safe way to stop. Escape ramps use a long bed of loose material to slow and stop a vehicle. Downshift to use engine braking and do not shift to neutral.'),
  ('In emergency braking with air brakes (no ABS), the best method is to:', 'Brake as hard as possible and hold the pedal down', 'Apply brakes firmly without locking the wheels and steer to safety', 'Pump the brakes rapidly', 'Apply the parking brake immediately', 'B', 'Air Brakes', 'medium', 'During emergency braking without ABS, you should apply the brakes firmly while avoiding wheel lockup. Locked wheels cause skidding and loss of steering control. Controlled braking (braking as hard as you can without locking wheels) is the most effective method.'),
  ('What does ABS (Anti-Lock Braking System) do on air brake equipped vehicles?', 'Automatically stops the vehicle faster', 'Prevents wheel lockup so you maintain steering control during hard braking', 'Eliminates the need for brake maintenance', 'Increases air pressure in the tanks', 'B', 'Air Brakes', 'medium', 'ABS uses sensors on the wheels to detect lockup and automatically reduces and reapplies brake pressure to prevent wheels from locking. This helps the driver maintain steering control during hard braking. ABS does not necessarily shorten stopping distance.'),
  ('Does ABS shorten your stopping distance?', 'Yes, it always shortens stopping distance significantly', 'No, ABS does not necessarily shorten stopping distance', 'Yes, by at least 50 percent', 'Only on wet roads', 'B', 'Air Brakes', 'medium', 'ABS does not necessarily shorten stopping distance. Its primary purpose is to prevent wheel lockup so the driver can maintain steering control during hard braking. On some surfaces, stopping distance may be similar or even slightly longer, but vehicle control is maintained.'),
  ('How should you brake when your vehicle has ABS?', 'Pump the brake pedal rapidly', 'Brake normally and do not let up on the pedal when you feel it pulsing', 'Apply brakes lightly only', 'Use the parking brake instead', 'B', 'Air Brakes', 'medium', 'When braking with ABS, you should brake normally. If you need to stop quickly, press the brake pedal firmly and do not let up, even if you feel the pedal pulsing or vibrating. The pulsing is the ABS working. Do not pump ABS brakes.'),
  ('How can you tell if your vehicle is equipped with ABS?', 'The vehicle will have a yellow ABS malfunction lamp on the instrument panel', 'There will be a special ABS sticker on the steering wheel', 'The brake pedal will be a different color', 'There is no way to tell from the cab', 'A', 'Air Brakes', 'medium', 'Vehicles equipped with ABS have a yellow ABS malfunction lamp on the instrument panel. This lamp comes on at start-up for a bulb check and then turns off. If it stays on, it indicates an ABS malfunction, though normal brakes will still work.'),
  ('How long should it take for air pressure to build from 50 to 90 PSI with the engine at operating RPM?', 'Within 5 minutes', 'Within 10 minutes', 'Within 3 minutes', 'Within 1 minute', 'C', 'Air Brakes', 'medium', 'The air compressor should build air pressure from 50 to 90 PSI within 3 minutes with the engine at operating RPM. If it takes longer, the air compressor or the system may have a problem that needs to be repaired before driving.'),
  ('If the air compressor takes longer than 3 minutes to build pressure from 50 to 90 PSI, this indicates:', 'Normal operation in cold weather', 'A possible problem with the compressor or system that needs repair', 'The governor needs adjustment', 'The safety valve is working correctly', 'B', 'Air Brakes', 'medium', 'If the air compressor cannot build pressure from 50 to 90 PSI within 3 minutes with the engine running at operating RPM, there is likely a problem. Possible causes include a worn compressor, air leaks, or a defective governor.'),
  ('The safety valve in the air brake system opens automatically at:', '100 PSI', '125 PSI', '60 PSI', '150 PSI', 'D', 'Air Brakes', 'medium', 'The safety valve is designed to protect the air system from overpressurization. It opens automatically at 150 PSI to release excess air pressure. If the safety valve must open, something is wrong with the system, likely a malfunctioning governor.'),
  ('If the safety valve has to release air, what is the likely problem?', 'The drain valves are stuck open', 'The governor or compressor unloading mechanism is malfunctioning', 'The brake pedal is stuck', 'The slack adjusters are too tight', 'B', 'Air Brakes', 'medium', 'If the safety valve releases air, it means pressure has exceeded 150 PSI. This likely indicates a malfunctioning governor that is not cutting out the compressor at 125 PSI, or the compressor unloading mechanism has failed.'),
  ('What is the purpose of front brake limiting valves found on some older vehicles?', 'To increase front brake pressure on slippery roads', 'To reduce front brake pressure to prevent front wheel skids on slippery surfaces', 'To lock the front brakes during emergency stops', 'To balance air between the primary and secondary systems', 'B', 'Air Brakes', 'medium', 'Front brake limiting valves were used on older vehicles to reduce air pressure to the front brakes, typically to about 50 percent of normal, on slippery surfaces. This was to help prevent front wheel lockup and loss of steering control.'),
  ('Should you use the front brake limiting valve in the normal or slippery position during normal driving?', 'Always in the slippery position', 'Always in the normal position to have full front braking power', 'It does not matter', 'Only use it when going uphill', 'B', 'Air Brakes', 'medium', 'The front brake limiting valve should be kept in the normal position during everyday driving to take full advantage of front brake stopping power. Reducing front brake pressure unnecessarily increases stopping distance. Many experts advise removing these valves.'),
  ('What are glad hands?', 'The rubber seals on brake chambers', 'Coupling devices that connect air lines between the tractor and trailer', 'Handles on the brake drums for inspection', 'The release valves on air tanks', 'B', 'Air Brakes', 'medium', 'Glad hands are the coupling devices used to connect the air lines between the tractor and trailer in a combination vehicle. They snap together and have rubber seals (grommets) to prevent air leaks at the connection point.'),
  ('What can happen if glad hand connections are not properly sealed?', 'The engine will not start', 'Air leaks that can reduce braking performance or cause brake failure', 'The trailer lights will not work', 'The fifth wheel will not lock', 'B', 'Air Brakes', 'medium', 'Improperly sealed glad hand connections cause air leaks in the brake system. This can lead to reduced air pressure, poor braking performance, and potentially brake failure. Always check that glad hand seals are in good condition and connections are secure.'),
  ('When coupling glad hands, what should you check for?', 'That the rubber seals are in good condition and free of damage', 'That the glad hands are painted the same color', 'That the air lines are the same length', 'That the trailer wheels are chocked on both sides', 'A', 'Air Brakes', 'medium', 'When coupling glad hands, you should inspect the rubber grommets (seals) to make sure they are in good condition and free of cracks, damage, or debris. Damaged seals will cause air leaks that reduce braking ability.'),
  ('What do air brake gauges tell you?', 'The temperature of the brake drums', 'How much air pressure is in the air tanks', 'The thickness of the brake pads', 'How fast the vehicle is going', 'B', 'Air Brakes', 'medium', 'Air brake gauges on the dashboard indicate the amount of air pressure in the air tanks, measured in PSI. In dual air brake systems, there are gauges for each system (primary and secondary). Monitoring these gauges is critical for safe operation.'),
  ('What should you do if the low air pressure warning comes on while driving?', 'Continue driving to the next rest stop', 'Speed up to build air pressure faster', 'Stop and safely park as soon as possible', 'Turn off the warning light and continue', 'C', 'Air Brakes', 'medium', 'If the low air pressure warning activates while driving, you should stop and safely park as soon as possible. Continuing to drive risks a further drop in pressure, which will cause the spring brakes to lock up suddenly, possibly causing a loss of control.'),
  ('What is the slack adjuster used for in an S-cam brake?', 'To adjust the distance between the brake shoes and the drum', 'To connect the air line to the brake chamber', 'To measure air pressure at the wheel', 'To lubricate the brake drum', 'A', 'Air Brakes', 'medium', 'The slack adjuster connects the push rod to the S-cam and is used to adjust the clearance between the brake shoes and the brake drum. Proper adjustment is critical because too much slack means the brakes will not apply fully.'),
  ('What happens to braking ability if the slack adjusters are out of adjustment?', 'Braking will be smoother', 'The brakes may not work properly or could fail because the push rod travels too far', 'The air compressor will build pressure faster', 'Nothing, as the ABS compensates automatically', 'B', 'Air Brakes', 'medium', 'If the slack adjusters are out of adjustment, the push rod has to travel too far to move the brake shoes against the drum. This reduces braking power and can lead to brake failure. Out-of-adjustment brakes are a leading cause of truck accidents.'),
  ('How should you test that the low air pressure warning works during a pre-trip inspection?', 'By turning on the ignition and checking if the light comes on briefly', 'By pumping the brake pedal with the engine off to reduce air pressure and verify the warning activates before 60 PSI', 'By disconnecting an air line', 'By pressing the horn button', 'B', 'Air Brakes', 'medium', 'To test the low air pressure warning, turn the engine off with a fully charged system, then repeatedly press and release the brake pedal to reduce air pressure. The low air pressure warning light and/or buzzer should activate before the pressure drops below 60 PSI.'),
  ('Automatic drain valves on air tanks:', 'Must be manually operated every day', 'Automatically expel water and oil that accumulate in the tanks', 'Regulate the air pressure in the system', 'Are only found on trailer air tanks', 'B', 'Air Brakes', 'medium', 'Automatic drain valves are installed on air tanks to automatically expel accumulated water, oil, and other contaminants. Even with automatic valves, it is good practice to manually drain the tanks periodically to ensure they are working properly.');
INSERT INTO questions (question_text, option_a, option_b, option_c, option_d, correct_answer, category, difficulty, explanation) VALUES
  ('What endorsement is a prerequisite for obtaining a School Bus (S) endorsement?', 'Air Brakes endorsement', 'Passenger (P) endorsement', 'Hazardous Materials (H) endorsement', 'Tanker (N) endorsement', 'B', 'Bus', 'medium', 'The S endorsement requires the Passenger (P) endorsement as a prerequisite. You must first hold a valid P endorsement before you can obtain the School Bus endorsement.'),
  ('How far does the danger zone extend around a school bus?', '5 feet on each side', '10 feet on each side', '15 feet on each side', '20 feet on each side', 'B', 'Bus', 'medium', 'The danger zone extends 10 feet around the bus on each side, including the front and rear. This is the area where students are most at risk of being struck or injured.'),
  ('When should students approach the school bus at a stop?', 'As soon as the bus is visible', 'When the amber lights begin flashing', 'When the bus has stopped, red lights are flashing, and the door is open', 'When the driver honks the horn', 'C', 'Bus', 'medium', 'Students should never approach the bus until it has completely stopped, the red warning lights are flashing, and the door is open. This ensures the bus is fully secured before students enter the danger zone.'),
  ('At a railroad crossing, how far from the nearest rail should a school bus stop?', '5 to 10 feet', '10 to 15 feet', '15 to 50 feet', '50 to 100 feet', 'C', 'Bus', 'medium', 'A school bus must stop between 15 and 50 feet from the nearest rail at a railroad crossing. This distance provides a safe buffer while keeping the driver close enough to see and hear approaching trains.'),
  ('What should a school bus driver do after stopping at a railroad crossing?', 'Proceed immediately if no train is visible', 'Silence passengers, open the door and/or window, and look and listen both ways', 'Honk the horn three times and proceed', 'Call dispatch for permission to cross', 'B', 'Bus', 'medium', 'After stopping at a railroad crossing, the driver must silence all passengers, open the door and/or window, and look and listen carefully in both directions for approaching trains before proceeding.'),
  ('What must a driver check under the bus before departing?', 'Oil level', 'For students or objects that may be hidden beneath the bus', 'Tire tread depth only', 'Exhaust system temperature', 'B', 'Bus', 'medium', 'Before departing, the driver must check under the bus for students or objects that may be hidden beneath it. Children in the danger zone may not be visible from the driver seat and could be struck if the bus moves.'),
  ('What should a driver look for during a post-trip inspection of a school bus?', 'Only mechanical defects', 'Sleeping students and lost items', 'Fuel level only', 'Tire pressure only', 'B', 'Bus', 'medium', 'A post-trip inspection must include checking for sleeping students and lost items. A child left on the bus could be in serious danger, making this inspection critical after every route.'),
  ('In rural areas, how far before a stop should the amber warning lights be activated?', '50 feet', '100 feet', '200 feet', '300 feet', 'C', 'Bus', 'medium', 'In rural areas, amber warning lights should be activated approximately 200 feet before the stop. This gives approaching traffic more time to react and slow down due to higher speeds on rural roads.'),
  ('In urban areas, how far before a stop should the amber warning lights be activated?', '50 feet', '100 feet', '200 feet', '300 feet', 'B', 'Bus', 'medium', 'In urban areas, amber warning lights should be activated approximately 100 feet before the stop. Urban areas have lower speeds, so less advance warning distance is needed compared to rural areas.'),
  ('What is the purpose of the crossing control arm on a school bus?', 'To block traffic from passing the bus', 'To keep students away from the front of the bus as they exit', 'To signal other drivers to stop', 'To help students climb onto the bus', 'B', 'Bus', 'medium', 'The crossing control arm, or crossing gate, extends outward from the front of the bus when the door opens. It forces students to walk far enough away from the front of the bus to be visible to the driver.'),
  ('Why should backing a school bus be avoided whenever possible?', 'It uses more fuel', 'It damages the transmission', 'The area behind the bus is a danger zone with limited visibility', 'It is illegal in all states', 'C', 'Bus', 'medium', 'Backing a school bus should be avoided because the area behind the bus is a danger zone with limited visibility. Children may be in the blind spot behind the bus where the driver cannot see them.'),
  ('If you must back a school bus, what should you do?', 'Back up quickly to minimize time in reverse', 'Use a reliable spotter outside the bus', 'Only use your mirrors', 'Honk the horn continuously while backing', 'B', 'Bus', 'medium', 'If backing is absolutely necessary, you should use a reliable spotter positioned outside the bus who can see the area behind the vehicle and communicate with you throughout the backing maneuver.'),
  ('Is it permissible to refuel a school bus while students are on board?', 'Yes, if the engine is off', 'Yes, if the windows are open', 'No, never refuel with students aboard', 'Yes, during short stops only', 'C', 'Bus', 'medium', 'You must never refuel a school bus with students on board. Fuel vapors are dangerous and any spill or ignition could put students at serious risk. Students must be unloaded before refueling.'),
  ('What type of mirror allows a school bus driver to see the danger zone directly in front of the bus?', 'Flat mirrors', 'Convex mirrors', 'Crossover mirrors', 'Rearview mirror', 'C', 'Bus', 'medium', 'Crossover mirrors are mounted on both sides at the front of the bus and allow the driver to see the danger zone area directly in front of the bus and the area to the left and right of the front bumper.'),
  ('What is the purpose of flat mirrors on a school bus?', 'To see the front danger zone', 'To see the sides of the bus and down the road behind', 'To see underneath the bus', 'To see the interior of the bus', 'B', 'Bus', 'medium', 'Flat mirrors, also called plane mirrors, are positioned on both sides of the bus and allow the driver to see along the sides of the bus, the rear tires, and traffic approaching from behind.'),
  ('What advantage do convex mirrors provide on a school bus?', 'They eliminate all blind spots', 'They provide a wider field of view than flat mirrors', 'They provide magnified images', 'They work better at night', 'B', 'Bus', 'medium', 'Convex mirrors provide a wider field of view than flat mirrors, allowing the driver to see a broader area along the sides of the bus. However, objects appear smaller and farther away in convex mirrors.'),
  ('Why is it important to count students at each stop during loading?', 'To verify bus capacity is not exceeded', 'To ensure all students who should board have boarded and are accounted for', 'To report attendance to the school', 'To calculate fuel consumption', 'B', 'Bus', 'medium', 'Counting students at each stop ensures that all expected students have boarded the bus. If a student is missing, they may be in the danger zone around the bus or under the bus, which requires immediate investigation.'),
  ('What should a driver do if a student drops an object near or under the bus?', 'Tell the student to quickly pick it up', 'Have the student tell the driver so the driver can retrieve it or ensure the student is visible before picking it up', 'Ignore it and proceed', 'Have another student retrieve it', 'B', 'Bus', 'medium', 'Students should be instructed to tell the driver if they drop something near or under the bus. The driver must be able to see the student at all times. A student bending down near the bus may not be visible to the driver.'),
  ('When unloading students, what should the driver do after students exit the bus?', 'Immediately close the door and leave', 'Check all mirrors to confirm students have moved away from the danger zone before moving the bus', 'Wait exactly 30 seconds then drive away', 'Honk the horn to signal departure', 'B', 'Bus', 'medium', 'After students exit, the driver must check all mirrors to confirm that all students have moved away from the danger zone and are in a safe location before closing the door and moving the bus.'),
  ('What are the amber warning lights on a school bus used for?', 'To indicate the bus is about to stop to load or unload students', 'To indicate the bus is broken down', 'To indicate the bus is turning', 'To indicate the bus is backing up', 'A', 'Bus', 'medium', 'Amber warning lights alert other drivers that the school bus is preparing to stop to load or unload students. They are activated before the bus comes to a complete stop to give traffic time to slow down.'),
  ('What do the red flashing lights on a school bus indicate?', 'The bus is about to turn', 'The bus is broken down', 'The bus has stopped and students are loading or unloading — traffic must stop', 'The bus is backing up', 'C', 'Bus', 'medium', 'Red flashing lights indicate that the bus has stopped and students are actively loading or unloading. In most jurisdictions, traffic in both directions must stop when the red lights are flashing.'),
  ('What is the purpose of the stop arm on a school bus?', 'To help students cross the street', 'To extend outward and signal traffic to stop when the bus is loading or unloading', 'To block the bus door', 'To act as an emergency brake', 'B', 'Bus', 'medium', 'The stop arm swings out from the left side of the bus when the door is opened. It provides an additional visual signal to traffic that they must stop because students are loading or unloading.'),
  ('When should emergency evacuation of a school bus be performed?', 'Whenever a student requests it', 'When there is a fire, the bus is in an unsafe position, or there is an imminent danger', 'At every stop', 'Only during drills', 'B', 'Bus', 'medium', 'Emergency evacuation should be performed when there is a fire or danger of fire, the bus is in an unsafe position such as risk of tipping, or there is an imminent hazard that makes staying on the bus more dangerous than evacuating.'),
  ('How should a driver demonstrate emergency exit operation to students?', 'Verbally describe it only', 'Show students how to open emergency exits and have them practice under supervision', 'Send home a written notice', 'Only demonstrate at the beginning of the school year', 'B', 'Bus', 'medium', 'Drivers should physically demonstrate how each emergency exit operates and allow students to practice under supervision. Students should know how to open rear emergency doors, roof hatches, and emergency windows.'),
  ('What is the strobe light on a school bus used for?', 'To signal turns', 'To improve visibility of the bus during adverse weather or low-visibility conditions', 'To communicate with dispatch', 'To entertain students', 'B', 'Bus', 'medium', 'The roof-mounted strobe light improves the visibility of the school bus during adverse weather conditions such as fog, rain, or snow, making it easier for other drivers to see the bus from a distance.'),
  ('What is the most dangerous area around a school bus for students?', 'Inside the bus', 'The area directly behind the exhaust', 'The danger zone, especially directly in front of and behind the bus', 'The area 50 feet away from the bus', 'C', 'Bus', 'medium', 'The most dangerous areas are within the danger zone, especially directly in front of and behind the bus where the driver has the least visibility. Students in these areas are at the greatest risk of being struck.'),
  ('How should students cross the street after exiting a school bus?', 'Walk behind the bus', 'Walk at least 10 feet in front of the bus where the driver can see them', 'Run across quickly', 'Cross without looking', 'B', 'Bus', 'medium', 'Students should walk at least 10 feet in front of the bus, staying outside the danger zone, and look at the driver for a signal before crossing. The driver must be able to see the student at all times.'),
  ('What is a critical part of a pre-trip inspection specific to school buses?', 'Checking the sound system', 'Inspecting emergency exits, mirrors, warning lights, stop arm, and crossing control arm', 'Counting the seats', 'Checking the paint condition', 'B', 'Bus', 'medium', 'A school bus pre-trip inspection must include checking that all emergency exits operate properly, mirrors are clean and adjusted, warning lights and stop arm function, and the crossing control arm works correctly.'),
  ('How should mirrors be adjusted on a school bus?', 'So the driver can see the interior of the bus only', 'So the driver can see the danger zones on all sides of the bus', 'So the driver can see traffic behind only', 'Mirrors do not need adjustment', 'B', 'Bus', 'medium', 'Mirrors must be adjusted so the driver can see the danger zones on all sides of the bus, including the front, rear, and both sides. Proper mirror adjustment is critical for monitoring student safety around the bus.'),
  ('What should a school bus driver do about student behavior problems on the bus?', 'Physically restrain the student', 'Pull over immediately and discipline the student', 'Address it with verbal intervention when safe, and report serious issues following district policy', 'Ignore all behavior issues', 'C', 'Bus', 'medium', 'The driver should address behavior issues with calm verbal intervention when it is safe to do so and report serious or persistent problems following the school district policy. The driver should never physically discipline a student or allow behavior to become a safety distraction while driving.'),
  ('Is cell phone use by a school bus driver permitted while driving?', 'Yes, for personal calls', 'Yes, for navigation only', 'No, cell phone use while driving is prohibited', 'Yes, with a hands-free device', 'C', 'Bus', 'medium', 'Cell phone use by a school bus driver while driving is prohibited. Using a phone is a dangerous distraction that takes attention away from the road and monitoring students, creating a serious safety hazard.'),
  ('What should a school bus driver do when approaching a stop in a rural area?', 'Activate the amber warning lights about 200 feet before the stop', 'Stop immediately without warning', 'Flash the headlights', 'Sound the horn three times', 'A', 'Bus', 'medium', 'In rural areas, the driver should activate amber warning lights approximately 200 feet before the bus stop. This gives motorists adequate time to slow down and prepare to stop, especially where speeds are typically higher.'),
  ('What does ABS do on a school bus?', 'It makes the bus stop faster', 'It prevents wheel lockup during hard braking, helping the driver maintain steering control', 'It eliminates the need for air brakes', 'It automatically stops the bus at railroad crossings', 'B', 'Bus', 'medium', 'ABS (Anti-lock Braking System) prevents wheel lockup during hard braking, which helps the driver maintain steering control. ABS does not necessarily shorten stopping distance, but it helps prevent skidding.'),
  ('If a school bus has ABS, how should the driver brake in an emergency?', 'Pump the brakes rapidly', 'Apply steady firm pressure to the brake pedal', 'Lightly tap the brakes', 'Only use the parking brake', 'B', 'Bus', 'medium', 'With ABS, the driver should apply firm, steady pressure to the brake pedal and let the ABS system do its job. Pumping the brakes can interfere with ABS operation and reduce its effectiveness.'),
  ('When dropping off students in traffic, what is most important?', 'Dropping them off quickly to avoid traffic delays', 'Ensuring students exit on the side away from traffic and are in a safe location before the bus moves', 'Letting students choose which side to exit', 'Dropping them off only at signalized intersections', 'B', 'Bus', 'medium', 'The driver must ensure students exit on the side away from traffic and reach a safe location before the bus moves. The driver should monitor all mirrors and confirm students are clear of the danger zone.'),
  ('What should a school bus driver do when driving in adverse weather such as fog or heavy rain?', 'Maintain normal speed', 'Slow down, increase following distance, and use headlights and the strobe light for visibility', 'Pull over and wait for conditions to clear', 'Turn off all lights to reduce glare', 'B', 'Bus', 'medium', 'In adverse weather, drivers should reduce speed, increase following distance, and use headlights and the roof-mounted strobe light to improve visibility. Extra caution is needed at stops where students may be harder to see.'),
  ('What should a driver do if they suspect a student is hiding under the bus?', 'Move the bus slowly and check mirrors', 'Do not move the bus, exit, and physically check underneath the bus', 'Honk the horn and proceed', 'Ask other students to look', 'B', 'Bus', 'medium', 'The driver must never move the bus if there is any suspicion that a student is underneath it. The driver should exit the bus and physically check under the vehicle before departing.'),
  ('How should special needs students be transported on a school bus?', 'The same as all other students with no accommodations', 'According to their Individual Education Program (IEP) with proper equipment and securement', 'Only in separate vehicles', 'Without seat belts or restraints', 'B', 'Bus', 'medium', 'Special needs students must be transported according to their Individual Education Program (IEP), which may require special equipment such as wheelchair lifts, securement systems, and child safety restraint systems.'),
  ('When securing a wheelchair on a school bus, what must be done?', 'Only the wheelchair brakes need to be set', 'The wheelchair must be secured with proper tie-downs and the student must wear a seat belt or restraint', 'The student can hold onto a handrail', 'No securement is needed for short trips', 'B', 'Bus', 'medium', 'Wheelchairs must be properly secured using approved tie-down systems, and the student must also be secured with a seat belt or appropriate restraint system. This prevents movement during sudden stops or accidents.'),
  ('What should a driver do if the bus stalls on a railroad crossing?', 'Try to restart the engine repeatedly', 'Evacuate the bus immediately and move everyone away from the tracks at a 45-degree angle toward the train', 'Wait for help', 'Call the railroad company first', 'B', 'Bus', 'medium', 'If the bus stalls on railroad tracks, the driver must evacuate all students immediately and move them away from the tracks at a 45-degree angle in the direction the train is coming from, so debris will not strike them if a train hits the bus.'),
  ('Why should students walk at least 10 feet away from the side of the bus?', 'To avoid splashing from puddles', 'To stay outside the danger zone where the driver can see them', 'To avoid exhaust fumes', 'To give other cars room to pass', 'B', 'Bus', 'medium', 'Walking at least 10 feet away from the side of the bus keeps students outside the danger zone. Within this zone, the driver may not be able to see them, increasing the risk of being struck by the bus.'),
  ('When should the red flashing lights and stop arm be activated?', '200 feet before the stop', 'When the bus is completely stopped and ready to load or unload students', 'Only in school zones', 'Only when children are under age 10', 'B', 'Bus', 'medium', 'The red flashing lights and stop arm are activated when the bus is completely stopped and the driver is ready to load or unload students. This signals traffic to stop and alerts everyone that students may be entering the roadway.'),
  ('What should a school bus driver do before opening the door at a student stop?', 'Open the door immediately upon stopping', 'Check all mirrors, ensure traffic has stopped, activate red lights and stop arm, then open the door', 'Honk the horn twice', 'Flash the headlights', 'B', 'Bus', 'medium', 'Before opening the door, the driver must check all mirrors to ensure the area around the bus is safe, verify that traffic has stopped, and activate the red flashing lights and stop arm before opening the door for students.'),
  ('What is the proper procedure for loading students in the morning?', 'Let students run to the bus as it approaches', 'Arrive at the stop, secure the bus, activate warning lights, open the door, and have students board in an orderly single-file line', 'Have students board from both doors', 'Stop in the middle of the road for faster loading', 'B', 'Bus', 'medium', 'The driver should arrive at the stop, bring the bus to a complete stop, activate all warning systems, and then open the door. Students should approach only after the door is open and board in a single-file line in an orderly manner.'),
  ('What endorsement(s) must a school bus driver hold?', 'Only the S endorsement', 'Both the P (Passenger) and S (School Bus) endorsements', 'Only the P endorsement', 'The H (Hazmat) and S endorsements', 'B', 'Bus', 'medium', 'A school bus driver must hold both the Passenger (P) endorsement and the School Bus (S) endorsement. The P endorsement is a prerequisite for the S endorsement, so both are required to legally operate a school bus.'),
  ('During an emergency evacuation, where should students assemble after exiting the bus?', 'Directly behind the bus', 'At least 100 feet from the bus in a safe location away from traffic', 'On the opposite side of the road', 'They should disperse in all directions', 'B', 'Bus', 'medium', 'After evacuating, students should assemble at least 100 feet away from the bus in a supervised, safe location away from traffic and any hazards. The driver must account for all students at the assembly point.'),
  ('How often should emergency evacuation drills be conducted on school buses?', 'Once every five years', 'At least twice per school year as required by most regulations', 'Only when a new driver is hired', 'Never, they are not required', 'B', 'Bus', 'medium', 'Most regulations require emergency evacuation drills to be conducted at least twice per school year. These drills ensure that students know how to exit the bus quickly and safely in an actual emergency.'),
  ('What should a school bus driver do if the red warning light system malfunctions?', 'Continue the route without the lights', 'Use hand signals instead', 'Report the malfunction and do not operate the bus until the system is repaired', 'Only drive during daylight hours', 'C', 'Bus', 'medium', 'If the red warning light system malfunctions, the driver should report the issue immediately. The bus should not be operated to load or unload students until the warning light system is fully repaired, as it is critical to student safety.'),
  ('What should a driver check regarding tail lights during a pre-trip inspection?', 'Only that they are the correct color', 'That tail lights, brake lights, and turn signals are all functioning properly and are clean', 'Only brake lights', 'Tail lights do not require inspection', 'B', 'Bus', 'medium', 'During a pre-trip inspection, the driver must verify that all tail lights, brake lights, and turn signals are functioning properly, are clean, and are the correct color. Malfunctioning lights can prevent other drivers from recognizing the bus is stopping.'),
  ('What must a school bus driver do when approaching a drawbridge?', 'Speed up to cross quickly', 'Stop the bus, open the window or door, and verify it is safe before crossing', 'Honk the horn and proceed', 'Slow down but do not stop', 'B', 'Bus', 'medium', 'At a drawbridge, a school bus driver must stop the bus completely, open the door or window to look and listen, and verify that the draw is completely closed and all signals indicate it is safe to proceed before crossing.');
INSERT INTO questions (question_text, option_a, option_b, option_c, option_d, correct_answer, category, difficulty, explanation) VALUES
  ('What hazardous materials class covers explosives?', 'Class 3', 'Class 1', 'Class 5', 'Class 8', 'B', 'Hazmat', 'medium', 'Class 1 covers explosives. This includes divisions 1.1 through 1.6, ranging from mass explosion hazards to extremely insensitive detonating substances.'),
  ('What hazardous materials class covers flammable liquids?', 'Class 1', 'Class 2', 'Class 3', 'Class 4', 'C', 'Hazmat', 'medium', 'Class 3 covers flammable liquids. These are liquids with a flash point below 141 degrees Fahrenheit, such as gasoline, acetone, and alcohol.'),
  ('What hazardous materials class covers gases?', 'Class 2', 'Class 5', 'Class 7', 'Class 9', 'A', 'Hazmat', 'medium', 'Class 2 covers gases, including flammable gases (Division 2.1), non-flammable compressed gases (Division 2.2), and poisonous gases (Division 2.3).'),
  ('What hazardous materials class covers radioactive materials?', 'Class 5', 'Class 6', 'Class 7', 'Class 9', 'C', 'Hazmat', 'medium', 'Class 7 covers radioactive materials. These are materials that emit ionizing radiation and require special handling, placarding, and Transport Index tracking.'),
  ('What hazardous materials class covers corrosive materials?', 'Class 4', 'Class 6', 'Class 8', 'Class 9', 'C', 'Hazmat', 'medium', 'Class 8 covers corrosive materials. These are substances that cause visible destruction or irreversible damage to human skin tissue or corrode steel or aluminum.'),
  ('What hazardous materials class covers poisons and toxic substances?', 'Class 4', 'Class 5', 'Class 6', 'Class 8', 'C', 'Hazmat', 'medium', 'Class 6 covers poisons and toxic substances. Division 6.1 covers poisonous materials and Division 6.2 covers infectious substances.'),
  ('What hazardous materials class covers flammable solids?', 'Class 2', 'Class 3', 'Class 4', 'Class 5', 'C', 'Hazmat', 'medium', 'Class 4 covers flammable solids. This includes flammable solids (Division 4.1), spontaneously combustible materials (Division 4.2), and dangerous when wet materials (Division 4.3).'),
  ('What hazardous materials class covers oxidizers and organic peroxides?', 'Class 3', 'Class 4', 'Class 5', 'Class 8', 'C', 'Hazmat', 'medium', 'Class 5 covers oxidizers (Division 5.1) and organic peroxides (Division 5.2). Oxidizers can cause or enhance the combustion of other materials by yielding oxygen.'),
  ('What hazardous materials class covers miscellaneous dangerous goods?', 'Class 1', 'Class 6', 'Class 8', 'Class 9', 'D', 'Hazmat', 'medium', 'Class 9 covers miscellaneous dangerous goods. These are hazardous materials that do not meet the definition of any other hazard class, such as environmentally hazardous substances and elevated temperature materials.'),
  ('Where must hazmat placards be displayed on a vehicle?', 'On the front and back only', 'On both sides and both ends of the vehicle', 'Only on the back of the vehicle', 'Only on the driver side', 'B', 'Hazmat', 'medium', 'Placards must be displayed on both sides and both ends of the vehicle, for a total of four placards. This ensures the hazardous material can be identified from any direction.'),
  ('How far must placards be placed from any other markings on the vehicle?', 'At least 1 inch', 'At least 2 inches', 'At least 3 inches', 'At least 6 inches', 'C', 'Hazmat', 'medium', 'Placards must be placed at least 3 inches away from any other markings on the vehicle. This ensures the placard is clearly visible and not confused with other labels or markings.'),
  ('When parking a vehicle loaded with Division 1.1, 1.2, or 1.3 explosives, how far must you be from bridges, tunnels, or buildings?', '100 feet', '200 feet', '300 feet', '500 feet', 'C', 'Hazmat', 'medium', 'When parking a vehicle loaded with Division 1.1, 1.2, or 1.3 explosives, you must be at least 300 feet from any bridge, tunnel, or building. This is to minimize damage in the event of an explosion.'),
  ('When parking a vehicle loaded with Division 1.1, 1.2, or 1.3 explosives, how far must you be from the traveled portion of the road?', '3 feet', '5 feet', '10 feet', '15 feet', 'B', 'Hazmat', 'medium', 'When parking a vehicle loaded with Division 1.1, 1.2, or 1.3 explosives, you must park at least 5 feet from the traveled portion of the road. This helps keep the vehicle away from passing traffic.'),
  ('When an attendant is required to watch a hazmat vehicle, how close must the attendant be to the vehicle?', 'Within 25 feet', 'Within 50 feet', 'Within 100 feet', 'Within 200 feet', 'C', 'Hazmat', 'medium', 'The attendant must be within 100 feet of the vehicle and must have it in clear view at all times. The attendant must know the hazards and emergency procedures for the materials being transported.'),
  ('What is the maximum total Transport Index allowed on a single vehicle carrying radioactive materials?', '25', '50', '75', '100', 'B', 'Hazmat', 'medium', 'The total Transport Index of all radioactive packages on a single vehicle must not exceed 50. The Transport Index is a number on radioactive labels that indicates the level of radiation exposure.'),
  ('Where are the Hazardous Materials Regulations (HMR) found?', 'Title 49 CFR Parts 100-110', 'Title 49 CFR Parts 171-180', 'Title 49 CFR Parts 200-250', 'Title 40 CFR Parts 171-180', 'B', 'Hazmat', 'medium', 'The Hazardous Materials Regulations are found in Title 49 of the Code of Federal Regulations (CFR), Parts 171 through 180. These regulations govern the transportation of hazardous materials.'),
  ('What special endorsement is required on your CDL to haul hazardous materials?', 'N endorsement', 'T endorsement', 'H endorsement', 'X endorsement', 'C', 'Hazmat', 'medium', 'The H endorsement is required on your CDL to transport hazardous materials. To obtain the H endorsement, you must pass a written knowledge test and a TSA security threat assessment background check.'),
  ('What background check is required to obtain the hazardous materials endorsement?', 'FBI background check', 'State police background check', 'TSA security threat assessment', 'Department of Defense background check', 'C', 'Hazmat', 'medium', 'A TSA (Transportation Security Administration) security threat assessment background check is required to obtain the hazmat endorsement. This was mandated after September 11, 2001 to enhance transportation security.'),
  ('What is CHEMTREC?', 'A type of hazmat placard', 'A 24-hour emergency response hotline for hazardous materials incidents', 'A government agency that regulates hazmat', 'A chemical testing laboratory', 'B', 'Hazmat', 'medium', 'CHEMTREC (Chemical Transportation Emergency Center) is a 24-hour emergency response hotline that provides information and assistance for hazardous materials incidents. It can be contacted for guidance during a hazmat emergency.'),
  ('Where must the driver keep shipping papers for hazardous materials while driving?', 'In the glove box', 'In a pouch on the driver door or within reach while the seat belt is fastened', 'In the trailer', 'Under the seat', 'B', 'Hazmat', 'medium', 'While driving, the driver must keep hazmat shipping papers in a pouch on the driver door pocket or within immediate reach while the seat belt is fastened. This allows quick access in an emergency.'),
  ('Who is responsible for properly packaging, labeling, and marking a hazardous materials shipment?', 'The driver', 'The carrier', 'The shipper', 'The consignee', 'C', 'Hazmat', 'medium', 'The shipper is responsible for properly packaging, labeling, marking, and providing placards and correct shipping papers for hazardous materials. The shipper must also certify that the shipment has been prepared according to all applicable regulations.'),
  ('What should a driver do if they discover a hazmat shipment is leaking or improperly packaged?', 'Deliver it anyway', 'Refuse the shipment and report it', 'Repackage it themselves', 'Ignore it if the leak is small', 'B', 'Hazmat', 'medium', 'A driver must refuse any hazmat shipment that is leaking or improperly packaged. It is the driver''s responsibility to check the shipment and refuse to transport hazardous materials that are not in compliance with regulations.'),
  ('What information must be included on hazardous materials shipping papers?', 'Only the shipper name and address', 'Proper shipping name, hazard class, ID number, and packing group', 'Only the weight of the shipment', 'Only the destination address', 'B', 'Hazmat', 'medium', 'Hazmat shipping papers must include the proper shipping name, hazard class or division number, UN or NA identification number, and packing group. They must also show the total quantity and the shipper''s certification.'),
  ('What is the purpose of the Hazardous Materials Table?', 'To list all truck drivers certified for hazmat', 'To identify regulated hazardous materials and their shipping requirements', 'To list all hazmat incidents', 'To track hazmat vehicle inspections', 'B', 'Hazmat', 'medium', 'The Hazardous Materials Table in 49 CFR 172.101 identifies regulated hazardous materials and provides their proper shipping names, hazard classes, identification numbers, packing groups, labeling requirements, and other shipping information.'),
  ('Division 1.1 explosives are defined as having what type of hazard?', 'Fire hazard', 'Mass explosion hazard', 'Projection hazard', 'Minor blast hazard', 'B', 'Hazmat', 'medium', 'Division 1.1 explosives have a mass explosion hazard, meaning the entire load can explode at once. This is the most dangerous division of explosives and requires the strictest safety precautions during transport.'),
  ('Division 1.2 explosives present what primary hazard?', 'Mass explosion hazard', 'Projection hazard but not mass explosion', 'Fire hazard only', 'No significant hazard', 'B', 'Hazmat', 'medium', 'Division 1.2 explosives have a projection hazard but not a mass explosion hazard. When they detonate, they send out dangerous fragments and projectiles, but the entire load does not explode at once.'),
  ('What does Division 2.1 cover?', 'Non-flammable gases', 'Flammable gases', 'Poisonous gases', 'Refrigerated gases', 'B', 'Hazmat', 'medium', 'Division 2.1 covers flammable gases. These are gases that at normal temperature and pressure form a flammable mixture with air, such as propane, butane, and hydrogen.'),
  ('What does Division 2.3 cover?', 'Flammable gases', 'Non-flammable gases', 'Poisonous or toxic gases', 'Compressed oxygen', 'C', 'Hazmat', 'medium', 'Division 2.3 covers poisonous or toxic gases. These are gases known to be so toxic to humans as to pose a health hazard during transportation, such as chlorine and hydrogen cyanide.'),
  ('When is a DANGEROUS placard used?', 'For all hazmat loads', 'When carrying 1,001 to 5,000 pounds of two or more Table 2 hazard classes that require different placards', 'Only for radioactive materials', 'Only for poisons', 'B', 'Hazmat', 'medium', 'A DANGEROUS placard may be used when carrying 1,001 to 5,000 pounds total of two or more Table 2 hazard classes that would require different placards. It replaces the separate placards for those classes.'),
  ('Which of the following is a carrier or driver responsibility regarding hazmat shipments?', 'Choosing the proper packaging', 'Writing the shipping papers', 'Checking the shipment for proper labeling, marking, and packaging before transport', 'Determining the hazard class', 'C', 'Hazmat', 'medium', 'The carrier and driver are responsible for checking that the hazmat shipment is properly labeled, marked, and packaged before transporting it. The driver must also refuse improperly prepared shipments and report accidents involving hazmat.'),
  ('What is the Emergency Response Guidebook (ERG)?', 'A vehicle maintenance manual', 'A guide for first responders to quickly identify hazards and take protective actions during hazmat incidents', 'A list of approved hazmat carriers', 'A fuel economy guide', 'B', 'Hazmat', 'medium', 'The Emergency Response Guidebook (ERG) is a reference guide for first responders to quickly identify the hazards of materials involved in a transportation incident and to take protective actions. It uses UN/NA identification numbers and placard information.'),
  ('What does the shipper''s certification on shipping papers confirm?', 'That the driver is qualified', 'That the vehicle is inspected', 'That the shipment has been prepared according to all applicable hazmat regulations', 'That the route has been approved', 'C', 'Hazmat', 'medium', 'The shipper''s certification on shipping papers confirms that the shipment has been properly classified, described, packaged, marked, labeled, and is in proper condition for transportation according to the Hazardous Materials Regulations.'),
  ('What must a driver do with hazmat shipping papers when leaving the vehicle but remaining nearby?', 'Take them with you', 'Place them on the dashboard or in the driver door pocket so they are visible to anyone entering the cab', 'Lock them in the glove box', 'Leave them on the passenger seat', 'B', 'Hazmat', 'medium', 'When the driver leaves the vehicle but remains nearby, hazmat shipping papers must be placed on the dashboard or in the driver door pocket so they are clearly visible to anyone entering the cab. This is required so emergency responders can quickly identify the hazardous materials.'),
  ('What is a forbidden hazardous material?', 'Any material with a placard', 'A material that is not permitted to be transported by any mode of transportation under normal conditions', 'Any radioactive material', 'Any flammable liquid', 'B', 'Hazmat', 'medium', 'A forbidden hazardous material is one that may not be offered or accepted for transportation. These items are too dangerous to transport under normal conditions and are identified in the Hazardous Materials Table with a forbidden designation.'),
  ('What is the purpose of hazmat segregation and compatibility rules?', 'To make loading faster', 'To prevent dangerous chemical reactions between incompatible hazardous materials', 'To reduce fuel costs', 'To simplify paperwork', 'B', 'Hazmat', 'medium', 'Hazmat segregation and compatibility rules exist to prevent dangerous chemical reactions that could occur if incompatible hazardous materials are placed near each other. For example, oxidizers must be separated from flammable liquids.'),
  ('When transporting a fumigated load, what warning sign must be placed on the vehicle?', 'POISON placard', 'A FUMIGANT marking sign with the date and time of fumigation', 'DANGER placard', 'INHALATION HAZARD sign', 'B', 'Hazmat', 'medium', 'A fumigated load must display a FUMIGANT marking sign that includes the date and time of fumigation, the type of fumigant used, and a warning that the space is dangerous. This warns anyone who might open the cargo area.'),
  ('What is the minimum amount of a Table 2 hazardous material that requires placarding?', 'Any amount', '100 pounds', '1,001 pounds', '5,000 pounds', 'C', 'Hazmat', 'medium', 'Table 2 hazardous materials require placarding when the gross weight of all Table 2 materials is 1,001 pounds or more. Below that amount, placarding for Table 2 materials is generally not required.'),
  ('For which hazardous materials must placards be displayed regardless of quantity?', 'Class 3 flammable liquids', 'Class 9 miscellaneous', 'Table 1 materials including Division 1.1 explosives, poison gas, and Danger Inhalation Hazard materials', 'Class 5 oxidizers', 'C', 'Hazmat', 'medium', 'Table 1 materials require placarding in any quantity. These include Division 1.1, 1.2, and 1.3 explosives, Division 2.3 poison gas, Division 6.1 (PG I, Inhalation Hazard only), and Class 7 radioactive Yellow III labels. The danger is too great to exempt any amount.'),
  ('What does the four-digit UN or NA identification number on a hazmat shipment indicate?', 'The weight of the shipment', 'The specific hazardous material being transported', 'The shipper code', 'The driver license number', 'B', 'Hazmat', 'medium', 'The four-digit UN (United Nations) or NA (North American) identification number identifies the specific hazardous material being transported. This number appears on shipping papers, packages, and sometimes on orange panels on the vehicle.'),
  ('What is required on the outside of bulk packaging used to transport hazardous materials?', 'Only the shipper name', 'The UN or NA identification number of the contents', 'Only the destination', 'The driver name', 'B', 'Hazmat', 'medium', 'Bulk packaging for hazardous materials must display the UN or NA identification number of its contents on orange panels or directly on the placard. This helps emergency responders identify the material.'),
  ('What must you check before loading hazardous materials into your vehicle?', 'Only the fuel level', 'That the vehicle is properly placarded, packages are properly labeled and marked, and there are no leaks or damage', 'Only the tire pressure', 'Only that the doors close', 'B', 'Hazmat', 'medium', 'Before loading hazmat, you must verify that the vehicle is properly placarded, all packages are correctly labeled and marked, there are no damaged or leaking packages, and incompatible materials are not loaded together.'),
  ('When must you stop your hazmat vehicle before crossing railroad tracks?', 'Never', 'Only if a train is visible', 'Always, unless exempt', 'Only at night', 'C', 'Hazmat', 'medium', 'Vehicles carrying certain hazardous materials are required to stop at all railroad crossings between 15 and 50 feet from the nearest rail. This applies to vehicles displaying hazmat placards unless a specific exemption applies.'),
  ('What should a hazmat driver do if involved in an accident with a hazardous materials spill?', 'Continue driving to the nearest town', 'Keep people away from the scene, notify authorities, and follow the emergency response information', 'Clean up the spill yourself', 'Wait for the shipper to arrive', 'B', 'Hazmat', 'medium', 'In a hazmat accident with a spill, the driver should keep people away from the scene, avoid contact with the material, notify authorities immediately, and refer to the emergency response information in the shipping papers and the Emergency Response Guidebook.'),
  ('What color is the label background for flammable liquid hazmat packages?', 'Green', 'Yellow', 'Red', 'Blue', 'C', 'Hazmat', 'medium', 'Flammable liquid (Class 3) labels and placards have a red background. The color coding system helps quickly identify the hazard class of the material during transport and in emergencies.'),
  ('What is the shape of a hazmat placard?', 'Circle', 'Rectangle', 'Diamond (square turned on a point)', 'Triangle', 'C', 'Hazmat', 'medium', 'Hazmat placards are diamond-shaped, which is a square turned on its point. They must be at least 10.8 inches on each side and are designed to be easily seen and recognized from a distance.'),
  ('An attendant watching a placarded hazmat vehicle must be able to do what?', 'Drive the vehicle', 'Move the vehicle if necessary and know the hazards and emergency procedures', 'Perform vehicle maintenance', 'Load and unload cargo', 'B', 'Hazmat', 'medium', 'An attendant watching a hazmat vehicle must be awake, within 100 feet with the vehicle in clear view, aware of the hazards of the materials, know the emergency procedures, and be able to move the vehicle if necessary.'),
  ('Division 4.3 materials are dangerous because of what property?', 'They are explosive', 'They are radioactive', 'They are dangerous when wet and can produce flammable or toxic gases upon contact with water', 'They are corrosive', 'C', 'Hazmat', 'medium', 'Division 4.3 materials are dangerous when wet. When these materials come in contact with water, they can produce flammable or toxic gases. Examples include sodium and potassium metals. They must be kept dry during transport.'),
  ('What is a Poison Inhalation Hazard (PIH) material?', 'Any solid poison', 'A liquid or gas that is toxic when inhaled and requires special placarding and shipping paper entries', 'Any corrosive material', 'A radioactive gas', 'B', 'Hazmat', 'medium', 'A Poison Inhalation Hazard material is a liquid or gas that is known or presumed to be toxic to humans when inhaled. These materials require the POISON INHALATION HAZARD or INHALATION HAZARD marking on packages and special placard requirements.'),
  ('How are hazardous materials identified on shipping papers when mixed with non-hazardous items?', 'They are listed on a separate page', 'They are highlighted, listed first, or marked with an X or RQ in the HM column', 'They are listed last', 'They are written in red ink', 'B', 'Hazmat', 'medium', 'On shipping papers, hazardous materials must be distinguished from non-hazardous items. This is done by highlighting them, listing them first before any non-hazmat items, or placing an X or RQ in the hazardous materials (HM) column.'),
  ('What is the difference between bulk and non-bulk packaging for hazardous materials?', 'There is no difference', 'Bulk packaging has a capacity greater than 119 gallons for liquids or a net mass greater than 882 pounds for solids', 'Bulk packaging is only for radioactive materials', 'Non-bulk packaging is always physically larger', 'B', 'Hazmat', 'medium', 'Bulk packaging has a maximum capacity greater than 119 gallons for liquids, a net mass greater than 882 pounds for solids, or a water capacity greater than 1,000 pounds for gases. Different regulatory rules apply to each packaging type.');
INSERT INTO questions (question_text, option_a, option_b, option_c, option_d, correct_answer, category, difficulty, explanation) VALUES
  ('When coupling twin trailers, which trailer should be positioned closest to the tractor?', 'The lighter trailer', 'The heavier trailer', 'The shorter trailer', 'It does not matter', 'B', 'Doubles/Triples', 'medium', 'The heavier trailer should always be coupled closest to the tractor in the first position. This improves stability and handling of the combination vehicle.'),
  ('Converter dollies built after March 1, 1998 are required to have what safety feature?', 'Automatic tire chains', 'Anti-lock braking system (ABS)', 'Electronic stability control', 'Automatic slack adjusters only', 'B', 'Doubles/Triples', 'medium', 'Federal law requires that converter dollies manufactured after March 1, 1998 must be equipped with anti-lock braking systems (ABS), indicated by a yellow lamp on the left side of the dolly.'),
  ('Where is the ABS malfunction lamp located on a converter dolly built after March 1, 1998?', 'On the right side of the dolly', 'On the left side of the dolly', 'On the rear of the dolly', 'On the front of the dolly near the pintle hook', 'B', 'Doubles/Triples', 'medium', 'The ABS malfunction lamp on converter dollies built after March 1, 1998 is located on the left side of the dolly. When lit, it indicates a problem with the ABS system.'),
  ('What is the term for the phenomenon where the last trailer in a combination vehicle swings out more than the front trailer during sudden steering movements?', 'Jackknifing', 'Rearward amplification', 'Fishtailing', 'Trailer sway', 'B', 'Doubles/Triples', 'medium', 'Rearward amplification is the phenomenon where quick steering inputs are amplified in the rear trailers. In a triple combination, the last trailer can swing out as much as three times the distance of the first trailer.'),
  ('In a triple trailer combination, how much more can the last trailer swing compared to the first trailer during a sudden lane change?', 'About the same amount', 'About twice as much', 'About three times as much', 'About five times as much', 'C', 'Doubles/Triples', 'medium', 'Due to rearward amplification, the last trailer in a triple combination can swing approximately three times as much as the first trailer during sudden steering maneuvers. This is why smooth, gentle steering is critical.'),
  ('What is the "crack-the-whip" effect in doubles and triples combinations?', 'The front trailer fishtails causing a jackknife', 'The last trailer amplifies the movement of the tractors steering input', 'The tractor pulls away from the trailers', 'The converter dolly disconnects from the trailer', 'B', 'Doubles/Triples', 'medium', 'The crack-the-whip effect occurs when steering movements by the driver are amplified in each successive trailer, causing the last trailer to experience the most exaggerated movement. This is especially dangerous during quick lane changes.'),
  ('When inspecting a converter dolly, you should verify that the pintle hook is locked by doing what?', 'Pulling on the safety chains', 'Looking into the back of the fifth wheel to verify the kingpin is locked', 'Checking the air line pressure gauge', 'Listening for a clicking sound', 'B', 'Doubles/Triples', 'medium', 'When inspecting the coupling on a converter dolly, you should look into the back of the fifth wheel on the dolly to verify that the kingpin of the trailer is properly locked in place.'),
  ('Why should you NEVER unlock the pintle hook with the dolly still under a trailer?', 'It will damage the pintle hook', 'The drop bar ring hitch may fly up and cause serious injury', 'The air lines will disconnect', 'The trailer brakes will lock up', 'B', 'Doubles/Triples', 'medium', 'You should never unlock the pintle hook while the dolly is still under a rear trailer because the ring hitch on the dolly tongue can fly up, potentially causing serious injury or death. Always secure the dolly before unlocking.'),
  ('When coupling a second trailer to a doubles combination, what should you do with the shut-off valves on the first trailer?', 'Close them', 'Open them', 'Leave them in the position they were already in', 'Remove them', 'B', 'Doubles/Triples', 'medium', 'The shut-off valves on the rear of the first trailer must be open to allow air to flow through to the second trailer. Only the shut-off valves at the rear of the last trailer in the combination should be closed.'),
  ('Where should the shut-off valves be closed in a doubles or triples combination?', 'At the rear of the first trailer', 'At the rear of the last trailer only', 'At the rear of every trailer', 'At the front of the first trailer', 'B', 'Doubles/Triples', 'medium', 'Shut-off valves must be closed at the rear of the last trailer in the combination. All other shut-off valves between trailers must be open to allow air to flow through the entire brake system.'),
  ('What is the proper position of the converter dolly air tank drain valve during operation?', 'Open to allow moisture to drain', 'Closed', 'Partially open', 'It depends on the weather conditions', 'B', 'Doubles/Triples', 'medium', 'The converter dolly air tank drain valve must be closed during operation. If left open, air will escape and the dolly brakes will not function properly. Drain the air tank during regular inspections, but always close the valve before driving.'),
  ('What should you check regarding the safety chains when coupling a converter dolly?', 'That they are loosely attached for flexibility', 'That they are secured and crossed under the coupling', 'That they are removed before driving', 'That only one chain is attached', 'B', 'Doubles/Triples', 'medium', 'Safety chains must be securely attached and crossed under the coupling to prevent the dolly tongue from dropping to the ground if the pintle hook connection fails. Crossing the chains creates a cradle to catch the dolly tongue.'),
  ('When driving doubles or triples around a curve, you should:', 'Drive at the posted speed limit for the curve', 'Drive slower than the posted curve speed', 'Drive slightly faster to maintain momentum', 'Accelerate through the curve to stabilize the trailers', 'B', 'Doubles/Triples', 'medium', 'Safe curve speeds posted for single vehicles may be too fast for doubles and triples. Due to the higher center of gravity and rearward amplification, you should always drive slower than the posted curve speed to prevent rollovers.'),
  ('What is the leading cause of rollover for doubles and triples combinations?', 'Tire blowouts', 'Driving too fast around curves and turns', 'Heavy cargo loads', 'Poor road conditions', 'B', 'Doubles/Triples', 'medium', 'Excessive speed in curves and turns is the leading cause of rollover for combination vehicles. Doubles and triples have a higher center of gravity and are more susceptible to rearward amplification, making speed management in curves critical.'),
  ('To prevent rollovers in doubles and triples, a driver should:', 'Make quick steering corrections', 'Steer gently and go slowly around curves', 'Apply the trailer brakes in curves', 'Shift to a higher gear before curves', 'B', 'Doubles/Triples', 'medium', 'To prevent rollovers, drivers of doubles and triples should steer gently and reduce speed before entering curves. Abrupt steering inputs and excessive speed are the primary causes of rollovers in combination vehicles.'),
  ('When should you back a triple trailer combination?', 'Only at very low speeds', 'Only with a spotter', 'Only in a straight line', 'You should never back a triple trailer combination', 'D', 'Doubles/Triples', 'medium', 'You should never back a triple trailer combination. It is nearly impossible to control the direction of three trailers while backing. If you must change direction, pull forward or disconnect and reposition the trailers.'),
  ('What is the first step in coupling twin trailers?', 'Connect the air lines', 'Secure the second trailer to the first with the converter dolly', 'Couple the tractor to the first (heavier) trailer', 'Attach the safety chains', 'C', 'Doubles/Triples', 'medium', 'The first step in coupling twin trailers is to couple the tractor to the first trailer, which should be the heavier of the two. This is done using the standard tractor-to-semitrailer coupling procedure.'),
  ('After connecting the converter dolly to the second trailer and before coupling the dolly to the first trailer, what should you verify?', 'That the trailer doors are closed', 'That the dolly fifth wheel is properly coupled to the second trailer kingpin', 'That the cargo is evenly distributed', 'That the parking brake on the tractor is set', 'B', 'Doubles/Triples', 'medium', 'Before moving the dolly and second trailer into position to couple with the first trailer, you must verify that the dolly fifth wheel is properly locked onto the second trailer kingpin by looking into the back of the fifth wheel.'),
  ('When uncoupling twin trailers, what should you do before disconnecting the converter dolly from the first trailer?', 'Park on a downhill grade', 'Lower the dolly landing gear and disconnect safety chains', 'Raise the dolly landing gear', 'Release all trailer brakes', 'B', 'Doubles/Triples', 'medium', 'Before disconnecting the converter dolly from the first trailer, you must lower the dolly landing gear to support the dolly and second trailer, then disconnect the safety chains and air and electrical lines from the first trailer.'),
  ('When coupling a triple trailer combination, in what order should the trailers be arranged from front to rear?', 'Heaviest, lightest, medium', 'Lightest, heaviest, medium', 'Heaviest, medium, lightest', 'It does not matter as long as all are connected', 'C', 'Doubles/Triples', 'medium', 'In a triple combination, the heaviest trailer goes directly behind the tractor, the medium-weight trailer in the middle, and the lightest trailer at the rear. This arrangement minimizes rearward amplification and improves stability.'),
  ('What component connects the converter dolly to the front trailer in a doubles or triples combination?', 'Fifth wheel', 'Pintle hook and ring hitch', 'Sliding tandem pin', 'Ball hitch', 'B', 'Doubles/Triples', 'medium', 'The converter dolly connects to the front trailer using a pintle hook on the first trailer and a ring hitch (drawbar eye) on the dolly tongue. This connection must be secure, and safety chains must be attached and crossed beneath it.'),
  ('During your pre-trip inspection of a doubles combination, you notice the spare tire on the converter dolly is loose. What should you do?', 'It is fine as long as it stays on the dolly', 'Secure the spare tire properly before driving', 'Remove the spare tire and leave it behind', 'Place the spare tire inside the trailer', 'B', 'Doubles/Triples', 'medium', 'The spare tire on the converter dolly must be properly secured before driving. A loose spare tire could come free during transit, creating a serious road hazard for other vehicles.'),
  ('How should the air lines between trailers be routed in a doubles or triples combination?', 'Dragging on the ground for easy inspection', 'Supported so they do not hang down and become tangled or caught', 'Wrapped tightly around the dolly frame', 'Left loose for flexibility', 'B', 'Doubles/Triples', 'medium', 'Air lines between trailers should be properly supported so they do not sag, drag on the ground, or become tangled. Damaged or snagged air lines can cause loss of braking ability in the rear trailers.'),
  ('When connecting glad hands between trailers, what should you check for?', 'That the glad hands are loosely attached', 'That the rubber seals are in good condition and connections are secure and free of dirt', 'That the glad hands are painted the same color', 'That only one glad hand is connected', 'B', 'Doubles/Triples', 'medium', 'When connecting glad hands, verify that rubber seals are in good condition and not cracked or worn. Clean the connections of dirt and debris before coupling. Ensure they are securely fastened to prevent air leaks that could cause brake failure.'),
  ('What should you do with the electrical cord when coupling trailers in a doubles or triples combination?', 'Leave it disconnected until needed', 'Ensure it is firmly seated in the socket and secured', 'Tape it loosely to the air lines', 'Connect it only if the trailer has lights', 'B', 'Doubles/Triples', 'medium', 'Electrical cords must be firmly seated in their sockets to ensure proper function of trailer lights, turn signals, and brake lights. Loose connections can cause intermittent light failures, which are hazardous and illegal.'),
  ('What is the recommended safe following distance for doubles and triples on a dry road at highway speed?', 'One second for every 10 feet of vehicle length', 'At least one second for every 10 feet of vehicle length plus an additional second for the extra trailers', 'The same distance as a passenger car', 'Two vehicle lengths', 'B', 'Doubles/Triples', 'medium', 'Doubles and triples require significantly more stopping distance than single vehicles. You should allow at least one second for every 10 feet of vehicle length, plus an additional second because of the extra trailers. At highway speeds, this means a very large following distance.'),
  ('When making a lane change with a doubles or triples combination, you should:', 'Change lanes quickly to minimize time spent between lanes', 'Signal early, check mirrors carefully, and change lanes gradually', 'Only change lanes on straight roads and never on curves', 'Use your horn to alert other drivers before changing lanes', 'B', 'Doubles/Triples', 'medium', 'When changing lanes with doubles or triples, signal well in advance, check all mirrors carefully for traffic, and make the lane change gradually and smoothly. Quick lane changes cause the crack-the-whip effect and increase the risk of rollover.'),
  ('What is the correct procedure for draining the converter dolly air tank?', 'Drain before each trip and leave the valve open', 'Drain regularly during inspections and close the valve before driving', 'Never drain the dolly air tank', 'Drain only when the air pressure warning light comes on', 'B', 'Doubles/Triples', 'medium', 'The converter dolly air tank should be drained regularly during inspections to remove accumulated moisture and oil. However, the drain valve must always be closed before driving to ensure proper air pressure for the dolly brakes.'),
  ('When parking a doubles combination overnight, what is the proper procedure?', 'Park on a slight incline and set only the tractor brakes', 'Park on level ground, set parking brakes on all units, and chock the wheels if necessary', 'Disconnect the trailers and park them separately', 'Leave the engine running with the brakes set', 'B', 'Doubles/Triples', 'medium', 'When parking doubles or triples, park on level ground, set the parking brakes on all units including the tractor, trailers, and dolly. Use wheel chocks when necessary, especially on any grade. Ensure the combination is secured against rolling.'),
  ('What is the 7-step inspection procedure adapted for doubles and triples?', 'It only applies to single trailers', 'The same basic 7-step method used for any commercial vehicle, with additional checks on coupling devices, converter dollies, and all trailer connections', 'A simplified 3-step check for multiple trailers', 'An inspection done only at weigh stations', 'B', 'Doubles/Triples', 'medium', 'The 7-step inspection method for doubles and triples follows the same basic procedure as for any commercial vehicle but includes additional checks on all coupling devices, converter dollies, safety chains, air and electrical connections between all units.'),
  ('Which of the following is TRUE about bridge weight laws for doubles and triples?', 'Bridge laws do not apply to doubles and triples', 'Doubles and triples must comply with bridge weight laws which may limit total weight based on axle spacing', 'Only the tractor weight counts for bridge laws', 'Bridge laws only apply when crossing bridges over water', 'B', 'Doubles/Triples', 'medium', 'Doubles and triples must comply with federal and state bridge weight formulas that limit the maximum weight based on the number of axles and the distance between them. Violations can result in fines and being placed out of service.'),
  ('If you are driving a doubles combination and a tire blows out on the rear trailer, you should:', 'Brake hard to stop as quickly as possible', 'Hold the steering wheel firmly, stay off the brakes, and gradually slow down', 'Accelerate to maintain control', 'Immediately pull to the left shoulder', 'B', 'Doubles/Triples', 'medium', 'If a tire blows out on any trailer, hold the steering wheel firmly, stay off the brakes to avoid a jackknife, and gradually slow down by releasing the accelerator. Pull off the road to a safe location once you have the vehicle under control.'),
  ('Which of the following helps prevent jackknifing in a doubles or triples combination?', 'Hard braking on wet roads', 'Keeping the trailers lightly loaded', 'Avoiding sudden braking and steering inputs', 'Driving faster than surrounding traffic', 'C', 'Doubles/Triples', 'medium', 'Jackknifing is primarily caused by sudden braking or sharp steering movements. To prevent jackknifing in doubles and triples, avoid sudden stops, brake gently and early, maintain a safe following distance, and adjust speed for road conditions.'),
  ('When coupling a converter dolly to a second trailer, the dolly air tank should be:', 'Full of air with the drain valve open', 'Charged with air and the drain valve closed', 'Completely empty of air', 'At half pressure', 'B', 'Doubles/Triples', 'medium', 'The converter dolly air tank should be properly charged with air and the drain valve must be closed to maintain air pressure. This ensures the dolly brakes function correctly when the combination is in motion.'),
  ('What happens if you leave the shut-off valves closed on the first trailer of a doubles combination?', 'Nothing, they should be closed', 'Air will not flow to the rear trailer brakes, causing them to not function properly', 'The front trailer brakes will fail', 'The tractor engine will stall', 'B', 'Doubles/Triples', 'medium', 'If shut-off valves on the first trailer are left closed, air cannot flow to the second trailer, meaning the rear trailer brakes will not receive air pressure and may not function. This creates a dangerous situation with insufficient braking.'),
  ('When uncoupling the rear trailer of a triples combination, the first step is to:', 'Disconnect the air and electrical lines from the middle trailer to the converter dolly', 'Release the dolly fifth wheel latch', 'Park the combination on level ground and set all brakes', 'Remove the safety chains first', 'C', 'Doubles/Triples', 'medium', 'The first step when uncoupling any trailer combination is to park on level ground and set all parking brakes on every unit. This ensures nothing moves during the uncoupling process and prevents accidents.'),
  ('A converter dolly has its own:', 'Engine and transmission', 'Air tank, frame, one or more axles, and fifth wheel', 'Fuel tank and electrical generator', 'Cab and steering wheel', 'B', 'Doubles/Triples', 'medium', 'A converter dolly consists of a frame, one or more axles with wheels, an air tank, a fifth wheel coupling on top to connect to the trailer above it, and a drawbar with a ring hitch to connect to the pintle hook on the trailer in front.'),
  ('The pintle hook is located on which part of the combination vehicle?', 'The front of the converter dolly', 'The rear of the trailer ahead of the dolly', 'The front of the tractor', 'The roof of the trailer', 'B', 'Doubles/Triples', 'medium', 'The pintle hook is mounted on the rear of the trailer that is ahead of the converter dolly. The ring hitch on the dolly tongue connects to the pintle hook, forming the coupling between the trailer and the dolly.'),
  ('At highway speeds, doubles and triples are more likely to roll over than single combination vehicles because:', 'They weigh more than single trailers', 'They have more tires on the road', 'The rearward amplification effect and higher overall center of gravity make them less stable', 'They have stronger brakes', 'C', 'Doubles/Triples', 'medium', 'Doubles and triples are more prone to rollover at highway speeds because rearward amplification magnifies any lateral movement, and the overall combination may have a higher center of gravity. Speed management and gentle steering are essential.'),
  ('If you must back a doubles combination, you should:', 'Back at high speed to keep the trailers straight', 'Disconnect the rear trailer and back only the tractor and first trailer if possible', 'Have two spotters, one at each trailer', 'Use the trailer brakes to steer while backing', 'B', 'Doubles/Triples', 'medium', 'If you must back a doubles combination, the safest approach is to disconnect the rear trailer and back only the tractor and first semitrailer. Backing with two trailers is extremely difficult and should be avoided whenever possible.'),
  ('What should you inspect on the converter dolly fifth wheel during a pre-trip inspection?', 'Only that it is painted', 'That it is properly greased, not cracked or broken, and the locking mechanism is secure', 'That it is loose enough to allow turning', 'Only the mounting bolts', 'B', 'Doubles/Triples', 'medium', 'During pre-trip inspection, check that the converter dolly fifth wheel is properly greased, not cracked, broken, or missing parts, and that the locking mechanism securely holds the trailer kingpin. Look into the back of the fifth wheel to verify the lock.'),
  ('What is the danger of improperly crossed or unsecured safety chains on a converter dolly?', 'The dolly may vibrate excessively', 'If the pintle hook connection fails, the dolly tongue could drop to the ground causing loss of control', 'The trailer lights will not work', 'The air brakes will not release', 'B', 'Doubles/Triples', 'medium', 'Safety chains must be properly crossed under the dolly tongue and securely attached. If the pintle hook fails and the safety chains are not properly secured, the dolly tongue will drop to the road surface, causing loss of control and a potential catastrophic accident.'),
  ('When coupling a triple trailer combination, after coupling the tractor to the first trailer, what is the next step?', 'Connect the third trailer to the second trailer', 'Couple the second trailer to the first using a converter dolly', 'Drive forward to test the coupling', 'Load the first trailer', 'B', 'Doubles/Triples', 'medium', 'After coupling the tractor to the first (heaviest) trailer, the next step is to couple the second trailer to the first using a converter dolly. Once the doubles combination is complete and checked, you then couple the third (lightest) trailer.'),
  ('Why is it important to test the trailer brakes individually when inspecting a doubles or triples combination?', 'To check fuel consumption', 'To ensure each trailer unit has working brakes and can stop independently if needed', 'To verify the speedometer is accurate', 'To warm up the engine', 'B', 'Doubles/Triples', 'medium', 'Testing each trailer brake individually during inspection ensures that every unit in the combination has properly functioning brakes. A trailer with failed brakes adds weight without stopping power, greatly increasing stopping distance and accident risk.'),
  ('When driving doubles or triples in strong crosswinds, you should:', 'Speed up to push through the wind', 'Reduce speed and maintain a firm grip on the steering wheel', 'Open the trailer doors to reduce wind resistance', 'Move to the left lane for more room', 'B', 'Doubles/Triples', 'medium', 'Strong crosswinds are particularly dangerous for doubles and triples because of their large surface area and multiple pivot points. Reduce speed, hold the steering wheel firmly, and be prepared for sudden gusts, especially when exiting tunnels or passing large vehicles.'),
  ('What should you check regarding the glad hands before starting a trip with doubles or triples?', 'That they are a matching color', 'That they are properly connected with no air leaks and the rubber seals are not damaged', 'That they are brand new', 'That they are disconnected for safety', 'B', 'Doubles/Triples', 'medium', 'Before every trip, check that all glad hand connections between units are properly sealed and secure with no air leaks. Damaged rubber seals must be replaced. Air leaks at glad hands can cause gradual loss of braking in rear trailers.'),
  ('During an emergency stop with a doubles or triples combination, what should you be most concerned about?', 'Running out of fuel', 'Jackknifing or trailer swing due to the multiple pivot points in the combination', 'Damage to the cargo', 'The radio falling off the dash', 'B', 'Doubles/Triples', 'medium', 'During an emergency stop with doubles or triples, the multiple pivot points between units make the combination highly susceptible to jackknifing and trailer swing. Brake firmly but controlled, avoid locking wheels, and steer to maintain a straight path if possible.'),
  ('What is the purpose of the converter dolly in a doubles or triples combination?', 'To carry extra fuel for long trips', 'To convert a semitrailer into a full trailer so it can be towed behind another trailer', 'To generate electrical power for trailer lights', 'To provide additional engine power', 'B', 'Doubles/Triples', 'medium', 'A converter dolly converts a semitrailer into a full trailer by providing a fifth wheel coupling and its own axle with wheels. This allows the semitrailer to be towed behind another trailer, creating a doubles or triples combination.'),
  ('When going down a steep grade with a doubles or triples combination, you should:', 'Use a lower gear and apply brakes intermittently using proper braking technique', 'Ride the brakes continuously to maintain a steady speed', 'Shift into neutral to save fuel', 'Apply only the trailer brakes', 'A', 'Doubles/Triples', 'medium', 'When descending a steep grade with doubles or triples, use a low gear selected before the descent and apply brakes using the proper snub braking technique: apply brakes to reduce speed, release to allow cooling, then repeat. Continuous braking causes brake fade.'),
  ('What is the correct order to connect air lines when coupling a converter dolly to a trailer?', 'Connect the emergency (supply) line first, then the service line', 'Connect the service line first, then the emergency line', 'Connect both at exactly the same time', 'Only the service line needs to be connected', 'A', 'Doubles/Triples', 'medium', 'When coupling a converter dolly, connect the emergency (supply) air line first. This charges the trailer air tank and releases the emergency brakes. Then connect the service line. This order ensures the trailer brakes are properly supplied with air.');
INSERT INTO questions (question_text, option_a, option_b, option_c, option_d, correct_answer, category, difficulty, explanation) VALUES
  ('What is liquid surge?', 'The movement of liquid in a partially filled tank', 'The pressure buildup in a sealed tank', 'The rate at which liquid is pumped into a tank', 'The temperature change of liquid during transport', 'A', 'Tanker', 'medium', 'Liquid surge is the movement of liquid inside a partially filled tank. As the vehicle brakes, turns, or changes speed, the liquid moves and pushes against the walls of the tank, affecting vehicle handling and stability.'),
  ('What effect can side-to-side surge have on a tanker vehicle?', 'Increased fuel efficiency', 'Tire blowouts', 'Rollover', 'Engine overheating', 'C', 'Tanker', 'medium', 'Side-to-side surge can cause a tanker to roll over. When liquid surges to one side during a turn or lane change, it shifts the center of gravity and can tip the vehicle over, especially on curves.'),
  ('What is the primary danger of forward-and-back surge?', 'It causes the tank to leak', 'It pushes the truck forward through intersections when stopping', 'It damages the tank baffles', 'It increases tire wear', 'B', 'Tanker', 'medium', 'Forward-and-back surge pushes the truck forward when you are trying to stop. The liquid continues moving forward due to inertia after braking begins, which can push the vehicle into an intersection or into the vehicle ahead.'),
  ('Why should you never fill a tank completely full?', 'To save money on product', 'To reduce vehicle weight', 'Liquid expands as it warms and needs room for expansion (outage)', 'To allow space for the pump mechanism', 'C', 'Tanker', 'medium', 'You should never fill a tank completely full because liquids expand as they warm. The empty space left in the tank, called outage, allows room for this expansion. Without outage, pressure buildup could damage the tank or cause leaks.'),
  ('What is outage?', 'The amount of time a tanker is out of service', 'The empty space left in a tank to allow for liquid expansion', 'The distance between the tanker and the vehicle ahead', 'The amount of liquid lost during transport', 'B', 'Tanker', 'medium', 'Outage is the empty space intentionally left in a tank to allow for liquid expansion. As liquids warm during transport, they expand, and without adequate outage the tank could rupture or overflow.'),
  ('What are baffles in a tank vehicle?', 'External supports that hold the tank in place', 'Internal walls with holes that allow liquid to flow through but reduce surge', 'Devices that measure the amount of liquid in the tank', 'Valves used to load and unload the tank', 'B', 'Tanker', 'medium', 'Baffles are internal walls inside a tank that have holes (openings) at the top and bottom to allow liquid to flow through. They help reduce the forward-and-back surge of liquid but do not prevent side-to-side surge.'),
  ('Baffled tanks reduce which type of surge?', 'Side-to-side surge', 'Forward-and-back surge', 'Both side-to-side and forward-and-back surge', 'Neither type of surge', 'B', 'Tanker', 'medium', 'Baffles reduce forward-and-back surge by breaking the tank into sections. However, because the baffles have holes that allow liquid to pass through, they do not prevent side-to-side surge. Drivers must still be cautious on curves and turns.'),
  ('Why are smooth bore (unbaffled) tanks required for hauling food-grade liquids like milk?', 'They are lighter in weight', 'Sanitation regulations require them because baffles are difficult to clean', 'They reduce surge more effectively', 'They are cheaper to manufacture', 'B', 'Tanker', 'medium', 'Smooth bore tanks are required for food-grade products like milk because sanitation regulations prohibit baffles. Baffles create areas that are extremely difficult to clean and sanitize, which could lead to bacterial contamination of food products.'),
  ('Which type of tank has the strongest forward-and-back surge?', 'Baffled tanks', 'Compartmented tanks', 'Smooth bore (unbaffled) tanks', 'Pressurized tanks', 'C', 'Tanker', 'medium', 'Smooth bore (unbaffled) tanks have the strongest forward-and-back surge because there are no internal walls to slow the movement of liquid. Drivers of smooth bore tankers must be especially careful when braking and stopping.'),
  ('What are bulkheads in a tank vehicle?', 'Holes in the baffles that allow liquid to pass through', 'Dividers that separate a tank into completely separate compartments', 'External bracing on the tank shell', 'The rounded ends of the tank', 'B', 'Tanker', 'medium', 'Bulkheads are solid dividers that separate a tank into completely separate compartments. Unlike baffles, bulkheads do not have holes, so each compartment holds its own separate load. Drivers must pay attention to weight distribution when loading compartmented tanks.'),
  ('Why is weight distribution important when loading a compartmented tank?', 'To prevent the tank from rusting', 'Uneven weight distribution can cause poor handling and put too much stress on axles', 'To make unloading faster', 'To increase fuel efficiency', 'B', 'Tanker', 'medium', 'Proper weight distribution in compartmented tanks is critical. An improperly loaded tank can put too much weight on some axles and too little on others, leading to poor handling, excessive tire wear, and potential violations of axle weight limits.'),
  ('Why do tanker vehicles have a high center of gravity?', 'Because the engine is mounted high', 'Because the liquid cargo is carried high above the ground in the tank', 'Because of the heavy frame rails', 'Because of the oversized tires', 'B', 'Tanker', 'medium', 'Tanker vehicles have a high center of gravity because the liquid cargo is carried in a tank mounted high above the road surface. This high center of gravity makes tankers more prone to rollovers, especially on curves and during sudden maneuvers.'),
  ('What does a high center of gravity mean for tanker vehicle handling?', 'The vehicle is easier to steer', 'The vehicle has better traction', 'The vehicle is more likely to roll over', 'The vehicle stops more quickly', 'C', 'Tanker', 'medium', 'A high center of gravity means the vehicle is more likely to roll over, especially when turning, changing lanes, or driving on curves. Tanker drivers must drive at reduced speeds in curves and avoid sudden steering movements to reduce rollover risk.'),
  ('When inspecting a tank vehicle, which of the following should you check?', 'Leaks, special equipment, and emergency shutoff devices', 'Only the tires and brakes', 'Just the fluid level inside the tank', 'Only the rearview mirrors', 'A', 'Tanker', 'medium', 'When inspecting a tank vehicle, you should check for leaks from the tank and fittings, verify that special equipment such as vapor recovery kits is in place, and ensure emergency shutoff devices are working properly, in addition to performing a standard pre-trip inspection.'),
  ('What is the safest way to drive a tanker through a curve?', 'Accelerate through the curve to maintain traction', 'Drive at or slightly above the posted speed limit', 'Slow down to well below the posted speed limit before entering the curve', 'Brake hard while in the curve', 'C', 'Tanker', 'medium', 'You should slow down to well below the posted speed limit before entering a curve. Tests have shown that tankers can roll over at the posted speed limit for a curve. Slowing down before the curve and maintaining a steady speed through it is the safest approach.'),
  ('Tests have shown that tankers can overturn at what speed on curves?', 'Only at double the posted speed limit', 'At speeds well below the posted speed limit', 'At the posted speed limit for the curve', 'Only at speeds over 70 mph', 'C', 'Tanker', 'medium', 'Tests have shown that tankers can overturn at the posted speed limit for a curve. This is why tanker drivers should always take curves well below the posted speed, especially when the tank is partially loaded and surge effects are strongest.'),
  ('What endorsement is required to drive a tank vehicle?', 'H endorsement', 'P endorsement', 'N endorsement (tanker endorsement)', 'S endorsement', 'C', 'Tanker', 'medium', 'The N endorsement (tanker endorsement) is required to drive a tank vehicle designed to transport liquid or gaseous materials in a tank or tanks with an individual capacity of more than 119 gallons and an aggregate capacity of 1,000 gallons or more.'),
  ('At what aggregate capacity is a tanker endorsement required?', '500 gallons or more', '1,000 gallons or more', '2,000 gallons or more', '5,000 gallons or more', 'B', 'Tanker', 'medium', 'A tanker endorsement is required when the vehicle is designed to transport liquid or gaseous materials in a tank with an aggregate rated capacity of 1,000 gallons or more. Individual tank capacities of more than 119 gallons count toward the 1,000-gallon aggregate.'),
  ('What individual tank capacity counts toward the 1,000-gallon aggregate for the tanker endorsement?', 'Over 50 gallons', 'Over 100 gallons', 'Over 119 gallons', 'Over 200 gallons', 'C', 'Tanker', 'medium', 'Individual tank capacities of more than 119 gallons count toward the 1,000-gallon aggregate that requires a tanker endorsement. Smaller tanks of 119 gallons or less are not counted when determining if the tanker endorsement is needed.'),
  ('What is an X endorsement on a CDL?', 'An endorsement for extra-long vehicles', 'A combined tanker and hazardous materials endorsement', 'An endorsement for driving in extreme weather', 'An endorsement for transporting explosives only', 'B', 'Tanker', 'medium', 'The X endorsement is a combined endorsement that covers both tanker (N) and hazardous materials (H) requirements. A driver with an X endorsement is authorized to drive a tank vehicle carrying hazardous materials, rather than needing separate N and H endorsements.'),
  ('Why is stopping distance increased for tanker vehicles?', 'Because tankers have smaller brakes', 'Because liquid surge pushes the vehicle forward even after braking', 'Because tankers have fewer axles', 'Because tanker tires are narrower', 'B', 'Tanker', 'medium', 'Stopping distance is increased for tanker vehicles because liquid surge continues to push the vehicle forward even after the brakes are applied. The weight of the liquid moving toward the front of the tank adds momentum and makes it harder to stop quickly.'),
  ('Which loading condition creates the most dangerous surge effect?', 'A completely full tank', 'A completely empty tank', 'A partially loaded tank', 'A tank with baffles', 'C', 'Tanker', 'medium', 'A partially loaded tank creates the most dangerous surge effect because the liquid has the most room to move around. A full tank has little room for liquid movement, and an empty tank has no liquid to surge. Partially loaded smooth bore tanks are especially dangerous.'),
  ('How should a tanker driver handle wet roads?', 'Drive at normal highway speed', 'Reduce speed significantly and increase following distance', 'Use cruise control to maintain steady speed', 'Drive in the left lane for better visibility', 'B', 'Tanker', 'medium', 'On wet roads, tanker drivers should reduce speed significantly and increase following distance. Wet roads reduce traction, and combined with the effects of liquid surge and a high center of gravity, tankers are even more susceptible to skidding and rollovers in wet conditions.'),
  ('What is the proper braking technique for a tanker vehicle?', 'Brake hard and fast at the last moment', 'Use steady, controlled braking pressure and brake early', 'Pump the brakes rapidly at all times', 'Only use the engine brake, never the service brakes', 'B', 'Tanker', 'medium', 'The proper braking technique for a tanker is to apply steady, controlled braking pressure and begin braking earlier than you would in a non-tanker vehicle. Hard or sudden braking can cause liquid surge that pushes the vehicle forward and may result in a jackknife or loss of control.'),
  ('What happens if you brake too hard in a smooth bore tanker?', 'The baffles absorb the impact', 'The liquid surges forward with great force, pushing the truck and possibly causing a skid or jackknife', 'The tank automatically releases pressure', 'Nothing different from a regular truck', 'B', 'Tanker', 'medium', 'Braking too hard in a smooth bore tanker causes the liquid to surge forward with great force because there are no baffles to slow it down. This forward surge pushes the truck, making it very difficult to stop and potentially causing a skid or jackknife.'),
  ('What emergency equipment should be checked during a tanker vehicle inspection?', 'Only a fire extinguisher', 'Emergency shutoff systems, fire extinguisher, and spill containment equipment', 'Just the CB radio', 'Only the reflective triangles', 'B', 'Tanker', 'medium', 'During a tanker vehicle inspection, you should check emergency shutoff systems, fire extinguisher(s), and spill containment equipment in addition to standard emergency equipment like reflective triangles. All emergency equipment must be in good working condition.'),
  ('How often must a tanker endorsement be renewed?', 'Every year', 'Every 2 years', 'When the CDL is renewed, typically every 4 to 5 years depending on the state', 'Only once, it never expires', 'C', 'Tanker', 'medium', 'A tanker endorsement must be renewed when the CDL is renewed, which is typically every 4 to 5 years depending on the state. Drivers may need to pass a knowledge test again at renewal time depending on state requirements.'),
  ('When driving a tanker on a curve posted at 35 mph, what speed should you travel?', '35 mph as posted', 'Well below 35 mph', '40 mph to get through quickly', 'It depends on the weight of the cargo only', 'B', 'Tanker', 'medium', 'You should travel well below the posted 35 mph speed for the curve. Tankers can roll over at the posted curve speed because of their high center of gravity and the effects of liquid surge. Always reduce speed to well below posted limits before entering any curve.'),
  ('What is the danger of loading only the front compartment of a compartmented tanker?', 'The front compartment might leak', 'It puts too much weight on the front axle, causing poor handling and possible steering problems', 'It increases fuel consumption slightly', 'There is no danger as long as the compartment is not overfilled', 'B', 'Tanker', 'medium', 'Loading only the front compartment puts too much weight on the front axle and not enough on the rear axles. This uneven weight distribution causes poor handling, can make steering difficult, and may exceed front axle weight limits, creating a serious safety hazard.'),
  ('What is a vapor recovery system on a tanker?', 'A system that cools the liquid to prevent evaporation', 'A system that captures fuel vapors during loading and unloading to prevent air pollution', 'A system that pressurizes the tank', 'A system that monitors tire pressure', 'B', 'Tanker', 'medium', 'A vapor recovery system captures fuel vapors that would otherwise escape into the atmosphere during loading and unloading operations. These systems are required at many facilities to reduce air pollution and prevent the release of volatile organic compounds.'),
  ('What is the purpose of an emergency shutoff system on a tanker?', 'To shut down the engine in an emergency', 'To quickly stop the flow of product in case of a leak, spill, or other emergency', 'To activate the emergency flashers', 'To lock the trailer brakes', 'B', 'Tanker', 'medium', 'Emergency shutoff systems are designed to quickly stop the flow of product from the tank in case of a leak, spill, hose rupture, or other emergency during loading or unloading. Drivers must know the location and operation of all emergency shutoff controls.'),
  ('What is bonding and grounding used for when working with flammable liquids?', 'To weigh the tank accurately', 'To prevent static electricity from creating a spark that could ignite flammable vapors', 'To keep the tank warm in cold weather', 'To test the purity of the liquid', 'B', 'Tanker', 'medium', 'Bonding and grounding are used to prevent static electricity from creating a spark that could ignite flammable vapors. Bonding connects the tank to the receiving container to equalize electrical charge, while grounding connects equipment to the earth to discharge static buildup.'),
  ('When should bonding and grounding be performed?', 'After the product has been fully transferred', 'Before opening the valves or hatches and beginning product transfer', 'Only when it is raining', 'Only when transferring gasoline, not other flammable liquids', 'B', 'Tanker', 'medium', 'Bonding and grounding must be performed before opening any valves, hatches, or dome covers and before beginning the transfer of any flammable liquid. This ensures that any static charge is safely discharged before flammable vapors are exposed to potential sparks.'),
  ('Why is a full tank less susceptible to surge than a partially loaded one?', 'Full tanks have more baffles', 'When a tank is full, there is very little room for the liquid to move', 'Full tanks are always pressurized', 'The liquid is heavier when the tank is full', 'B', 'Tanker', 'medium', 'When a tank is completely full (with proper outage), there is very little room for the liquid to move. The liquid cannot build up momentum because it has nowhere to go. In a partially filled tank, the liquid has room to slosh and surge, creating more force against the tank walls.'),
  ('What should you do before making a lane change in a tanker?', 'Speed up quickly to pass other vehicles', 'Check mirrors, signal early, and make the change slowly and smoothly', 'Brake hard, then change lanes quickly', 'Flash your headlights at other drivers', 'B', 'Tanker', 'medium', 'Before making a lane change in a tanker, check your mirrors, signal early, and make the change slowly and smoothly. Abrupt steering movements cause side-to-side surge that can shift the center of gravity and increase the risk of a rollover.'),
  ('Why must tanker drivers increase their following distance?', 'Tankers are not allowed to travel in the right lane', 'Tankers need more stopping distance because of liquid surge and heavier weight', 'Tanker brakes are less effective than other truck brakes', 'It is not necessary to increase following distance in a tanker', 'B', 'Tanker', 'medium', 'Tanker drivers must increase their following distance because tankers need more stopping distance. Liquid surge adds forward force when braking, and the heavy weight of the liquid increases overall stopping distance. Extra following distance gives the driver more time and space to stop safely.'),
  ('How does liquid surge affect a vehicle going downhill?', 'It has no effect on downhill driving', 'The surge pushes the vehicle forward faster and makes it harder to control speed', 'It helps the vehicle slow down', 'It only affects the vehicle when going uphill', 'B', 'Tanker', 'medium', 'When going downhill, liquid surge pushes the vehicle forward, adding to the force of gravity pulling the vehicle downhill. This makes it harder to control speed and increases stopping distance. Tanker drivers should use a lower gear and start downhill at a reduced speed.'),
  ('What is the best way to prevent rollover in a tanker?', 'Load the tank as full as possible at all times', 'Drive slowly, especially on curves, ramps, and turns', 'Use the highest gear possible', 'Drive close to other vehicles for drafting', 'B', 'Tanker', 'medium', 'The best way to prevent rollover is to drive slowly, especially on curves, highway on-ramps and off-ramps, and turns. The high center of gravity and liquid surge in tankers make them very susceptible to rollover. Reducing speed gives you more control and reduces the force of the surge.'),
  ('What are the risks of hauling liquid in a smooth bore tank?', 'No risks beyond a normal trailer', 'Maximum surge effect with no baffles to slow liquid movement, increasing stopping distance and rollover risk', 'The liquid freezes more easily', 'The tank is more likely to corrode', 'B', 'Tanker', 'medium', 'Smooth bore tanks present the maximum surge effect because there are no internal baffles to reduce liquid movement. This means the liquid can build up strong forward-and-back and side-to-side surge forces, significantly increasing both stopping distance and rollover risk.'),
  ('What should a driver do if liquid begins leaking from a tanker?', 'Continue driving to the nearest repair shop', 'Pull over safely, secure the vehicle, and use emergency shutoff systems to stop the flow', 'Speed up to reduce the leak pressure', 'Ignore it if the leak is small', 'B', 'Tanker', 'medium', 'If liquid begins leaking from a tanker, the driver should pull over to a safe location as soon as possible, secure the vehicle, and use the emergency shutoff systems to stop the flow of product. The driver should then follow emergency procedures and contact the appropriate authorities.'),
  ('How does the amount of liquid in a tank affect the center of gravity?', 'It has no effect', 'A partially loaded tank allows liquid to shift, causing the center of gravity to move unpredictably', 'A full tank always has a lower center of gravity than a partially loaded one', 'Center of gravity only matters for dry cargo', 'B', 'Tanker', 'medium', 'In a partially loaded tank, the liquid can shift from side to side and front to back, causing the center of gravity to change unpredictably. This is particularly dangerous on curves and during braking because the shifting center of gravity increases the risk of rollover and loss of control.'),
  ('When approaching a stop sign in a tanker, what should you do differently than in a regular vehicle?', 'Nothing different', 'Begin braking earlier and use controlled, steady pressure to allow for liquid surge', 'Brake harder at the last second', 'Always downshift to the lowest gear immediately', 'B', 'Tanker', 'medium', 'When approaching a stop sign in a tanker, begin braking earlier than you would in a regular vehicle and use controlled, steady pressure. This accounts for the forward surge of liquid that will push the truck forward as you slow down, and prevents sudden stops that could cause loss of control.'),
  ('Which endorsement combination allows you to haul hazardous materials in a tanker?', 'N endorsement only', 'H endorsement only', 'X endorsement or both N and H endorsements', 'P and S endorsements', 'C', 'Tanker', 'medium', 'To haul hazardous materials in a tanker, you need either an X endorsement (which combines both) or separate N (tanker) and H (hazardous materials) endorsements. The X endorsement is a convenient single endorsement that covers both requirements.'),
  ('What causes the most tanker rollovers?', 'Mechanical failure', 'Taking curves and turns too fast', 'Tire blowouts', 'High winds', 'B', 'Tanker', 'medium', 'Taking curves and turns too fast is the leading cause of tanker rollovers. The high center of gravity and liquid surge make tankers especially vulnerable to rolling over when cornering. Drivers must slow down well below posted speeds for curves, ramps, and turns.'),
  ('What is the proper way to ground a tanker before unloading flammable liquids?', 'Attach a grounding cable from the tank to the ground rod or approved grounding point before opening any valves', 'Ground the tank after unloading is complete', 'Grounding is only needed in dry weather', 'Simply touch the tank with your hand', 'A', 'Tanker', 'medium', 'The proper way to ground a tanker is to attach a grounding cable from the tank to a ground rod or approved grounding point before opening any valves, hatches, or dome covers. This safely discharges any static electricity that could ignite flammable vapors during the unloading process.'),
  ('During a pre-trip inspection of a tanker, what should you look for on the tank itself?', 'Only the paint condition', 'Dents, leaks, broken or missing parts on valves and piping, and proper seal condition', 'Only whether it is full or empty', 'Only the placards', 'B', 'Tanker', 'medium', 'During a pre-trip inspection of the tank, you should look for dents or damage to the tank shell, leaks from the tank body or fittings, broken or missing parts on valves and piping, and the condition of seals and gaskets. Any defects could lead to leaks or failures during transport.'),
  ('What is the danger of driving a tanker in strong crosswinds?', 'Crosswinds only affect empty tankers', 'Strong crosswinds can push the high-profile tanker sideways and contribute to side-to-side surge, increasing rollover risk', 'Crosswinds improve fuel efficiency', 'There is no additional danger for tankers', 'B', 'Tanker', 'medium', 'Strong crosswinds are especially dangerous for tankers because of their large, high-profile shape. The wind pushes the tanker sideways and can also cause side-to-side liquid surge inside the tank, compounding the force and significantly increasing the risk of rollover.'),
  ('What should a tanker driver do when entering a highway on-ramp?', 'Accelerate quickly to match highway speed', 'Slow down well below the posted ramp speed because the curve could cause a rollover', 'Maintain the posted ramp speed since it accounts for all vehicles', 'Use the shoulder if the ramp is too sharp', 'B', 'Tanker', 'medium', 'When entering a highway on-ramp, tanker drivers should slow down well below the posted ramp speed. On-ramps are curved, and the posted speed may be too fast for a tanker with its high center of gravity and liquid surge. Entering too fast could cause a rollover.'),
  ('How do baffles affect the cleaning of a tank?', 'They have no effect on cleaning', 'Baffles make the tank much harder to clean because they create areas that are difficult to wash and sanitize', 'Baffles make cleaning easier', 'Baffles automatically clean the tank', 'B', 'Tanker', 'medium', 'Baffles make the tank much harder to clean because they create corners, crevices, and areas behind the baffle walls that are difficult to reach with cleaning equipment. This is why sanitation regulations prohibit baffles in tanks used for food-grade products like milk.'),
  ('Why should you avoid pumping the brakes when driving a tanker vehicle?', 'It wears out the brake pads faster', 'Each brake release and reapplication can worsen liquid surge effects', 'It uses more air pressure', 'Pumping brakes is actually recommended for tankers', 'B', 'Tanker', 'medium', 'Pumping the brakes on a tanker should be avoided because each time you release and reapply the brakes, the liquid surge can push the vehicle forward during the release phase. Instead, apply steady brake pressure to maintain control.');
INSERT INTO questions (question_text, option_a, option_b, option_c, option_d, correct_answer, category, difficulty, explanation) VALUES
  ('What tests are required to obtain a Passenger (P) endorsement on your CDL?', 'Only a knowledge (written) test', 'No additional tests beyond the basic CDL', 'Both a knowledge test and a skills test', 'Only a skills (driving) test', 'C', 'Passenger', 'medium', 'A Passenger endorsement requires BOTH a knowledge (written) test and a skills test performed in a representative passenger vehicle.'),
  ('When must a driver perform a pre-trip inspection on a passenger vehicle?', 'Before driving the vehicle each day', 'Only on the first trip of the week', 'Only when passengers report a problem', 'Only before long-distance trips', 'A', 'Passenger', 'medium', 'A thorough pre-trip inspection must be performed before driving any commercial vehicle each day to ensure it is safe for passenger transport.'),
  ('What is required after completing the last trip of the day in a passenger vehicle?', 'A verbal report to the dispatcher', 'Nothing, pre-trip inspections are sufficient', 'Only a report if defects were found', 'A written post-trip inspection report', 'D', 'Passenger', 'medium', 'Drivers must complete a written post-trip inspection report after the last trip each day, even if no defects are found, documenting the condition of the vehicle.'),
  ('What is the standee line on a bus?', 'A line painted on the exterior of the bus', 'A 2-inch line on the floor showing where passengers may not stand forward of', 'A line showing the maximum passenger capacity', 'A line near the emergency exit', 'B', 'Passenger', 'medium', 'The standee line is a 2-inch line on the floor of the bus. Passengers must not stand forward of the rear of the driver''s seat, as indicated by this line.'),
  ('Passengers are not allowed to stand forward of which point on the bus?', 'The rear of the driver''''s seat', 'The front door', 'The windshield', 'The front axle', 'A', 'Passenger', 'medium', 'No passenger may stand forward of the rear of the driver''s seat. The standee line on the floor marks this boundary for passengers who are standing.'),
  ('When is it acceptable to refuel a bus with passengers on board?', 'When the fuel tank is nearly empty', 'During short scheduled rest stops', 'Only if the engine is turned off first', 'Never — passengers must never be on board during refueling', 'D', 'Passenger', 'medium', 'You must never refuel a bus with passengers aboard. Passengers must be discharged before refueling to prevent exposure to fuel fumes and fire hazards.'),
  ('Where should you never refuel a bus?', 'At a truck stop', 'In an enclosed building or area', 'At a gas station with a canopy', 'On a slight downhill grade', 'B', 'Passenger', 'medium', 'Never refuel in an enclosed building or area. Fuel vapors can accumulate and create an explosion or fire hazard in enclosed spaces.'),
  ('What must be done with the engine when refueling a bus?', 'Turn it off completely', 'Keep it idling for quick departure', 'Rev it slightly to keep the battery charged', 'It does not matter as long as passengers are off', 'A', 'Passenger', 'medium', 'The engine must be turned off during refueling. Running the engine during refueling creates a fire and explosion risk from fuel vapors.'),
  ('When must the bus driver wear a seat belt?', 'Only on highways', 'At all times when driving', 'Only when carrying passengers', 'Only when driving over 40 mph', 'B', 'Passenger', 'medium', 'The driver must always wear a seat belt when driving. This is required at all times regardless of speed, road type, or whether passengers are aboard.'),
  ('At a railroad crossing, a bus must stop within what distance of the tracks?', '5 to 10 feet', '50 to 100 feet', '15 to 50 feet', '25 to 75 feet', 'C', 'Passenger', 'medium', 'Buses must stop between 15 and 50 feet before railroad tracks. The driver must then look and listen for approaching trains before proceeding.'),
  ('What must a bus driver do at a railroad crossing after stopping?', 'Open the door and look and listen for trains', 'Honk the horn three times', 'Flash the headlights', 'Wait 30 seconds then proceed', 'A', 'Passenger', 'medium', 'After stopping at a railroad crossing, the bus driver must open the door (and window if necessary) and look and listen in both directions for approaching trains before proceeding.'),
  ('How far before a drawbridge must a bus stop?', '15 feet', '25 feet', '50 feet', '100 feet', 'C', 'Passenger', 'medium', 'A bus must stop at least 50 feet before a drawbridge that does not have a signal or attendant controlling traffic. The driver must then open the door, look, and listen before proceeding.'),
  ('What should a bus driver do when stopped at a drawbridge?', 'Open the door, look, and listen before proceeding when safe', 'Honk twice and proceed slowly', 'Flash hazard lights and proceed when the bridge is fully down', 'Wait for an all-clear signal from the bridge operator', 'A', 'Passenger', 'medium', 'At a drawbridge, after stopping 50 feet before it, the driver must open the door, look, and listen to confirm it is safe to cross before proceeding.'),
  ('What is a brake-door interlock on a bus?', 'A device that applies the brakes when the door is open', 'A lock that secures the door during an emergency stop', 'A device that applies the brakes when the rear door opens', 'A manual lock connecting brakes to the steering wheel', 'A', 'Passenger', 'medium', 'A brake-door interlock is a device on newer buses that applies the brakes automatically when the door is open. It is designed to prevent the bus from moving while passengers board or exit.'),
  ('Should the brake-door interlock replace the parking brake?', 'Yes, it is a more modern and reliable system', 'No, never let the interlock replace the parking brake', 'Yes, if the interlock is functioning properly', 'Only if the bus is on level ground', 'B', 'Passenger', 'medium', 'The brake-door interlock should never be used as a substitute for the parking brake. Always set the parking brake when the bus is parked or when loading and unloading passengers.'),
  ('What must be kept clear at all times on a bus?', 'Only the front windshield', 'Only the emergency exits', 'The driver''''s area only', 'The aisle and doorways must be clear of baggage and obstructions', 'D', 'Passenger', 'medium', 'Aisles and doorways must be kept clear of baggage and any other obstructions at all times so passengers can move freely and evacuate quickly in an emergency.'),
  ('Why must baggage and freight be secured on a bus?', 'To prevent damage to the items', 'So that it does not block the aisle, exits, or become a hazard in an accident', 'To keep the bus properly balanced', 'For customs inspection purposes', 'B', 'Passenger', 'medium', 'Baggage and freight must be properly secured so they do not block the aisle or emergency exits and do not become projectiles during a sudden stop or accident.'),
  ('What information must a bus driver announce at each scheduled stop?', 'The location, destination, next stop, and reason for any delay', 'Only the name of the stop', 'Only the estimated time of arrival', 'Only the stop number', 'A', 'Passenger', 'medium', 'At stops, the driver must announce the location, the destination, the next stop, and the reason for any delay so passengers are properly informed.'),
  ('Which of the following items is prohibited on a bus?', 'Small personal luggage', 'Carry-on bags that fit under the seat', 'Boxed lunches', 'Hazardous materials in the passenger area', 'D', 'Passenger', 'medium', 'Hazardous materials are prohibited in the passenger area of a bus. Only small arms ammunition, emergency hospital supplies, and drugs specifically permitted by regulations may be transported.'),
  ('What must the driver do regarding emergency exits before starting a trip?', 'Lock all emergency exits', 'Explain and demonstrate the location and operation of emergency exits to passengers', 'Test each exit by fully opening it', 'Post a sign near each exit', 'B', 'Passenger', 'medium', 'Before starting, the driver should ensure passengers are aware of emergency exit locations and how to operate them. This information should be communicated clearly.'),
  ('How should the driver handle an unruly passenger?', 'Ignore the passenger and continue driving', 'Ask other passengers to restrain the person', 'Pull over and leave the bus', 'Stop the bus in a safe location and address the situation; contact authorities if necessary', 'D', 'Passenger', 'medium', 'If a passenger becomes unruly, the driver should stop the bus safely, address the issue calmly, and contact law enforcement if the situation cannot be resolved. Safety of all passengers is the priority.'),
  ('During a pre-trip inspection of a passenger vehicle, what should the driver specifically check?', 'Only the engine and tires', 'Passenger entry and emergency exits, interior lights, mirrors, and safety equipment', 'Only the brakes', 'Only the exterior lights', 'B', 'Passenger', 'medium', 'A pre-trip inspection for a passenger vehicle includes checking all standard items plus passenger-specific items such as entry and emergency exits, interior lights, mirrors, handrails, and safety equipment.'),
  ('What should a bus driver do if forced to evacuate the bus?', 'Direct passengers to the nearest safe exit, including emergency windows and roof hatches', 'Tell passengers to exit through the front door only', 'Wait for emergency services before evacuating', 'Exit the bus first and then call for help', 'A', 'Passenger', 'medium', 'During an emergency evacuation, the driver should direct passengers to the nearest safe exit, which can include the front and rear doors, emergency windows, and roof hatches.'),
  ('What are roof hatches on a bus used for?', 'Ventilation only', 'Storage access points', 'As emergency exits and for ventilation', 'Satellite antenna mounts', 'C', 'Passenger', 'medium', 'Roof hatches serve dual purposes: they provide ventilation during normal operation and serve as emergency exits if other exits are blocked or unusable.'),
  ('Where should fire extinguishers be located on a bus?', 'In the trunk compartment only', 'Under each passenger seat', 'In the engine compartment only', 'In an accessible location near the driver', 'D', 'Passenger', 'medium', 'Fire extinguishers must be in a readily accessible and visible location, typically near the driver, so they can be quickly reached in case of a fire.'),
  ('What type of fire extinguisher is typically required on a bus?', 'Water-based only', 'A B:C rated dry chemical extinguisher at minimum', 'CO2 extinguisher only', 'No specific type is required', 'B', 'Passenger', 'medium', 'Buses must carry at least a B:C rated dry chemical fire extinguisher. This type is effective against flammable liquid and electrical fires, which are the most common hazards on a bus.'),
  ('If a fire breaks out on a bus, what should the driver do first?', 'Continue driving to the nearest fire station', 'Pull over safely, evacuate passengers, and then attempt to suppress the fire', 'Open all windows to ventilate', 'Let passengers decide what to do', 'B', 'Passenger', 'medium', 'The driver must pull over to a safe location and evacuate all passengers immediately. Once passengers are safe, the driver may attempt to fight the fire with the onboard extinguisher if it is small enough.'),
  ('When checking brakes during a pre-trip inspection on a bus, what should you verify?', 'Only that the pedal feels firm', 'Only the parking brake holds', 'Only that the brake lights work', 'Brake adjustment, air pressure levels, low-pressure warning device, and brake-door interlock operation', 'D', 'Passenger', 'medium', 'A thorough brake check includes verifying proper adjustment, adequate air pressure, operation of the low-pressure warning device, and on buses with a brake-door interlock, that it functions correctly.'),
  ('What does ABS (Anti-Lock Braking System) do on a bus?', 'Reduces stopping distance significantly', 'Prevents wheel lockup during hard braking, helping the driver maintain steering control', 'Eliminates the need for air brakes', 'Automatically stops the bus at railroad crossings', 'B', 'Passenger', 'medium', 'ABS prevents the wheels from locking up during hard braking, which helps the driver maintain steering control. It does not necessarily shorten stopping distance but does improve directional stability.'),
  ('If your bus has ABS, how should you brake in an emergency?', 'Pump the brakes rapidly', 'Tap the brakes lightly and steer sharply', 'Slam the brakes and release repeatedly', 'Apply steady, firm pressure to the brake pedal', 'D', 'Passenger', 'medium', 'With ABS, apply firm, steady pressure to the brake pedal. Do not pump the brakes — the ABS system will automatically modulate brake pressure to prevent wheel lockup.'),
  ('What is a key difference between urban and intercity bus operations?', 'Urban buses make frequent stops and are more likely to carry standees; intercity buses travel longer distances with all passengers seated', 'Urban buses never carry standing passengers', 'Intercity buses do not require pre-trip inspections', 'There is no operational difference', 'A', 'Passenger', 'medium', 'Urban (transit) buses make frequent stops and commonly have standing passengers. Intercity buses travel longer distances between stops and generally require all passengers to be seated.'),
  ('What must you ensure regarding wheelchair accessibility on a bus?', 'Wheelchair passengers must transfer to a regular seat', 'Wheelchairs are not permitted on buses', 'Wheelchair lifts and securement devices must be in working order and properly used', 'Only manual wheelchairs are allowed', 'C', 'Passenger', 'medium', 'Wheelchair lifts, ramps, and securement devices must be inspected during pre-trip and must be in proper working condition. Wheelchair passengers must be properly secured using the provided equipment.'),
  ('When loading passengers who use wheelchairs, what should the driver do?', 'Properly operate the lift or ramp and secure the wheelchair using all provided securement devices', 'Ask another passenger to assist', 'Allow the passenger to board without assistance', 'Tell the passenger to wait for a special vehicle', 'A', 'Passenger', 'medium', 'The driver must properly operate the wheelchair lift or ramp and ensure the wheelchair is fully secured using all securement straps and devices before the bus moves.'),
  ('What should the driver check regarding seats and handrails during the pre-trip inspection?', 'That they match the bus color scheme', 'That seat covers are clean', 'That seats are securely fastened and handrails are firmly mounted and undamaged', 'Only that the driver''''s seat adjusts properly', 'C', 'Passenger', 'medium', 'During the pre-trip inspection, the driver must verify that passenger seats are securely fastened to the floor and that handrails and stanchions are firmly attached and free of damage.'),
  ('Which of the following is NOT a reason to evacuate a bus?', 'An engine fire', 'The bus is stalled on railroad tracks', 'A minor disagreement between passengers', 'Hazardous material spill near the bus', 'C', 'Passenger', 'medium', 'A minor disagreement between passengers does not warrant evacuation. Evacuation is necessary for life-threatening situations such as fire, the bus being stuck on railroad tracks, or nearby hazardous material incidents.'),
  ('What is the proper procedure for unloading passengers?', 'Open the door and let passengers exit while the bus is still rolling', 'Stop only if requested by passengers', 'Allow passengers to exit from the rear emergency door at every stop', 'Come to a complete stop, set the parking brake, then allow passengers to exit safely', 'D', 'Passenger', 'medium', 'The driver must bring the bus to a complete stop and set the parking brake before opening the door to allow passengers to exit. This ensures the bus will not move unexpectedly.'),
  ('How should carry-on baggage be stored on a bus?', 'On the floor in the aisle', 'In overhead racks or under seats so it does not block the aisle or exits', 'On empty passenger seats only', 'Stacked near the front entrance', 'B', 'Passenger', 'medium', 'Carry-on baggage should be stored in overhead racks or under seats to keep aisles and exits clear. Baggage must never block the aisle, doorway, or emergency exits.'),
  ('What items are passengers forbidden from bringing aboard a bus?', 'Hazardous materials, weapons, and items that could endanger passengers', 'Personal electronics', 'Food and beverages', 'Newspapers and magazines', 'A', 'Passenger', 'medium', 'Passengers are forbidden from bringing hazardous materials, weapons, and any items that could pose a danger to the driver or other passengers aboard the bus.'),
  ('How can the driver tell if the bus has an Anti-Lock Braking System?', 'By pumping the brakes and feeling for pulsation', 'By looking under the bus for extra brake lines', 'By checking for a yellow ABS warning light on the dashboard', 'ABS-equipped buses have a special horn', 'C', 'Passenger', 'medium', 'Buses equipped with ABS have a yellow ABS malfunction lamp on the instrument panel. The light comes on briefly at startup as a bulb check and should then turn off if the system is functioning properly.'),
  ('What should you do if the ABS warning light stays on while driving?', 'Pull over immediately and refuse to drive', 'Pump the brakes to reset the system', 'Disconnect the ABS fuse', 'Continue to drive normally since you still have regular brakes, but have the ABS serviced soon', 'D', 'Passenger', 'medium', 'If the ABS light stays on, the underlying braking system still works normally. You can continue driving but should have the ABS inspected and repaired as soon as possible.'),
  ('At what point during the trip should the driver check mirrors?', 'Only before starting the trip', 'Only when changing lanes', 'Frequently throughout the trip to monitor passengers and traffic', 'Only when backing up', 'C', 'Passenger', 'medium', 'The driver should check mirrors frequently during the trip to monitor traffic conditions around the bus and to keep an eye on passenger activity inside the bus.'),
  ('What is the proper way to handle a passenger who refuses to follow safety rules?', 'Physically remove the passenger from the bus', 'Explain the rules firmly, and if the passenger still refuses, stop at a safe location and contact authorities', 'Ignore the situation and keep driving', 'Ask other passengers to enforce the rules', 'B', 'Passenger', 'medium', 'If a passenger refuses to follow safety rules, the driver should calmly but firmly explain the requirement. If the passenger continues to refuse, stop at a safe location and contact dispatch or law enforcement.'),
  ('Why must you stop at railroad crossings when driving a bus?', 'Only if the warning lights are flashing', 'Only if passengers request it', 'Because buses are required by law to stop at all railroad crossings, regardless of signals', 'Only during nighttime hours', 'C', 'Passenger', 'medium', 'Federal and state laws require buses to stop at railroad crossings every time, regardless of whether signals are active. This is because of the catastrophic risk a train collision poses to many passengers.'),
  ('After stopping at a railroad crossing, when may you proceed?', 'After counting to ten', 'As soon as you open the door', 'After honking your horn twice', 'Only when you are sure no train is approaching and you can clear the tracks completely', 'D', 'Passenger', 'medium', 'You may proceed across the tracks only after you have opened the door, looked and listened in both directions, and confirmed no train is approaching and that there is room to completely clear the tracks on the other side.'),
  ('What should a driver do if the bus stalls on railroad tracks?', 'Evacuate passengers immediately and move them away from the tracks at a 45-degree angle toward the approaching train direction', 'Try to restart the engine repeatedly', 'Wait inside the bus for help', 'Call the railroad company before evacuating', 'A', 'Passenger', 'medium', 'If the bus stalls on tracks, evacuate immediately. Move passengers away from the tracks at a 45-degree angle toward the direction from which a train would come, so debris from a collision moves away from them.'),
  ('When are standing passengers (standees) prohibited on a bus?', 'On buses traveling on the highway or interstate at highway speeds', 'Standees are always allowed on all buses', 'Only during nighttime', 'Only during rain', 'A', 'Passenger', 'medium', 'Standing passengers are generally prohibited on buses operating at highway speeds. If standing is permitted, passengers must stay behind the standee line and not stand forward of the rear of the driver''s seat.'),
  ('What must be included in a post-trip inspection report?', 'Only a verbal description to the next driver', 'A phone call to the maintenance shop', 'A written report noting the condition of the vehicle and any defects found or the absence of defects', 'A video recording of the bus', 'C', 'Passenger', 'medium', 'A written post-trip inspection report is required each day. It must document the condition of key components and note any defects found, or state that no defects were found.'),
  ('What should the next driver do with the previous driver''s post-trip inspection report?', 'Throw it away and start fresh', 'File it without reading it', 'Give it to the passengers', 'Review it and sign it, acknowledging the reported conditions and verifying repairs were made for any noted defects', 'D', 'Passenger', 'medium', 'The next driver must review the previous post-trip inspection report, verify that any reported defects have been repaired or are safe to operate with, and sign the report to acknowledge they have reviewed it.'),
  ('How should a bus driver approach a curve while carrying passengers?', 'Speed up to maintain momentum', 'Brake hard in the middle of the curve', 'Slow down before the curve and avoid braking while in the curve to keep passengers safe and comfortable', 'Maintain the same speed throughout', 'C', 'Passenger', 'medium', 'The driver should slow down before entering a curve and avoid braking while in the curve. This provides a smoother ride and prevents passengers, especially standees, from losing their balance.'),
  ('What special considerations apply to charter bus operations?', 'Charter buses are exempt from DOT regulations', 'Charter bus drivers do not need a P endorsement', 'Charter buses never make stops', 'Charter buses follow the same rules but the driver must account for passengers who may be unfamiliar with bus safety procedures', 'D', 'Passenger', 'medium', 'Charter bus operations follow the same safety rules as regular routes. However, drivers must take extra care because charter passengers may be less familiar with bus emergency exits, rules, and safety procedures.');
